INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23016, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "没有用的东西。", "primary_collocate": null, "pronunciation": "fèi wù", "ipa": "fei˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "这些旧报纸是废物，请把它们扔掉。", "target_word": "废物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的废物要放进垃圾桶。", "target_word": "废物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂把废物倒进了河里，鱼都死了。", "target_word": "废物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得这台坏电脑是废物，不想再修了。", "target_word": "废物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把有用的东西当成废物。", "target_word": "废物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里堆着很多废物，该打扫了。", "target_word": "废物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些废物可以回收，做成新的东西。", "target_word": "废物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，家里不要的废物都可以卖掉。", "target_word": "废物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明用废物做了一个小机器人。", "target_word": "废物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些东西没用，只是一堆废物。", "target_word": "废物", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "堆", "label": "量词"}, {"form": "废物利用", "label": "复合"}, {"form": "廢物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "没有用、该扔掉的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebcaa39-880a-494e-9b7b-c3edf04ba17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23016, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "废物", "is_correct": true, "explanation": "废物：指没有用、应该扔掉的东西，与“请把它们扔掉”搭配，符合句意。"}, {"text": "宝贝", "is_correct": false, "explanation": "语义：“宝贝”指珍贵的东西，不应该扔掉，与后句“请把它们扔掉”矛盾。"}, {"text": "证据", "is_correct": false, "explanation": "语义：“证据”是有用的东西，不能随便扔掉，与后句矛盾。"}, {"text": "证件", "is_correct": false, "explanation": "搭配：“旧报纸是证件”的说法不成立，“证件”通常不指报纸。"}], "explanations": {"废物": "废物：指没有用、应该扔掉的东西，与“请把它们扔掉”搭配，符合句意。", "宝贝": "语义：“宝贝”指珍贵的东西，不应该扔掉，与后句“请把它们扔掉”矛盾。", "证据": "语义：“证据”是有用的东西，不能随便扔掉，与后句矛盾。", "证件": "搭配：“旧报纸是证件”的说法不成立，“证件”通常不指报纸。"}, "sentence_index": 0, "correct_answer": "废物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市经过地震后，变成了一片废物。", "explanation": "这里应该用〈废墟〉。废墟指倒塌后的残余建筑；“废物”指没有用的东西，不能用来指一片地方。"}, {"text": "他在院子里种了一片废物，绿绿的很好看。", "explanation": "这里应该用〈草坪〉。“种”的对象是植物，草坪可以种，看起来绿绿的；“废物”是没有用的东西，不能被种植。"}, {"text": "考古队在山里发现了一处古代废物。", "explanation": "这里应该用〈遗址〉。遗址指古代人活动留下的地方；“废物”不指古迹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "废物", "is_correct": true, "explanation": "废物：指可以回收利用的废弃物，符合“可以回收，做成新的东西”的句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是废弃物，不能被回收后做成新东西，句意不通。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：“回收”一般用于物品，不能用于人。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不能被回收，也不能做成新东西。"}], "explanations": {"废物": "废物：指可以回收利用的废弃物，符合“可以回收，做成新的东西”的句意。", "空气": "语义：空气不是废弃物，不能被回收后做成新东西，句意不通。", "老师": "搭配：“回收”一般用于物品，不能用于人。", "大海": "语义：大海不能被回收，也不能做成新东西。"}, "sentence_index": 6, "correct_answer": "废物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里有一本废物，该清理了。", "explanation": "量词错误：一堆废物应该用〈堆〉。“本”用于书册，不能用来数废物。"}, {"text": "仓库里放着一条废物。", "explanation": "量词错误：这里应该用〈堆〉。“条”多用于细长的东西，不用来数废物。"}, {"text": "车间角落里有一张废物。", "explanation": "量词错误：这里应该用〈堆〉。“张”用于平面的东西，不用来数废物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨房里的一张废物要放进垃圾桶。", "corrected_sentence": "厨房里的一堆废物要放进垃圾桶。", "error_description": "错误：“张”用于平面的东西，不能用来数废物。正确：应说“一堆废物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批地废物以前被回收过。", "corrected_sentence": "这批废物以前被回收过。", "error_description": "错误：“地”用于修饰动词或形容词，不能修饰名词“废物”。正确：直接写作“这批废物以前被回收过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23018, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消极", "is_correct": true, "explanation": "消极：与“积极”相对，指不主动、不努力。"}, {"text": "冷静", "is_correct": false, "explanation": "无关：“冷静”指不慌乱，与“积极”之间不构成反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "无关：“复杂”形容事物头绪多，与“积极”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”形容明白，与“积极”不构成反义关系。"}], "correct_answer": "消极", "explanations": {"消极": "消极：与“积极”相对，指不主动、不努力。", "冷静": "无关：“冷静”指不慌乱，与“积极”之间不构成反义关系。", "复杂": "无关：“复杂”形容事物头绪多，与“积极”没有反义关系。", "清楚": "无关：“清楚”形容明白，与“积极”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23018, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消极", "is_correct": true, "explanation": "消极：与“积极”相对，指不主动、不努力。"}, {"text": "善良", "is_correct": false, "explanation": "无关：“善良”形容心地好，与“积极”没有反义关系。"}, {"text": "辽阔", "is_correct": false, "explanation": "无关：“辽阔”形容面积广大，与“积极”不构成反义关系。"}, {"text": "陈旧", "is_correct": false, "explanation": "无关：“陈旧”指旧的、不新鲜，与“积极”不构成反义关系。"}], "correct_answer": "消极", "explanations": {"消极": "消极：与“积极”相对，指不主动、不努力。", "善良": "无关：“善良”形容心地好，与“积极”没有反义关系。", "辽阔": "无关：“辽阔”形容面积广大，与“积极”不构成反义关系。", "陈旧": "无关：“陈旧”指旧的、不新鲜，与“积极”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23018, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指做事很努力，或者态度让人感觉很好。", "primary_collocate": null, "pronunciation": "jī jí", "ipa": "tɕi⁵⁵ tɕi³⁵", "syllable_count": 2, "sentences": [{"text": "他学习很积极。", "target_word": "积极", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她总是积极举手回答问题。", "target_word": "积极", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要用积极的态度面对困难。", "target_word": "积极", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王工作积极，老板很喜欢他。", "target_word": "积极", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都积极参加了今天的活动。", "target_word": "积极", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对这件事很积极。", "target_word": "积极", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "听了老师的话，他变得更积极了。", "target_word": "积极", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是一个很积极的人。", "target_word": "积极", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们积极地帮老师搬桌子。", "target_word": "积极", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛前，大家都积极准备着。", "target_word": "积极", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "积极性", "label": "复合"}], "register": "中性", "sense_fingerprint": "做事努力主动；态度正面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '449b634c-ae74-4ccb-8934-b82cc0828b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23018, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "积极", "is_correct": true, "explanation": "积极：做事努力主动，与“学习很……”搭配自然。"}, {"text": "美丽", "is_correct": false, "explanation": "语义：“美丽”形容外貌好看，不能用来形容学习的态度。"}, {"text": "慷慨", "is_correct": false, "explanation": "语义：“慷慨”指大方给予财物或帮助，不能用来形容学习。"}, {"text": "冷淡", "is_correct": false, "explanation": "配价：“冷淡”需要带“对”引出对象，应说“对学习很冷淡”，直接说“学习很冷淡”不成立。"}], "explanations": {"积极": "积极：做事努力主动，与“学习很……”搭配自然。", "美丽": "语义：“美丽”形容外貌好看，不能用来形容学习的态度。", "慷慨": "语义：“慷慨”指大方给予财物或帮助，不能用来形容学习。", "冷淡": "配价：“冷淡”需要带“对”引出对象，应说“对学习很冷淡”，直接说“学习很冷淡”不成立。"}, "sentence_index": 0, "correct_answer": "积极"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯咖啡很积极。", "explanation": "这里应该用〈好喝〉。积极形容人做事的态度和行动，不用来形容饮料的味道。"}, {"text": "这家公司的产品很积极。", "explanation": "这里应该用〈优秀〉。积极只描述人的做事态度和行动，不用于形容产品。"}, {"text": "他很积极地叹了口气。", "explanation": "这里应该用〈失望〉。积极表示主动做事，叹气是不由自主的情绪反应，不能用积极修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "积极", "is_correct": true, "explanation": "积极：做事态度变得主动，符合“变得更……了”的语境。"}, {"text": "深", "is_correct": false, "explanation": "语义：“深”形容距离或程度，用于人的变化不自然。"}, {"text": "长", "is_correct": false, "explanation": "搭配：“长”指长度，不能用来形容人的状态变化。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：“粗糙”可指做事粗疏，但与“听了老师的话，他变得更……了”所描述的积极转变语义相反。"}], "explanations": {"积极": "积极：做事态度变得主动，符合“变得更……了”的语境。", "深": "语义：“深”形容距离或程度，用于人的变化不自然。", "长": "搭配：“长”指长度，不能用来形容人的状态变化。", "粗糙": "语义：“粗糙”可指做事粗疏，但与“听了老师的话，他变得更……了”所描述的积极转变语义相反。"}, "sentence_index": 6, "correct_answer": "积极"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很积极地逃避困难。", "explanation": "这里应该用〈消极〉。积极表示主动投入，逃避是消极的行为，与“积极”语义相反。"}, {"text": "这间教室很积极。", "explanation": "这里应该用〈安静〉。积极只形容人的态度和行动，不用于描述教室。"}, {"text": "他很积极地哭了一场。", "explanation": "这里应该用〈伤心〉。积极形容主动的行为，哭泣是不由自主的情绪，不能用积极修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一个非常积极同事。", "corrected_sentence": "她是一个非常积极的同事。", "error_description": "错误形式：“积极同事”。正确形式：“积极的同事”。形容词“积极”修饰名词时，中间需要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他工作得很积极地。", "corrected_sentence": "他工作得很积极。", "error_description": "错误形式：“工作得很积极地”。正确形式：“工作得很积极”。“积极”作补语时，后面不加“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
