INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23026, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "极小的，肉眼看不见的。", "primary_collocate": null, "pronunciation": "wēi guān", "ipa": "weɪ˥ kwan˥", "syllable_count": 2, "sentences": [{"text": "显微镜让我们看到微观世界。", "target_word": "微观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原子是微观粒子。", "target_word": "微观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家研究微观世界。", "target_word": "微观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水由分子组成，分子属于肉眼看不见的微观世界。", "target_word": "微观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "微观世界里有很多我们看不见的东西。", "target_word": "微观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片拍的是微观世界。", "target_word": "微观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用图片给我们介绍微观结构。", "target_word": "微观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "细菌是肉眼看不见的微观生物。", "target_word": "微观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对微观世界特别感兴趣。", "target_word": "微观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子显微镜能让我们看到微观的细胞结构。", "target_word": "微观", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "微观世界", "label": "复合"}, {"form": "微观粒子", "label": "复合"}], "register": "中性", "sense_fingerprint": "极小，肉眼看不见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245aa18a-045a-46cc-b4fa-b7de9581fe19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23026, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "微观", "is_correct": true, "explanation": "正确：微观（wēi guān），指很小、肉眼看不见的。"}, {"text": "围观", "is_correct": false, "explanation": "wéi（第二声）与 wēi（第一声）声调不同，意思是许多人围着看热闹，不是很小。"}, {"text": "微管", "is_correct": false, "explanation": "guǎn（第三声）与 guān（第一声）声调不同，意思是细胞里的一种细小管状结构。"}, {"text": "维管", "is_correct": false, "explanation": "wéi guǎn 与 wēi guān 两个字声调都不同，意思是植物体内输送水分的管状组织。"}], "explanations": {"微观": "正确：微观（wēi guān），指很小、肉眼看不见的。", "围观": "wéi（第二声）与 wēi（第一声）声调不同，意思是许多人围着看热闹，不是很小。", "微管": "guǎn（第三声）与 guān（第一声）声调不同，意思是细胞里的一种细小管状结构。", "维管": "wéi guǎn 与 wēi guān 两个字声调都不同，意思是植物体内输送水分的管状组织。"}, "sentence_index": null, "correct_answer": "微观"}, "level_3": {"options": [{"text": "微观", "is_correct": true, "explanation": "正确：「显微镜让我们看到微观世界」中，「微观」指肉眼看不见的极小世界。"}, {"text": "遥远", "is_correct": false, "explanation": "语义：显微镜看的是极小的东西，看不到遥远的世界。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：「嘈杂」指声音乱，显微镜是用来看极小东西的，看不到嘈杂的世界。"}, {"text": "辽阔", "is_correct": false, "explanation": "语义：「辽阔」指空间很大，显微镜看到的不是辽阔的世界。"}], "explanations": {"微观": "正确：「显微镜让我们看到微观世界」中，「微观」指肉眼看不见的极小世界。", "遥远": "语义：显微镜看的是极小的东西，看不到遥远的世界。", "嘈杂": "语义：「嘈杂」指声音乱，显微镜是用来看极小东西的，看不到嘈杂的世界。", "辽阔": "语义：「辽阔」指空间很大，显微镜看到的不是辽阔的世界。"}, "sentence_index": 0, "correct_answer": "微观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这颗钉子很微观。", "explanation": "这里应该用〈细小〉。「微观」指肉眼看不见的极小世界，不用来形容肉眼可见的钉子。"}, {"text": "他的脾气很微观。", "explanation": "语义：「微观」指肉眼看不见的极小事物，不能用来形容脾气。"}, {"text": "这座山很微观。", "explanation": "这里应该用〈高大〉。「微观」指肉眼看不见的极小事物，不用来形容山。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23026, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "微观", "is_correct": true, "explanation": "正确：微观（wēi guān），指很小、肉眼看不见的。"}, {"text": "微光", "is_correct": false, "explanation": "guāng 与 guān 韵母不同（多一个后鼻音 ng），意思是很微弱的光。"}, {"text": "外观", "is_correct": false, "explanation": "wài 与 wēi 韵母和声调不同，guān 相同，意思是东西外表的样子。"}, {"text": "尾管", "is_correct": false, "explanation": "wěi guǎn（第三声、第三声）与 wēi guān（第一声、第一声）声调不同，意思是车尾的排气管。"}], "explanations": {"微观": "正确：微观（wēi guān），指很小、肉眼看不见的。", "微光": "guāng 与 guān 韵母不同（多一个后鼻音 ng），意思是很微弱的光。", "外观": "wài 与 wēi 韵母和声调不同，guān 相同，意思是东西外表的样子。", "尾管": "wěi guǎn（第三声、第三声）与 wēi guān（第一声、第一声）声调不同，意思是车尾的排气管。"}, "sentence_index": null, "correct_answer": "微观"}, "level_3": {"options": [{"text": "微观", "is_correct": true, "explanation": "正确：「老师用图片给我们介绍微观结构」中，「微观结构」指极小的结构。"}, {"text": "甜", "is_correct": false, "explanation": "语义：「甜」指味道，不能用来修饰结构。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：「响亮」形容声音，不用来修饰结构。"}, {"text": "辣", "is_correct": false, "explanation": "语义：「辣」指味觉，不能用来修饰结构。"}], "explanations": {"微观": "正确：「老师用图片给我们介绍微观结构」中，「微观结构」指极小的结构。", "甜": "语义：「甜」指味道，不能用来修饰结构。", "响亮": "搭配：「响亮」形容声音，不用来修饰结构。", "辣": "语义：「辣」指味觉，不能用来修饰结构。"}, "sentence_index": 6, "correct_answer": "微观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间教室很微观。", "explanation": "这里应该用〈宽敞〉。「微观」指极小、肉眼看不见，不用来描述空间的大小。"}, {"text": "这座微观的寺庙很有名。", "explanation": "这里应该用〈小巧〉。「微观」指肉眼看不见的极小事物，寺庙不会小到这种程度，应说〈小巧〉。"}, {"text": "这首歌的旋律很微观。", "explanation": "这里应该用〈动听〉。「微观」指肉眼看不见的极小事物，不用来形容旋律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究人员用仪器观察微观地结构。", "corrected_sentence": "研究人员用仪器观察微观的结构。", "error_description": "的/地误用：错误形式为「地」，正确形式为「的」，「微观」修饰名词「结构」要用「的」，「地」用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这门课讲的是很微观世界的规律。", "corrected_sentence": "这门课讲的是微观世界的规律。", "error_description": "程度副词误用：错误形式为「很微观世界」，正确形式为「微观世界」。「微观世界」是复合词，「很」不能插在「微观」和「世界」之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
