INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23028, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "层面是指事物的一部分或一个方面。", "primary_collocate": null, "pronunciation": "céng miàn", "ipa": "tsʰɤŋ˧˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这个问题要从两个层面看。", "target_word": "层面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在技术层面，我们已经没有问题了。", "target_word": "层面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从法律层面说，这样做不对。", "target_word": "层面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在思想层面比同学成熟。", "target_word": "层面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先谈谈经济层面的问题。", "target_word": "层面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要在制度层面做出改变。", "target_word": "层面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事在个人层面和社会层面都有影响。", "target_word": "层面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格只是一个层面，质量也很重要。", "target_word": "层面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从心理层面看，孩子需要安全感。", "target_word": "层面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议讨论了管理层面的几个问题。", "target_word": "层面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "層面", "label": "繁体"}, {"form": "个", "label": "量词"}, {"form": "社会层面", "label": "复合"}, {"form": "技术层面", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物的某一方面或某一个层次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662c7823-51e1-46b7-b4e3-759c04a652e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子是器物，不是可以从中观察问题的方面，句意不通。"}, {"text": "层面", "is_correct": true, "explanation": "正确：层面指事物的一个方面，“从两个层面看”即从两个方面看问题。"}, {"text": "房间", "is_correct": false, "explanation": "语义：“房间”是空间，不能作为看问题的角度，“从两个房间看”说不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是器物，不能作为看问题的角度，“从两个书包看”说不通。"}], "explanations": {"桌子": "语义：桌子是器物，不是可以从中观察问题的方面，句意不通。", "层面": "正确：层面指事物的一个方面，“从两个层面看”即从两个方面看问题。", "房间": "语义：“房间”是空间，不能作为看问题的角度，“从两个房间看”说不通。", "书包": "语义：“书包”是器物，不能作为看问题的角度，“从两个书包看”说不通。"}, "sentence_index": 0, "correct_answer": "层面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子的层面很光滑。", "explanation": "这里应该用〈表面〉。层面指事物的一个方面或层次，描述物体的外表要用表面。"}, {"text": "这家餐厅的层面很亮。", "explanation": "这里应该用〈光线〉。层面指事物的方面或层次，房间明暗要说“光线”，不能用“层面”。"}, {"text": "这间房子的层面很大。", "explanation": "这里应该用〈面积〉。层面不指平面的大小，说房子的大小要用面积。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不能作为个人的一个方面，句意不通。"}, {"text": "层面", "is_correct": true, "explanation": "正确：“个人层面”与“社会层面”并列，指两个方面，句意通顺。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“个人”修饰的一般是利益、生活等，“钢琴”是器物，不能说“个人钢琴”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能作为个人的一个方面，句意不通。"}], "explanations": {"老虎": "语义：老虎是动物，不能作为个人的一个方面，句意不通。", "层面": "正确：“个人层面”与“社会层面”并列，指两个方面，句意通顺。", "钢琴": "搭配：“个人”修饰的一般是利益、生活等，“钢琴”是器物，不能说“个人钢琴”。", "天气": "语义：天气是自然现象，不能作为个人的一个方面，句意不通。"}, "sentence_index": 6, "correct_answer": "层面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个西瓜的层面很高，吃起来特别甜。", "explanation": "这里应该用〈甜度〉。层面指事物的方面或层次，西瓜有多甜要说“甜度很高”，不能用“层面”。"}, {"text": "他的围棋层面很快，一会儿就下完了。", "explanation": "这里应该用〈速度〉。层面指事物的方面或层次，下棋的快慢要说“速度”，不能用“层面”。"}, {"text": "这座山的层面很高。", "explanation": "这里应该用〈高度〉。层面不指高低、高矮的尺寸，说山的高低要用高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要从三只层面来分析这个问题。", "corrected_sentence": "我们要从三个层面来分析这个问题。", "error_description": "量词错误：“层面”的量词应为“个”，“只”用于动物，不能用来数层面。正确说法是“三个层面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事有两根层面，需要分开看。", "corrected_sentence": "这件事有两个层面，需要分开看。", "error_description": "量词错误：“层面”应用量词“个”，“根”用于细长的东西，不能用来数层面。正确说法：这件事有两个层面，需要分开看。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
