INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23032, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西不集中在一个地方，而是分开放到很多地方。", "primary_collocate": null, "pronunciation": "fēn bù shì", "ipa": "fən˥ pu˥˩ ʂʅ˥˩", "syllable_count": 3, "sentences": [{"text": "这个公司用分布式系统存资料。", "target_word": "分布式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些服务器采用分布式结构，放在不同的城市。", "target_word": "分布式", "complexity_tier": "T3", "furigana": "zhè xiē fú wù qì cǎi yòng fēn bù shì jié gòu, fàng zài bù tóng de chéng shì.", "sentence_source": "generated"}, {"text": "分布式的数据不在同一个地方。", "target_word": "分布式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们开发了一个分布式数据库。", "target_word": "分布式", "complexity_tier": "T3", "furigana": "tā men kāi fā le yí gè fēn bù shì shù jù kù.", "sentence_source": "generated"}, {"text": "分布式系统比一台电脑更安全。", "target_word": "分布式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行的分布式系统有很多服务器。", "target_word": "分布式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王在学分布式技术。", "target_word": "分布式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分布式办公让大家在家也能工作。", "target_word": "分布式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把文件放在分布式的网络里。", "target_word": "分布式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分布式发电让每个小区都有电。", "target_word": "分布式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分布式系统", "label": "复合"}, {"form": "分布式计算", "label": "复合"}, {"form": "分佈式", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不集中在一处，而是分开放在很多地方的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40c6bb68-9edb-4a24-ad31-cf0cde640a3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23032, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可爱", "is_correct": false, "explanation": "搭配：“可爱”形容人或动物，不能修饰“系统”。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”指没有声音或很平和，与“用系统存资料”的语境不合。"}, {"text": "分布式", "is_correct": true, "explanation": "正确。“分布式”指资料分开放在多台机器上，符合“用分布式系统存资料”的句意。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道，与“系统”没有关系。"}], "explanations": {"可爱": "搭配：“可爱”形容人或动物，不能修饰“系统”。", "安静": "语义：“安静”指没有声音或很平和，与“用系统存资料”的语境不合。", "分布式": "正确。“分布式”指资料分开放在多台机器上，符合“用分布式系统存资料”的句意。", "咸": "语义：“咸”指味道，与“系统”没有关系。"}, "sentence_index": 0, "correct_answer": "分布式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "分布式的同学都来了。", "explanation": "这里应该用〈分散〉。「分布式」指系统或资源的存放结构，不能形容人；人分散在各地要说「分散」。"}, {"text": "他有一种分布式的性格，朋友都很喜欢他。", "explanation": "这里应该用〈复杂〉。「分布式」指东西分放在多处，不能形容性格；形容性格多面要说「复杂」。"}, {"text": "这辆汽车很分布式。", "explanation": "这里应该用〈快〉。「分布式」只指东西分放在多处，不能形容汽车的快慢；形容速度要说「快」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23032, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温柔", "is_correct": false, "explanation": "搭配：“温柔”形容人的性情，不能修饰“技术”。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”指形状，与学技术没有关系。"}, {"text": "分布式", "is_correct": true, "explanation": "正确。“分布式技术”指分开放在多台机器上运行的技术，符合句意。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，与“学技术”的语境不合。"}], "explanations": {"温柔": "搭配：“温柔”形容人的性情，不能修饰“技术”。", "圆": "语义：“圆”指形状，与学技术没有关系。", "分布式": "正确。“分布式技术”指分开放在多台机器上运行的技术，符合句意。", "甜": "语义：“甜”指味道，与“学技术”的语境不合。"}, "sentence_index": 6, "correct_answer": "分布式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的眼睛很分布式。", "explanation": "这里应该用〈明亮〉。「分布式」只指东西分放在多处，不能形容眼睛；形容眼睛有神要说「明亮」。"}, {"text": "他今天的分布式心情很好。", "explanation": "这里应该用〈愉快〉。「分布式」只指东西分放在多处，不能形容心情；形容心情舒畅要说「愉快」。"}, {"text": "这个电影很分布式，很好看。", "explanation": "这里应该用〈有趣〉。「分布式」只指东西分放在多处，不能形容电影；形容电影吸引人要说「有趣」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23032, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个网站的数据是分布式。", "corrected_sentence": "这个网站的数据是分布式的。", "error_description": "错误：“是分布式”；正确：“是分布式的”。“分布式”作谓语时，后面一般要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23032, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些服务器分布式在各个城市。", "corrected_sentence": "这些服务器分布在各个城市。", "error_description": "错误：“分布式在”；正确：“分布在”。“分布式”是修饰系统或结构的形容词，不能当动词用，表示分开放置要用动词“分布”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
