INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23034, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "脚踩过留下的印子。", "primary_collocate": null, "pronunciation": "zú jì", "ipa": "tsu˧˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "雪地上留下了一行小小的足迹。", "target_word": "足迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水把沙滩上的足迹冲走了。", "target_word": "足迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，地上有一串动物的足迹。", "target_word": "足迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们沿着足迹找到了走丢的小羊。", "target_word": "足迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨后，泥路上全是人的足迹。", "target_word": "足迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位旅行家在沙滩上留下了一串足迹。", "target_word": "足迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月球上还留着宇航员的足迹。", "target_word": "足迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在院子里踩出了许多小足迹。", "target_word": "足迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在窗下发现了陌生人的足迹。", "target_word": "足迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪停了，我们回头看自己的足迹。", "target_word": "足迹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一行足迹", "label": "量词"}, {"form": "一串足迹", "label": "量词"}], "register": "中性", "sense_fingerprint": "脚踩过地面后留下的印子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48420b25-8f0d-4c8e-9a02-21c20436390e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23034, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "足迹", "is_correct": true, "explanation": "足迹：脚踩过地面后留下的印子。这是正确答案。"}, {"text": "阻击", "is_correct": false, "explanation": "zǔjī（第三、第一声）与 zújì（第二、第四声）声调不同，意思是阻挡打击。"}, {"text": "祖籍", "is_correct": false, "explanation": "zǔjí（第三、第二声）与 zújì（第二、第四声）声调不同，意思是祖先的籍贯。"}, {"text": "族籍", "is_correct": false, "explanation": "zújí（第二声）与 zújì（第四声）第二个音节声调不同，意思是民族的籍属，不常用。"}], "explanations": {"足迹": "足迹：脚踩过地面后留下的印子。这是正确答案。", "阻击": "zǔjī（第三、第一声）与 zújì（第二、第四声）声调不同，意思是阻挡打击。", "祖籍": "zǔjí（第三、第二声）与 zújì（第二、第四声）声调不同，意思是祖先的籍贯。", "族籍": "zújí（第二声）与 zújì（第四声）第二个音节声调不同，意思是民族的籍属，不常用。"}, "sentence_index": null, "correct_answer": "足迹"}, "level_3": {"options": [{"text": "足迹", "is_correct": true, "explanation": "正确：足迹指脚踩过留下的印子，符合“雪地上留下了一行小小的”。"}, {"text": "指纹", "is_correct": false, "explanation": "语义：指纹是手指按过留下的印记，雪地上的印子不可能是手指留下的。"}, {"text": "泪痕", "is_correct": false, "explanation": "语义：泪痕是眼泪流过脸颊留下的痕迹，不会留在雪地上。"}, {"text": "印章", "is_correct": false, "explanation": "语义：印章是盖章用的工具，不会在雪地上留下一行印子。"}], "explanations": {"足迹": "正确：足迹指脚踩过留下的印子，符合“雪地上留下了一行小小的”。", "指纹": "语义：指纹是手指按过留下的印记，雪地上的印子不可能是手指留下的。", "泪痕": "语义：泪痕是眼泪流过脸颊留下的痕迹，不会留在雪地上。", "印章": "语义：印章是盖章用的工具，不会在雪地上留下一行印子。"}, "sentence_index": 0, "correct_answer": "足迹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌上留着一圈咖啡的足迹。", "explanation": "这里应该用〈痕迹〉。足迹专指脚踩过留下的印子，咖啡渍只能说痕迹。"}, {"text": "这双鞋的足迹是四十码。", "explanation": "这里表示鞋的尺寸，应该用〈尺码〉。足迹指脚踩过留下的印子，不指鞋的大小。"}, {"text": "他听见身后传来急促的足迹。", "explanation": "这里应该用〈脚步〉。足迹是看得见的印子，听见的声音要说脚步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23034, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "足迹", "is_correct": true, "explanation": "正确：足迹指脚踩过留下的印子，符合“月球上还留着宇航员的”。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：呼吸是人的生理活动，不会留在月球上。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是人体的温度，会随时间散失，不能像印子一样留在月球上。"}, {"text": "尾气", "is_correct": false, "explanation": "搭配：尾气是交通工具排出的废气，不能说宇航员的尾气留在月球上。"}], "explanations": {"足迹": "正确：足迹指脚踩过留下的印子，符合“月球上还留着宇航员的”。", "呼吸": "语义：呼吸是人的生理活动，不会留在月球上。", "体温": "语义：体温是人体的温度，会随时间散失，不能像印子一样留在月球上。", "尾气": "搭配：尾气是交通工具排出的废气，不能说宇航员的尾气留在月球上。"}, "sentence_index": 6, "correct_answer": "足迹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的足迹很香。", "explanation": "这里表示气味，应该用〈香气〉。足迹是脚踩留下的印子，没有气味，不能用来形容香味。"}, {"text": "这片雪地的足迹很甜。", "explanation": "这里误用了〈味道〉的意思。足迹是脚踩留下的印子，没有味道，甜只能用来形容食物。"}, {"text": "这辆车在雪地上留下了一串足迹。", "explanation": "足迹指人或动物脚踩出的印子，车轮压出的痕迹应该用〈车辙〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小狗在雪地上留下了一根足迹。", "corrected_sentence": "小狗在雪地上留下了一串足迹。", "error_description": "错误：量词“一根”。“根”用于细长条状的东西，不能用于足迹。正确：“一串足迹”，足迹应用〈串〉或〈行〉计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪化以后，院子里还留着许多足迹们。", "corrected_sentence": "雪化以后，院子里还留着许多足迹。", "error_description": "错误：“足迹们”，在足迹后面加了“们”。“们”只用于指人的名词，足迹不能加“们”。正确：“许多足迹”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23036, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "推进", "is_correct": false, "explanation": "无关：“推进”指使事情向前发展，与“干预”没有反义关系。"}, {"text": "放任", "is_correct": true, "explanation": "反义：“放任”指任由别人去做、不加过问，与“干预”相对。"}, {"text": "观察", "is_correct": false, "explanation": "无关：“观察”指仔细看，与“干预”没有反义关系。"}, {"text": "保存", "is_correct": false, "explanation": "无关：“保存”指留存、收藏，与“干预”没有反义关系。"}], "correct_answer": "放任", "explanations": {"推进": "无关：“推进”指使事情向前发展，与“干预”没有反义关系。", "放任": "反义：“放任”指任由别人去做、不加过问，与“干预”相对。", "观察": "无关：“观察”指仔细看，与“干预”没有反义关系。", "保存": "无关：“保存”指留存、收藏，与“干预”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23036, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "维修", "is_correct": false, "explanation": "无关：“维修”指修理保养，与“干预”没有反义关系。"}, {"text": "不管", "is_correct": true, "explanation": "反义：“不管”指不过问、任其自便，与“干预”相对。"}, {"text": "赞助", "is_correct": false, "explanation": "无关：“赞助”指出资支持，与“干预”没有反义关系。"}, {"text": "奖励", "is_correct": false, "explanation": "无关：“奖励”指给予好处以表扬，与“干预”没有反义关系。"}], "correct_answer": "不管", "explanations": {"维修": "无关：“维修”指修理保养，与“干预”没有反义关系。", "不管": "反义：“不管”指不过问、任其自便，与“干预”相对。", "赞助": "无关：“赞助”指出资支持，与“干预”没有反义关系。", "奖励": "无关：“奖励”指给予好处以表扬，与“干预”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23036, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "插手别人的事，影响别人怎么做。", "primary_collocate": null, "pronunciation": "gān yù", "ipa": "kan˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "父母不应该干预孩子的选择。", "target_word": "干预", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有干预他们的讨论。", "target_word": "干预", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是干预我的工作，我很烦。", "target_word": "干预", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别的国家不能干预这件事。", "target_word": "干预", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈从不干预我交朋友。", "target_word": "干预", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理干预了我们的计划，大家都不高兴。", "target_word": "干预", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要干预别人的生活。", "target_word": "干预", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板干预过我的决定，我不喜欢。", "target_word": "干预", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不想让邻居干预家里的事。", "target_word": "干预", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷总想干预孙子的婚事。", "target_word": "干预", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "干预了", "label": "完成体"}, {"form": "干预过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "插手别人的事，不让别人照自己的想法做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f735cfaa-c81a-4eea-8896-d7ab5126a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23036, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "敢于", "is_correct": false, "explanation": "gǎn yú（第三声、第二声）与 gān yù（第一声、第四声）声调不同，意思是有勇气去做。"}, {"text": "甘于", "is_correct": false, "explanation": "gān yú 与 gān yù 只有第二个音节声调不同（第二声与第四声），意思是心甘情愿。"}, {"text": "干预", "is_correct": true, "explanation": "正确：“干预”读作 gān yù，指插手别人的事、不让别人做想做的事。"}, {"text": "干鱼", "is_correct": false, "explanation": "gān yú 与 gān yù 只有第二个音节声调不同（第二声与第四声），意思是晒干的鱼。"}], "explanations": {"敢于": "gǎn yú（第三声、第二声）与 gān yù（第一声、第四声）声调不同，意思是有勇气去做。", "甘于": "gān yú 与 gān yù 只有第二个音节声调不同（第二声与第四声），意思是心甘情愿。", "干预": "正确：“干预”读作 gān yù，指插手别人的事、不让别人做想做的事。", "干鱼": "gān yú 与 gān yù 只有第二个音节声调不同（第二声与第四声），意思是晒干的鱼。"}, "sentence_index": null, "correct_answer": "干预"}, "level_3": {"options": [{"text": "尊重", "is_correct": false, "explanation": "语义：“尊重”是重视别人的想法，“不应该尊重”会与句子语境相反。"}, {"text": "认识", "is_correct": false, "explanation": "搭配：“认识”的对象是人或事物，不能说“认识孩子的选择”。"}, {"text": "干预", "is_correct": true, "explanation": "正确：“干预”指父母插手并阻止孩子的选择，符合句意。"}, {"text": "照顾", "is_correct": false, "explanation": "配价：“照顾”的对象通常是人或需要照料的事物，“选择”不能被照顾。"}], "explanations": {"尊重": "语义：“尊重”是重视别人的想法，“不应该尊重”会与句子语境相反。", "认识": "搭配：“认识”的对象是人或事物，不能说“认识孩子的选择”。", "干预": "正确：“干预”指父母插手并阻止孩子的选择，符合句意。", "照顾": "配价：“照顾”的对象通常是人或需要照料的事物，“选择”不能被照顾。"}, "sentence_index": 0, "correct_answer": "干预"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们干预他考上了大学。", "explanation": "这里应该用〈祝贺〉。干预指插手并阻止别人做想做的事，不能用来表达对喜事的庆贺。"}, {"text": "我们干预他的热心帮助。", "explanation": "这里应该用〈感谢〉。干预是不让对方做事，不能用来表达对别人帮助的谢意。"}, {"text": "老师干预他的勇气。", "explanation": "这里应该用〈赞赏〉。干预指阻止别人行动，不能用来赞扬别人的品质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23036, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "享受", "is_correct": false, "explanation": "语义：“享受”指感受快乐，与“请不要”的劝阻语境相冲突。"}, {"text": "清洗", "is_correct": false, "explanation": "搭配：“清洗”用于衣物、器皿等，不能接“生活”作宾语。"}, {"text": "干预", "is_correct": true, "explanation": "正确：“干预”指插手别人的事，与“请不要”搭配，句意通顺。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止”指让正在进行的事结束，“别人的生活”不能被停止，句子不通。"}], "explanations": {"享受": "语义：“享受”指感受快乐，与“请不要”的劝阻语境相冲突。", "清洗": "搭配：“清洗”用于衣物、器皿等，不能接“生活”作宾语。", "干预": "正确：“干预”指插手别人的事，与“请不要”搭配，句意通顺。", "停止": "语义：“停止”指让正在进行的事结束，“别人的生活”不能被停止，句子不通。"}, "sentence_index": 6, "correct_answer": "干预"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸干预了那把坏掉的椅子。", "explanation": "这里应该用〈修理〉。干预是插手别人的事，不能用于修补东西。"}, {"text": "他干预了这些碗。", "explanation": "这里应该用〈清洗〉。清洗是用水把东西弄干净，干预指插手别人的事，不能用于碗。"}, {"text": "妈妈干预了一个蛋糕。", "explanation": "这里应该用〈烘焙〉。烘焙是把面团加热做成食物，干预不能用于做食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父母曾经干预了过孩子的选择。", "corrected_sentence": "父母曾经干预过孩子的选择。", "error_description": "“干预”后同时用了“了”和“过”，两个动态助词不能并用；应去掉“了”，说“干预过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经理干预了过我们的工作。", "corrected_sentence": "经理干预过我们的工作。", "error_description": "“干预”后同时用了“了”和“过”，两个动态助词不能并用；应去掉“了”，说“干预过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
