INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23038, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "把没用的东西扔掉或变成有用的东西。", "primary_collocate": null, "pronunciation": "lā jī chǔ lǐ", "ipa": "la˥ tɕi˥ ʈʂʰu˨˩˦ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "我家每天都要做垃圾处理。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾处理的第一步是分类。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校教我们怎样做垃圾处理。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾处理做得好，城市就干净。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司负责垃圾处理的工作。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些旧东西经过垃圾处理，会变成有用的东西。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的垃圾处理让河水不再变脏。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们小区的垃圾处理很方便。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾处理不好，夏天会有难闻的味道。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在课上学习垃圾处理的办法。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "垃圾处理厂", "label": "复合"}, {"form": "垃圾处理站", "label": "复合"}, {"form": "垃圾處理", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把没用的东西扔掉或变成有用东西的做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8504da67-cb87-4591-9bab-b889bffaad51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23038, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "垃圾处理", "is_correct": true, "explanation": "正确：作“做”的宾语，指家庭把没用的东西扔掉或变废为宝的日常做法。"}, {"text": "手术", "is_correct": false, "explanation": "语义：家庭日常不做手术，“我家每天都要做手术”不成立。"}, {"text": "体检", "is_correct": false, "explanation": "语义：体检不是每天都要做的家务，与“每天都要”的语境冲突。"}, {"text": "演讲", "is_correct": false, "explanation": "语义：家庭每天不会做演讲，“每天都要做演讲”与家庭日常的语境冲突。"}], "explanations": {"垃圾处理": "正确：作“做”的宾语，指家庭把没用的东西扔掉或变废为宝的日常做法。", "手术": "语义：家庭日常不做手术，“我家每天都要做手术”不成立。", "体检": "语义：体检不是每天都要做的家务，与“每天都要”的语境冲突。", "演讲": "语义：家庭每天不会做演讲，“每天都要做演讲”与家庭日常的语境冲突。"}, "sentence_index": 0, "correct_answer": "垃圾处理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们家今天做了三只垃圾处理。", "explanation": "这里应该用〈次〉。垃圾处理指一次次的处理动作，计量用“次”；“只”用于动物或成对的器物，不能用于此。"}, {"text": "他今天只做了一张垃圾处理。", "explanation": "这里应该用〈次〉。“张”用于纸、桌子等平面的东西，不用于计数动作。"}, {"text": "这些旧罐头我放进了垃圾处理里。", "explanation": "这里是把过程误当成容器。垃圾处理指处理的过程，不是盛放废物的地方；放东西应说〈垃圾桶〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23038, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "垃圾处理", "is_correct": true, "explanation": "正确：作主语，指把废弃物扔掉或变废为宝的做法，能让河水变干净。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”不是能让河水变干净的做法，“好的老师让河水不再变脏”句意不通。"}, {"text": "发型", "is_correct": false, "explanation": "语义：“发型”与河水无关，无法使河水变干净。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：“让……不再变脏”的主语应是处理、措施一类的行为，“鞋子”不能与之搭配。"}], "explanations": {"垃圾处理": "正确：作主语，指把废弃物扔掉或变废为宝的做法，能让河水变干净。", "老师": "语义：“老师”不是能让河水变干净的做法，“好的老师让河水不再变脏”句意不通。", "发型": "语义：“发型”与河水无关，无法使河水变干净。", "鞋子": "搭配：“让……不再变脏”的主语应是处理、措施一类的行为，“鞋子”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "垃圾处理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天都做一块垃圾处理。", "explanation": "这里应该用〈次〉。“块”用于成块的东西，不计数动作，垃圾处理是动作。"}, {"text": "他们班去年做了两把垃圾处理。", "explanation": "这里应该用〈次〉。“把”用于带柄的器具，不用于计数动作。"}, {"text": "我弟弟是我们家的垃圾处理。", "explanation": "这里是把过程误当成人。垃圾处理指处理的过程，不指做这件事的人；指人应说〈垃圾处理员〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每天都很做垃圾处理，把瓶子和纸分开。", "corrected_sentence": "我们每天都做垃圾处理，把瓶子和纸分开。", "error_description": "“很”是程度副词，不能直接修饰动词“做”；应去掉“很”，写作“每天都做垃圾处理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈常常垃圾处理，把旧瓶子变成花盆。", "corrected_sentence": "妈妈常常做垃圾处理，把旧瓶子变成花盆。", "error_description": "“垃圾处理”是名词，作宾语时需要动词“做”引出动作，句中缺少动词。错误形式：妈妈常常垃圾处理；正确形式：妈妈常常做垃圾处理。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
