INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23040, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "碳是一种很常见的元素，石墨、钻石和木炭都是它的不同形式。", "primary_collocate": null, "pronunciation": "tàn", "ipa": "tʰan⁵¹", "syllable_count": 1, "sentences": [{"text": "碳是一种很常见的元素。", "target_word": "碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木炭里最主要的东西是碳。", "target_word": "碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钻石和铅笔芯都是由碳做成的。", "target_word": "碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家们一直在研究碳的用处。", "target_word": "碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化学课上，老师讲了碳的用途。", "target_word": "碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球上所有的生命都含有碳。", "target_word": "碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烧过的木头里有很多碳。", "target_word": "碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "碳在空气中烧，会变成气体。", "target_word": "碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块黑黑的东西主要是碳。", "target_word": "碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在书上学到，碳有很多种样子。", "target_word": "碳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "碳元素", "label": "复合"}, {"form": "碳原子", "label": "复合"}], "register": "中性", "sense_fingerprint": "碳|名词|常见元素，石墨、钻石、木炭都由它构成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f735cfaa-c81a-4eea-8896-d7ab5126a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23040, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "碳", "is_correct": true, "explanation": "碳（tàn，第四声）是一种常见的化学元素。"}, {"text": "谈", "is_correct": false, "explanation": "谈（tán，第二声）与 tàn 声调不同，意思是谈话。"}, {"text": "坦", "is_correct": false, "explanation": "坦（tǎn，第三声）与 tàn 声调不同，意思是平坦。"}, {"text": "贪", "is_correct": false, "explanation": "贪（tān，第一声）与 tàn 声调不同，意思是贪心。"}, {"text": "趟", "is_correct": false, "explanation": "趟（tàng，第四声）与 tàn 韵尾不同，一个是 n，一个是 ng，意思是一次来回。"}], "explanations": {"碳": "碳（tàn，第四声）是一种常见的化学元素。", "谈": "谈（tán，第二声）与 tàn 声调不同，意思是谈话。", "坦": "坦（tǎn，第三声）与 tàn 声调不同，意思是平坦。", "贪": "贪（tān，第一声）与 tàn 声调不同，意思是贪心。", "趟": "趟（tàng，第四声）与 tàn 韵尾不同，一个是 n，一个是 ng，意思是一次来回。"}, "sentence_index": null, "correct_answer": "碳"}, "level_3": {"options": [{"text": "碳", "is_correct": true, "explanation": "正确。碳是一种常见元素，与“一种很常见的元素”相合。"}, {"text": "水", "is_correct": false, "explanation": "语义：水是化合物，不是元素，与“一种很常见的元素”不符。"}, {"text": "木头", "is_correct": false, "explanation": "搭配：“木头”是材料，不是元素，不能说“木头是一种元素”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是混合物，不是元素，与句意不合。"}], "explanations": {"碳": "正确。碳是一种常见元素，与“一种很常见的元素”相合。", "水": "语义：水是化合物，不是元素，与“一种很常见的元素”不符。", "木头": "搭配：“木头”是材料，不是元素，不能说“木头是一种元素”。", "空气": "语义：空气是混合物，不是元素，与句意不合。"}, "sentence_index": 0, "correct_answer": "碳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都喝一杯碳。", "explanation": "这里应该用〈牛奶〉。碳是一种元素，不是饮料，不能喝。"}, {"text": "妈妈戴着一颗碳戒指。", "explanation": "这里应该用〈钻石〉。碳是元素的名称，不能用来指戒指上的宝石。"}, {"text": "我们在化学课上把木头碳了。", "explanation": "这里应该用〈碳化〉。碳是名词，表示元素，不能直接当动词用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23040, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "碳", "is_correct": true, "explanation": "碳（tàn，第四声）是一种常见的化学元素。"}, {"text": "滩", "is_correct": false, "explanation": "滩（tān，第一声）与 tàn 声调不同，意思是河边或海边的沙地。"}, {"text": "毯", "is_correct": false, "explanation": "毯（tǎn，第三声）与 tàn 声调不同，意思是毛毯。"}, {"text": "痰", "is_correct": false, "explanation": "痰（tán，第二声）与 tàn 声调不同，意思是呼吸道分泌的黏液。"}, {"text": "烫", "is_correct": false, "explanation": "烫（tàng，第四声）与 tàn 韵尾不同，一个是 n，一个是 ng，意思是温度很高。"}], "explanations": {"碳": "碳（tàn，第四声）是一种常见的化学元素。", "滩": "滩（tān，第一声）与 tàn 声调不同，意思是河边或海边的沙地。", "毯": "毯（tǎn，第三声）与 tàn 声调不同，意思是毛毯。", "痰": "痰（tán，第二声）与 tàn 声调不同，意思是呼吸道分泌的黏液。", "烫": "烫（tàng，第四声）与 tàn 韵尾不同，一个是 n，一个是 ng，意思是温度很高。"}, "sentence_index": null, "correct_answer": "碳"}, "level_3": {"options": [{"text": "碳", "is_correct": true, "explanation": "正确。烧过的木头里含有大量碳，与“烧过”相合。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不会存在于烧过的木头里，与句意不合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“很多”后应接可以存在于其中的物质，“木头里有很多颜色”不成立。"}, {"text": "泥", "is_correct": false, "explanation": "语义：泥是土和水的混合物，不是木头燃烧后的剩余物，与“烧过”不合。"}], "explanations": {"碳": "正确。烧过的木头里含有大量碳，与“烧过”相合。", "雨": "语义：雨不会存在于烧过的木头里，与句意不合。", "颜色": "搭配：“很多”后应接可以存在于其中的物质，“木头里有很多颜色”不成立。", "泥": "语义：泥是土和水的混合物，不是木头燃烧后的剩余物，与“烧过”不合。"}, "sentence_index": 6, "correct_answer": "碳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "铁是一种常见的碳。", "explanation": "这里应该用〈金属〉。铁属于金属，碳是非金属元素，不能说铁是一种碳。"}, {"text": "这扇窗户是用碳做的。", "explanation": "这里应该用〈玻璃〉。碳是元素，不能用来做窗户。"}, {"text": "这座房子是用碳盖的。", "explanation": "这里应该用〈石头〉。碳不能用来盖房子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "钻石是碳由做成的。", "corrected_sentence": "钻石是由碳做成的。", "error_description": "介词“由”要放在“碳”的前面，构成“由碳做成”；“碳由做成”语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块碳烧完以后，会变气体。", "corrected_sentence": "这块碳烧完以后，会变成气体。", "error_description": "“变”后面要加结果补语“成”，说“变成气体”；“变气体”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23042, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暴露", "is_correct": true, "explanation": "反义：“潜藏着”指东西躲在某处别人看不见，“暴露”指藏着的东西被人看见，二者相对。"}, {"text": "修理", "is_correct": false, "explanation": "无反义关系：“修理”指把坏了的东西修好，与藏与显无关。"}, {"text": "搬运", "is_correct": false, "explanation": "无反义关系：“搬运”指把物品从一处运到另一处，不涉及是否被看见。"}, {"text": "讨论", "is_correct": false, "explanation": "无反义关系：“讨论”指多人交流意见，与隐藏、显现无关。"}], "correct_answer": "暴露", "explanations": {"暴露": "反义：“潜藏着”指东西躲在某处别人看不见，“暴露”指藏着的东西被人看见，二者相对。", "修理": "无反义关系：“修理”指把坏了的东西修好，与藏与显无关。", "搬运": "无反义关系：“搬运”指把物品从一处运到另一处，不涉及是否被看见。", "讨论": "无反义关系：“讨论”指多人交流意见，与隐藏、显现无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23042, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "显露", "is_correct": true, "explanation": "反义：“潜藏着”指东西躲在某处别人看不见，“显露”指表现出来让人看见，二者相对。"}, {"text": "翻译", "is_correct": false, "explanation": "无反义关系：“翻译”指把一种语言转成另一种语言，与藏与显无关。"}, {"text": "旅行", "is_correct": false, "explanation": "无反义关系：“旅行”指到外地游览，与是否被看见无关。"}, {"text": "播种", "is_correct": false, "explanation": "无反义关系：“播种”指把种子撒进土里，与藏与显无关。"}], "correct_answer": "显露", "explanations": {"显露": "反义：“潜藏着”指东西躲在某处别人看不见，“显露”指表现出来让人看见，二者相对。", "翻译": "无反义关系：“翻译”指把一种语言转成另一种语言，与藏与显无关。", "旅行": "无反义关系：“旅行”指到外地游览，与是否被看见无关。", "播种": "无反义关系：“播种”指把种子撒进土里，与藏与显无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23042, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西躲在一个地方，别人看不见它。", "primary_collocate": null, "pronunciation": "qián cáng zhe", "ipa": "tɕʰjɛn˧˥ tsʰɑŋ˧˥ ʈʂɤ", "syllable_count": 3, "sentences": [{"text": "洞里潜藏着一只小老鼠。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草丛里潜藏着几条蛇，我们要小心。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子后面潜藏着一只小猫，没人看见它。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水底潜藏着一块大石头，船过不去。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑暗中潜藏着一个人，我们都没发现。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙子下面潜藏着许多小螃蟹。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树叶后面潜藏着一只鸟，孩子们找不到它。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山洞里潜藏着一只受伤的狐狸，外面的人不知道。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "床底下潜藏着一个旧盒子，我找了很久。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟潜藏着，等猎人走远了才飞出来。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "潜藏", "label": "体标"}, {"form": "潜藏了", "label": "体标"}, {"form": "潜藏过", "label": "体标"}, {"form": "潛藏著", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或东西躲在某处，别人看不见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8504da67-cb87-4591-9bab-b889bffaad51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23042, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "潜藏着", "is_correct": true, "explanation": "正确。“潜藏着”表示老鼠躲在洞里、别人看不见，与句意相合。"}, {"text": "陈列着", "is_correct": false, "explanation": "语义：“陈列”是摆出来给人看，与“别人看不见”相矛盾。"}, {"text": "挂着", "is_correct": false, "explanation": "搭配：“挂着”多接物件，不说洞里挂着一只老鼠。"}, {"text": "堆着", "is_correct": false, "explanation": "搭配：“堆着”指许多实物堆在一起，不用于单只老鼠。"}], "explanations": {"潜藏着": "正确。“潜藏着”表示老鼠躲在洞里、别人看不见，与句意相合。", "陈列着": "语义：“陈列”是摆出来给人看，与“别人看不见”相矛盾。", "挂着": "搭配：“挂着”多接物件，不说洞里挂着一只老鼠。", "堆着": "搭配：“堆着”指许多实物堆在一起，不用于单只老鼠。"}, "sentence_index": 0, "correct_answer": "潜藏着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌子上潜藏着一瓶花，客人一进门就看见了。", "explanation": "这里应该用〈摆着〉。潜藏着指东西躲着、别人看不见，而花瓶摆在桌上是醒目可见的，应说“桌子上摆着一瓶花”。"}, {"text": "湖面上潜藏着一片落叶，很显眼。", "explanation": "这里应该用〈漂浮着〉。潜藏着表示看不见，落叶漂在湖面上很显眼，应说“湖面上漂浮着一片落叶”。"}, {"text": "墙上潜藏着一幅画，很多人都在看。", "explanation": "这里应该用〈挂着〉。潜藏着指不被看见，墙上的画人人可见，应说“墙上挂着一幅画”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23042, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潜藏着", "is_correct": true, "explanation": "正确。“潜藏着”表示小鸟躲在树叶后面，孩子们找不到，与句意相合。"}, {"text": "停放着", "is_correct": false, "explanation": "语义：“停放”用于车辆、物品，不说树叶后停放着一只鸟。"}, {"text": "悬挂着", "is_correct": false, "explanation": "搭配：“悬挂”多接物件，不用于活的鸟。"}, {"text": "摆放着", "is_correct": false, "explanation": "语义：“摆放”指有意摆出来，与“孩子们找不到它”的情境相矛盾。"}], "explanations": {"潜藏着": "正确。“潜藏着”表示小鸟躲在树叶后面，孩子们找不到，与句意相合。", "停放着": "语义：“停放”用于车辆、物品，不说树叶后停放着一只鸟。", "悬挂着": "搭配：“悬挂”多接物件，不用于活的鸟。", "摆放着": "语义：“摆放”指有意摆出来，与“孩子们找不到它”的情境相矛盾。"}, "sentence_index": 6, "correct_answer": "潜藏着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份计划在全体会议上潜藏着，经理当场就对大家讲清楚了。", "explanation": "这里应该用〈宣布〉。潜藏着指东西躲着、别人看不见，而计划在会议上当场讲清楚，人人都知道，应说“这份计划在会议上宣布了”。"}, {"text": "操场中央潜藏着一座大钟楼，远远地就能望见它的钟面。", "explanation": "这里应该用〈矗立〉。潜藏着指东西躲着、别人看不见，而钟楼高大醒目、远远可望，应说“操场中央矗立着一座大钟楼”。"}, {"text": "教室里潜藏着一块大黑板，全班同学都能看清上面的字。", "explanation": "这里应该用〈立着〉。潜藏着指东西躲着、别人看不见，而大黑板醒目，人人都能看清，应说“教室里立着一块大黑板”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "草堆里潜藏起来一只兔子。", "corrected_sentence": "草堆里潜藏着一只兔子。", "error_description": "错误在于“潜藏”后的“起来”。应为“潜藏着”；“潜藏起来”是不及物的，后面不能直接接宾语“一只兔子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书架后面潜藏了着一本旧书。", "corrected_sentence": "书架后面潜藏着一本旧书。", "error_description": "“潜藏着”已含体标“着”，又加“了”构成“了着”，属双重体标，不合语法；应只保留“着”。错误形式：潜藏了着；正确形式：潜藏着。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
