INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23044, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "温和的人很友好，不生气。", "primary_collocate": null, "pronunciation": "wēn hé", "ipa": "wən˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "我的邻居很温和，对谁都很友好。", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个温和的人，从来不生气。", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈很温和，我做错事她也不发火。", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温和的人容易交到朋友。", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的新同事看起来很温和，也很爱笑。", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李脾气温和，别人骂他，他也不生气。", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷对谁都温和，大家都愿意和他聊天。", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很温和，说话总是笑着。", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老爷爷很温和，从来不对孩子发脾气。", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是你再温和一点，大家会更喜欢你。", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "温和派", "label": "复合"}, {"form": "溫和", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人友好、脾气好、不爱生气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8504da67-cb87-4591-9bab-b889bffaad51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23044, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温和", "is_correct": true, "explanation": "正确：形容邻居性情平和，与“对谁都很友好”相合。"}, {"text": "暴躁", "is_correct": false, "explanation": "语义：“暴躁”指脾气急、易发火，与“对谁都很友好”矛盾。"}, {"text": "易怒", "is_correct": false, "explanation": "语义：“易怒”表示容易生气，与后半句的“友好”不相容。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：“冷漠”指对人冷淡、不关心，与“对谁都很友好”矛盾。"}], "explanations": {"温和": "正确：形容邻居性情平和，与“对谁都很友好”相合。", "暴躁": "语义：“暴躁”指脾气急、易发火，与“对谁都很友好”矛盾。", "易怒": "语义：“易怒”表示容易生气，与后半句的“友好”不相容。", "冷漠": "语义：“冷漠”指对人冷淡、不关心，与“对谁都很友好”矛盾。"}, "sentence_index": 0, "correct_answer": "温和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老师很温和，学生们一见他就吓得发抖。", "explanation": "这里应该用〈严厉〉。温和指性格或态度不严厉、不粗暴；学生一见就吓得发抖说明他态度严厉，与“温和”矛盾。"}, {"text": "这个老板很温和，对员工一天骂三次。", "explanation": "这里应该用〈暴躁〉。温和指不发火、不粗暴；一天骂三次说明脾气暴躁，应说“暴躁”，不能说“温和”。"}, {"text": "面对突发的火灾，他很温和，没有慌张。", "explanation": "这里应该用〈冷静〉。温和指性格或态度不严厉，不指遇事时的镇定；应对危机时应说“冷静”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23044, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温和", "is_correct": true, "explanation": "正确：指对人友好、不发脾气，与“大家都愿意和他聊天”相合。"}, {"text": "凶", "is_correct": false, "explanation": "语义：“凶”表示态度凶狠，大家不愿与之聊天，与后半句矛盾。"}, {"text": "高傲", "is_correct": false, "explanation": "语义：“高傲”表示看不起人，与“大家都愿意和他聊天”不相合。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外表，不用来描写对人的态度，“对谁都漂亮”说不通。"}], "explanations": {"温和": "正确：指对人友好、不发脾气，与“大家都愿意和他聊天”相合。", "凶": "语义：“凶”表示态度凶狠，大家不愿与之聊天，与后半句矛盾。", "高傲": "语义：“高傲”表示看不起人，与“大家都愿意和他聊天”不相合。", "漂亮": "体貌：“漂亮”形容外表，不用来描写对人的态度，“对谁都漂亮”说不通。"}, "sentence_index": 6, "correct_answer": "温和"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人很温和，见人就破口大骂。", "explanation": "这里应该用〈粗暴〉。温和指性格不粗暴、不发火；“见人就破口大骂”与“温和”矛盾，应说“粗暴”。"}, {"text": "这位大叔很温和，动手打了路人一拳。", "explanation": "这里应该用〈凶狠〉。温和指性格、态度不粗暴；“动手打人”与“温和”矛盾，应说“凶狠”。"}, {"text": "这孩子很温和，经常抢别人的东西。", "explanation": "这里应该用〈霸道〉。温和指性格和善、不强横；经常抢别人的东西说明霸道，不能说“温和”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位大叔温和得，孩子们都喜欢找他玩。", "corrected_sentence": "这位大叔温和得很，孩子们都喜欢找他玩。", "error_description": "“温和得”后面须接补语，如“温和得很”，不能以“得”结尾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈对谁都被温和，邻居们都说她好相处。", "corrected_sentence": "妈妈对谁都很温和，邻居们都说她好相处。", "error_description": "“温和”是形容词，不能与被动标记“被”搭配；应去掉“被”，改用“很温和”作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9fee08-31d7-43b4-9c57-30810208a321') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
