INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23046, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "战略就是关系全局的大计划。", "primary_collocate": null, "pronunciation": "zhàn lüè", "ipa": "ʈʂan˥˩ lɥe˥˩", "syllable_count": 2, "sentences": [{"text": "将军制定了新的战略，准备进攻。", "target_word": "战略", "complexity_tier": "T3", "furigana": "jiāng jūn zhì dìng le xīn de zhàn lüè zhǔn bèi jìn gōng", "sentence_source": "generated"}, {"text": "将军的战略是先守后攻。", "target_word": "战略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场战争的战略目标很清楚。", "target_word": "战略", "complexity_tier": "T3", "furigana": "zhè chǎng zhàn zhēng de zhàn lüè mù biāo hěn qīng chu", "sentence_source": "generated"}, {"text": "好的战略能帮助军队打赢战争。", "target_word": "战略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌军改变了战略。", "target_word": "战略", "complexity_tier": "T3", "furigana": "dí jūn gǎi biàn le zhàn lüè", "sentence_source": "generated"}, {"text": "将军对这场战争的长期战略很有信心。", "target_word": "战略", "complexity_tier": "T3", "furigana": "jiāng jūn duì zhè chǎng zhàn zhēng de cháng qī zhàn lüè hěn yǒu xìn xīn", "sentence_source": "generated"}, {"text": "战略不对，再努力也很难成功。", "target_word": "战略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个战略需要三年才能完成。", "target_word": "战略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争开始前，将军先制定战略。", "target_word": "战略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要根据情况调整战略。", "target_word": "战略", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "战略家", "label": "复合"}, {"form": "战略性", "label": "复合"}, {"form": "戰略", "label": "繁体"}], "register": "书面", "sense_fingerprint": "全局性的大计划", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ab50cd-4340-49f3-b7d1-188a43322068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23046, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "战略", "is_correct": true, "explanation": "原句说“制定了新的……，准备进攻”，需要全局性的大计划，“战略”正合适。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“制定”用于计划、规则，不说“制定歌曲”。"}, {"text": "食物", "is_correct": false, "explanation": "语义：“食物”与“准备进攻”的军事语境不符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“制定”用于计划、方案，不能用于“天气”。"}], "explanations": {"战略": "原句说“制定了新的……，准备进攻”，需要全局性的大计划，“战略”正合适。", "歌曲": "搭配：“制定”用于计划、规则，不说“制定歌曲”。", "食物": "语义：“食物”与“准备进攻”的军事语境不符。", "天气": "搭配：“制定”用于计划、方案，不能用于“天气”。"}, "sentence_index": 0, "correct_answer": "战略"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上的战略是先喝一杯咖啡。", "explanation": "这里应该用〈习惯〉。“战略”指关系全局的大计划，每天早上的日常做法要用“习惯”。"}, {"text": "我去超市买了一个战略。", "explanation": "这里应该用〈面包〉。“战略”是抽象的大计划，不是能买到的实物，超市里买的东西要用具体名词，如“面包”。"}, {"text": "这部电影的战略很感人。", "explanation": "这里应该用〈情节〉。“战略”是全局性的大计划，不能用来形容作品是否感人；电影里打动人的故事进程要用“情节”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23046, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战略", "is_correct": true, "explanation": "原句说“战略不对，再努力也很难成功”，指全局的大方向，“战略”正合适。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”不是决定成败的大计划，“体温不对”与后句的成功无关。"}, {"text": "节日", "is_correct": false, "explanation": "搭配：“不对”用于计划、方法，不能说“节日不对”。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：“脚印”是痕迹，不能用“不对”来评价成败的前提。"}], "explanations": {"战略": "原句说“战略不对，再努力也很难成功”，指全局的大方向，“战略”正合适。", "体温": "语义：“体温”不是决定成败的大计划，“体温不对”与后句的成功无关。", "节日": "搭配：“不对”用于计划、方法，不能说“节日不对”。", "脚印": "搭配：“脚印”是痕迹，不能用“不对”来评价成败的前提。"}, "sentence_index": 6, "correct_answer": "战略"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的战略长得很高。", "explanation": "这里应该用〈个子〉。“战略”是抽象的大计划，不能说“长得很高”，形容人的身高要用“个子”。"}, {"text": "这场雨的战略很大。", "explanation": "这里应该用〈雨量〉。“战略”是抽象的大计划，不能用来形容雨的大小，雨下得多少要用“雨量”。"}, {"text": "我的战略是123456。", "explanation": "这里应该用〈密码〉。“密码”是用于登录的一串字符，不是计划，“战略”不能指它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23046, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "参谋长提出了一场新的战略。", "corrected_sentence": "参谋长提出了一项新的战略。", "error_description": "量词错误：“战略”是抽象的计划，应用量词“项”，不能用“场”；“场”通常用于比赛、战争、活动等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23046, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些战略们都很重要。", "corrected_sentence": "这些战略都很重要。", "error_description": "“们”只用于指人的名词，“战略”是抽象名词，不能加“们”表示复数，应说“这些战略”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23048, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "取出", "is_correct": true, "explanation": "取出：从里面拿出来，与投入（放进去）构成反义。"}, {"text": "擦拭", "is_correct": false, "explanation": "与投入无反义关系：擦拭是把物体弄干净，与放进去无关。"}, {"text": "修理", "is_correct": false, "explanation": "与投入无反义关系：修理是使损坏的东西恢复正常，与放进去无关。"}, {"text": "唱歌", "is_correct": false, "explanation": "与投入无反义关系：唱歌是发出声音表演，与放进去无关。"}], "correct_answer": "取出", "explanations": {"取出": "取出：从里面拿出来，与投入（放进去）构成反义。", "擦拭": "与投入无反义关系：擦拭是把物体弄干净，与放进去无关。", "修理": "与投入无反义关系：修理是使损坏的东西恢复正常，与放进去无关。", "唱歌": "与投入无反义关系：唱歌是发出声音表演，与放进去无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23048, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "取出", "is_correct": true, "explanation": "取出：从里面拿出来，与投入（放进去）构成反义。"}, {"text": "清洗", "is_correct": false, "explanation": "与投入无反义关系：清洗是把脏物弄干净，与放进去无关。"}, {"text": "劝说", "is_correct": false, "explanation": "与投入无反义关系：劝说是用言语使人同意，与放进去无关。"}, {"text": "打扮", "is_correct": false, "explanation": "与投入无反义关系：打扮是修饰外表，与放进去无关。"}], "correct_answer": "取出", "explanations": {"取出": "取出：从里面拿出来，与投入（放进去）构成反义。", "清洗": "与投入无反义关系：清洗是把脏物弄干净，与放进去无关。", "劝说": "与投入无反义关系：劝说是用言语使人同意，与放进去无关。", "打扮": "与投入无反义关系：打扮是修饰外表，与放进去无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23048, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放到里面去。", "primary_collocate": null, "pronunciation": "tóu rù", "ipa": "tʰou˧˥ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "他把硬币投入了机器里。", "target_word": "投入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把垃圾投入垃圾桶。", "target_word": "投入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把信投入邮筒就走了。", "target_word": "投入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把一块糖投入杯子里。", "target_word": "投入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把原料投入机器。", "target_word": "投入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把票投入投票箱。", "target_word": "投入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把小石子投入湖里，水面起了波纹。", "target_word": "投入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧信投入火中烧掉了。", "target_word": "投入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把饺子投入开水中。", "target_word": "投入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把纸条投入了许愿箱。", "target_word": "投入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "投入了", "label": "体标（了）"}, {"form": "投入过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "投入：把硬币、信、垃圾等放进某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '071f4daf-d2f5-4352-a46c-90263f231feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23048, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "投入", "is_correct": true, "explanation": "投入：把硬币放进机器里，符合句意。"}, {"text": "欢呼", "is_correct": false, "explanation": "语义：欢呼是高兴时发出声音，不能用于把硬币放进机器。"}, {"text": "寄", "is_correct": false, "explanation": "配价：寄需要收件对象和「寄到」的结构，不能直接接处所「机器里」。"}, {"text": "赢", "is_correct": false, "explanation": "语义：赢是取得胜利，与把硬币放进机器的动作不符。"}], "explanations": {"投入": "投入：把硬币放进机器里，符合句意。", "欢呼": "语义：欢呼是高兴时发出声音，不能用于把硬币放进机器。", "寄": "配价：寄需要收件对象和「寄到」的结构，不能直接接处所「机器里」。", "赢": "语义：赢是取得胜利，与把硬币放进机器的动作不符。"}, "sentence_index": 0, "correct_answer": "投入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把钥匙投入了书包旁边。", "explanation": "这里应该用〈放〉。投入表示把东西放进某个容器或空间里，钥匙放在书包旁边不是放进去，不能用投入。"}, {"text": "她把外套投入墙上了。", "explanation": "这里应该用〈挂〉。投入表示把东西放进某处，把外套挂在墙上不是放进去的动作。"}, {"text": "她从杯子里投入了一块糖。", "explanation": "这里应该用〈取出〉。投入是把东西放进去，不能与「从杯子里」连用表示从里面拿出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23048, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投入", "is_correct": true, "explanation": "投入：把小石子放进湖里，水面起了波纹，符合句意。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏的对象是景物或作品，小石子不能被欣赏到湖里。"}, {"text": "演唱", "is_correct": false, "explanation": "搭配：演唱的宾语是歌曲或唱段，不能用于湖。"}, {"text": "抱", "is_correct": false, "explanation": "配价：抱需要拿在手里，不能只接处所「湖里」。"}], "explanations": {"投入": "投入：把小石子放进湖里，水面起了波纹，符合句意。", "欣赏": "语义：欣赏的对象是景物或作品，小石子不能被欣赏到湖里。", "演唱": "搭配：演唱的宾语是歌曲或唱段，不能用于湖。", "抱": "配价：抱需要拿在手里，不能只接处所「湖里」。"}, "sentence_index": 6, "correct_answer": "投入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把毛巾投入了椅背上。", "explanation": "这里应该用〈搭〉。投入表示把东西放进某个容器或空间里，毛巾搭在椅背上不是放进去的动作，不能用投入。"}, {"text": "他把颜料投入墙上了。", "explanation": "这里应该用〈涂〉。投入表示把东西放进某处，把颜料涂在墙上不是放进去的动作。"}, {"text": "她把花瓶投入桌子上了。", "explanation": "这里应该用〈摆〉。投入表示放进某个容器或处所，把花瓶摆在桌子上不能用投入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23048, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把一枚硬币投入在自动售货机。", "corrected_sentence": "她把一枚硬币投入自动售货机。", "error_description": "「投入在」多了「在」。投入后面直接接处所，应说「投入自动售货机」，不用「在」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一块石子投入河里。", "corrected_sentence": "他把一块石子投入河里。", "error_description": "缺少“把”：“他”后直接跟“一块石子”不成句，需用“把”引出被投入的宾语，应说“他把一块石子投入河里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
