INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23050, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家或地区发展大工业生产的过程。", "primary_collocate": null, "pronunciation": "gōng yè huà", "ipa": "kʊŋ˥ jɛ˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "这个国家的工业化走得很快。", "target_word": "工业化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业化让城市变大了。", "target_word": "工业化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业化需要很多工厂和工人。", "target_word": "工业化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在课上讲了欧洲的工业化。", "target_word": "工业化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业化以后，农村的人少了。", "target_word": "工业化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们国家的工业化已经完成了。", "target_word": "工业化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业化带来了很多新的工作。", "target_word": "工业化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，工业化改变了人们的生活。", "target_word": "工业化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇正在走工业化的路。", "target_word": "工业化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业化也会让空气变差。", "target_word": "工业化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工业", "label": "复合"}, {"form": "工业化国家", "label": "复合"}, {"form": "去工业化", "label": "复合"}], "register": "中性", "sense_fingerprint": "工业化：国家或地区发展大工业生产的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8c9982-2261-4a26-bafc-a41b87d5771d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23050, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工业化", "is_correct": true, "explanation": "正确：工业化指发展大工业生产的过程，可以“走”得快。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是不会移动的物体，不会“走”，更不能说进程。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋是食物，不是能“走得很快”的对象。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“走”说进程或速度，人口不能用“走”来描述。"}], "explanations": {"工业化": "正确：工业化指发展大工业生产的过程，可以“走”得快。", "石头": "语义：石头是不会移动的物体，不会“走”，更不能说进程。", "鸡蛋": "语义：鸡蛋是食物，不是能“走得很快”的对象。", "人口": "搭配：“走”说进程或速度，人口不能用“走”来描述。"}, "sentence_index": 0, "correct_answer": "工业化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市有很多工业化。", "explanation": "这里应该用〈工厂〉。工业化指发展大工业生产的过程，不能像工厂一样用来计数。"}, {"text": "工业化每天在教室里给学生上课。", "explanation": "这里应该用〈老师〉。工业化指发展大工业生产的过程，不能给学生上课，上课的是老师。"}, {"text": "工业化每天工作八个小时。", "explanation": "这里应该用〈工人〉。工业化是发展过程，不是能工作的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23050, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工业化", "is_correct": true, "explanation": "正确：工业化指发展大工业生产的过程，可以带来新的工作。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光线形成的暗影，不能带来工作。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能带来工作。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：脸色描写人的外表神情，不能带来工作。"}], "explanations": {"工业化": "正确：工业化指发展大工业生产的过程，可以带来新的工作。", "影子": "语义：影子是光线形成的暗影，不能带来工作。", "月亮": "语义：月亮是天体，不能带来工作。", "脸色": "体貌：脸色描写人的外表神情，不能带来工作。"}, "sentence_index": 6, "correct_answer": "工业化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天在厨房里工业化。", "explanation": "这里应该用〈做饭〉。工业化指国家或地区发展大工业生产的过程，不能用于个人在厨房里的活动，这里应该用做饭。"}, {"text": "这座发电站每天都在工业化。", "explanation": "这里应该用〈发电〉。工业化是国家或地区发展大工业的过程，不指具体的生产动作。"}, {"text": "这家工业化每年都扩大规模。", "explanation": "这里应该用〈公司〉。工业化指发展过程，不能像企业一样指具体的单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23050, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个地区的工业化推进地很快。", "corrected_sentence": "这个地区的工业化推进得很快。", "error_description": "“推进”后面表示程度的补语要用“得”，写成“地”是错误的，应说“推进得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23050, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个国家经历了过工业化。", "corrected_sentence": "这个国家经历过工业化。", "error_description": "“经历”后面的“了”和“过”不能同时使用，只保留“过”，应说“经历过工业化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
