INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23056, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把堆在一起的东西翻一翻。", "primary_collocate": null, "pronunciation": "fān duī", "ipa": "fan˥ tweɪ˥", "syllable_count": 2, "sentences": [{"text": "仓库里的粮食堆得很高，工人正在翻堆。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煤堆里面太热，必须马上翻堆。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅说，晒过的稻谷晚上要翻堆。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木头堆湿了，请明天翻堆晾一晾。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果放久了容易坏，所以要经常翻堆。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用大铲子翻堆，花了两个小时。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人翻堆后，发现下面的土豆都发芽了。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天下班前都要去院子里给柴火翻堆。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾站的工人正在翻堆，找能回收的东西。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "麦子堆在场上太久了，得赶快翻堆。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "翻堆机", "label": "复合"}], "register": "中性", "sense_fingerprint": "把堆放的东西翻动一遍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f00a336-31a6-490c-a9b6-74cabb491bba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23056, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "翻堆", "is_correct": true, "explanation": "正确：粮食堆得很高，工人需要翻动堆放的粮食，符合语境。"}, {"text": "刷漆", "is_correct": false, "explanation": "语义：刷漆是涂饰物体表面，与堆放的粮食无关。"}, {"text": "装订", "is_correct": false, "explanation": "搭配：「装订」多指书册，不用于粮食堆。"}, {"text": "焊接", "is_correct": false, "explanation": "语义：焊接是连接金属的作业，与粮食堆的情况不符。"}], "explanations": {"翻堆": "正确：粮食堆得很高，工人需要翻动堆放的粮食，符合语境。", "刷漆": "语义：刷漆是涂饰物体表面，与堆放的粮食无关。", "装订": "搭配：「装订」多指书册，不用于粮食堆。", "焊接": "语义：焊接是连接金属的作业，与粮食堆的情况不符。"}, "sentence_index": 0, "correct_answer": "翻堆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "炒饭的时候要不断翻堆米饭。", "explanation": "这里应该用〈翻炒〉。在锅中翻动食材要说翻炒，翻堆指翻动堆放的东西。"}, {"text": "他翻堆了一份旧报纸，发现了一则新闻。", "explanation": "这里应该用〈翻阅〉。翻看报纸要说翻阅，翻堆不用于翻看纸张。"}, {"text": "这台旧冰箱翻堆以后很好用。", "explanation": "这里应该用〈翻新〉。把旧物修整一新要说翻新，翻堆指翻动堆放的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ae68017-183c-4839-956e-4c1bff6e8fa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23056, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "翻堆", "is_correct": true, "explanation": "正确：工人翻动堆放的土豆后，才会发现下面的土豆发芽了。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：冷冻会使土豆停止生长，与「发芽」的结果矛盾。"}, {"text": "烧烤", "is_correct": false, "explanation": "语义：烤熟的土豆无法发芽，与「发芽」的结果矛盾。"}, {"text": "粉碎", "is_correct": false, "explanation": "搭配：「粉碎」一般用于坚硬物体，与整堆土豆的处理不搭配。"}], "explanations": {"翻堆": "正确：工人翻动堆放的土豆后，才会发现下面的土豆发芽了。", "冷冻": "语义：冷冻会使土豆停止生长，与「发芽」的结果矛盾。", "烧烤": "语义：烤熟的土豆无法发芽，与「发芽」的结果矛盾。", "粉碎": "搭配：「粉碎」一般用于坚硬物体，与整堆土豆的处理不搭配。"}, "sentence_index": 6, "correct_answer": "翻堆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇古文要翻堆成白话文。", "explanation": "这里应该用〈翻译〉。翻译指把一种语言转换成另一种语言，翻堆指翻动堆放的东西。"}, {"text": "河水翻堆起来，溅起白色的浪花。", "explanation": "这里应该用〈翻腾〉。液体上下翻涌要说翻腾，翻堆指翻动堆放的东西。"}, {"text": "小猫在草地上翻堆，玩得很开心。", "explanation": "这里应该用〈翻滚〉。小猫在地上打滚要说翻滚，翻堆指翻动堆放的物料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ae68017-183c-4839-956e-4c1bff6e8fa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人在仓库里翻堆着两个小时。", "corrected_sentence": "工人在仓库里翻堆了两个小时。", "error_description": "错误：「翻堆」后接时量表示动作已完成，要用「了」，不能用「着」。正确形式：翻堆了两个小时。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ae68017-183c-4839-956e-4c1bff6e8fa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人翻堆翻的很快。", "corrected_sentence": "工人翻堆翻得很快。", "error_description": "错误：重复动词后的补语要用「得」，不能用「的」。正确形式：翻堆翻得很快。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ae68017-183c-4839-956e-4c1bff6e8fa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23058, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
