INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23058, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指新出现的、大家还不知道的事情。", "primary_collocate": null, "pronunciation": "xīn liào", "ipa": "ɕin˥ liɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "他说他有一个新料，是关于老板的，大家都不知道。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天报纸上有一个关于学校的新料。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都想听听班里的新料。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新料太特别了，我还没听过。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王又带来了新料，是关于老板的。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁有新料？下课后告诉我。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者找到了一个大新料，马上写成了报道。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把新料发到了网上。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天又带来一个新料，大家都围过来听。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室里每天都有人说新料。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "新料：刚出现、大家还不知道的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f100bb76-d1fe-41e2-a9a4-3bd009c02759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23058, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "新料", "is_correct": true, "explanation": "xīn liào，指新出现、大家还不知道的事情或材料，即本义。"}, {"text": "金料", "is_correct": false, "explanation": "jīn 与 xīn 声母不同，金料指金的原料，意思不同。"}, {"text": "心量", "is_correct": false, "explanation": "liàng 与 liào 韵母不同，心量指度量、器量，意思不同。"}, {"text": "新粮", "is_correct": false, "explanation": "liáng 与 liào 的声调和韵母都不同，新粮指刚收获的粮食。"}], "explanations": {"新料": "xīn liào，指新出现、大家还不知道的事情或材料，即本义。", "金料": "jīn 与 xīn 声母不同，金料指金的原料，意思不同。", "心量": "liàng 与 liào 韵母不同，心量指度量、器量，意思不同。", "新粮": "liáng 与 liào 的声调和韵母都不同，新粮指刚收获的粮食。"}, "sentence_index": null, "correct_answer": "新料"}, "level_3": {"options": [{"text": "颜料", "is_correct": false, "explanation": "语义：“颜料”是用来着色的物品，不是“大家都不知道”的事情，句意不通。"}, {"text": "饲料", "is_correct": false, "explanation": "语义：“饲料”是喂动物的东西，不是关于老板、大家都不知道的事情。"}, {"text": "木料", "is_correct": false, "explanation": "语义：“木料”是木材实物，不能说成“大家都不知道”的情况，与句意不符。"}, {"text": "新料", "is_correct": true, "explanation": "正确选项“新料”与“他说他有一个……，大家都不知道”的语境相合。"}], "explanations": {"颜料": "语义：“颜料”是用来着色的物品，不是“大家都不知道”的事情，句意不通。", "饲料": "语义：“饲料”是喂动物的东西，不是关于老板、大家都不知道的事情。", "木料": "语义：“木料”是木材实物，不能说成“大家都不知道”的情况，与句意不符。", "新料": "正确选项“新料”与“他说他有一个……，大家都不知道”的语境相合。"}, "sentence_index": 0, "correct_answer": "新料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是几年前的新料，早就过时了。", "explanation": "这里应该用〈旧闻〉。“新料”指刚出现的消息，不能指几年前的事。"}, {"text": "这杯新料太烫了，他喝得直咧嘴。", "explanation": "这里的〈新料〉被误当作饮料。“新料”指新出现的、大家还不知道的消息或事情，不能当作可以喝的东西。"}, {"text": "他每天都给新料浇水。", "explanation": "这里的〈新料〉被误当作植物。“新料”指新出现的消息或事情，不能当作需要浇水的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23058, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩具", "is_correct": false, "explanation": "语义：“玩具”是供玩耍的物品，记者“找到一个大玩具”不能构成有价值的新闻，句意不通。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：“墨水”一般用“瓶”“支”计，不说“一个大墨水”，与句中搭配不当。"}, {"text": "鞋垫", "is_correct": false, "explanation": "搭配：“鞋垫”以“双”或“片”计，与“一个大”不搭，也不指可报道的事情。"}, {"text": "新料", "is_correct": true, "explanation": "正确选项“新料”与“记者找到了一个大……”的新闻语境相合。"}], "explanations": {"玩具": "语义：“玩具”是供玩耍的物品，记者“找到一个大玩具”不能构成有价值的新闻，句意不通。", "墨水": "搭配：“墨水”一般用“瓶”“支”计，不说“一个大墨水”，与句中搭配不当。", "鞋垫": "搭配：“鞋垫”以“双”或“片”计，与“一个大”不搭，也不指可报道的事情。", "新料": "正确选项“新料”与“记者找到了一个大……”的新闻语境相合。"}, "sentence_index": 6, "correct_answer": "新料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把新料穿在身上，走出了教室。", "explanation": "这里的〈新料〉被误当作衣物。“新料”指新出现的消息或事情，不能穿在身上。"}, {"text": "他的新料很高，比我还高。", "explanation": "这里的〈新料〉被误当作指人的身材。“新料”指新出现的消息或事情，不用来形容人的身高。"}, {"text": "妈妈把新料吃进了肚子里。", "explanation": "这里的〈新料〉被误当作食物。“新料”指新出现的消息或事情，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班里昨天有一只新料，大家都很吃惊。", "corrected_sentence": "班里昨天有一个新料，大家都很吃惊。", "error_description": "量词错误：“新料”前应用量词“个”，不能用“只”（“只”多用于动物或成对的东西）。错误为“一只新料”，正确为“一个新料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天找到了一个的新料。", "corrected_sentence": "他昨天找到了一个新料。", "error_description": "助词错误：“一个”与名词之间不能加“的”，应说“一个新料”，不能说“一个的新料”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
