INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23060, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "意思是每隔一段时间做一样的事。", "primary_collocate": null, "pronunciation": "dìng qī", "ipa": "tiŋ˥˩ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "医生让我定期检查身体。", "target_word": "定期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司定期开会，每个星期一次。", "target_word": "定期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们定期给花浇水。", "target_word": "定期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行会定期把账单寄给客人。", "target_word": "定期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他定期去看牙医，半年一次。", "target_word": "定期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师定期和家长见面。", "target_word": "定期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车要定期检查，才安全。", "target_word": "定期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈定期打扫房间，每周两次。", "target_word": "定期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆定期买新书。", "target_word": "定期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你应该定期锻炼身体。", "target_word": "定期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不定期", "label": "否定式"}, {"form": "定期的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "每隔固定的一段时间重复做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55f2e96c-13a5-42cd-ab9f-f21f3b3466c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23060, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "定期", "is_correct": true, "explanation": "定期表示每隔一段时间重复做某事，“医生让我定期检查身体”符合语境。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示事情出乎意料地发生，与“医生让我……检查身体”的计划性不符。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作正在进行，不能用于“让我”后面的安排。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示一次也没有，与“医生让我检查”的要求矛盾。"}], "explanations": {"定期": "定期表示每隔一段时间重复做某事，“医生让我定期检查身体”符合语境。", "突然": "语义：“突然”表示事情出乎意料地发生，与“医生让我……检查身体”的计划性不符。", "正在": "搭配：“正在”表示动作正在进行，不能用于“让我”后面的安排。", "从不": "语义：“从不”表示一次也没有，与“医生让我检查”的要求矛盾。"}, "sentence_index": 0, "correct_answer": "定期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他定期来看了我一次。", "explanation": "这里应该用〈偶尔〉。偶尔表示次数不固定，定期要求有固定的间隔，只发生一次不能用“定期”。"}, {"text": "他定期哭了起来。", "explanation": "这里应该用〈突然〉。突然表示没有预料地发生一次，定期要求有规律地重复。"}, {"text": "我定期一下子吃完了一整个蛋糕。", "explanation": "这里不是“定期”的用法。“定期”指每隔一段时间重复做，吃完一整个蛋糕是一次性完成，应说“一口气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23060, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "定期", "is_correct": true, "explanation": "定期修饰“检查”，表示按固定间隔进行，“车要定期检查，才安全”符合语境。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已经完成，与“要……检查”的要求不符。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”一般修饰形容词或心理动词，不能直接修饰动词“检查”。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示时间刚过不久，与“要”表示的要求不符。"}], "explanations": {"定期": "定期修饰“检查”，表示按固定间隔进行，“车要定期检查，才安全”符合语境。", "已经": "语义：“已经”表示动作已经完成，与“要……检查”的要求不符。", "很": "搭配：“很”一般修饰形容词或心理动词，不能直接修饰动词“检查”。", "刚刚": "语义：“刚刚”表示时间刚过不久，与“要”表示的要求不符。"}, "sentence_index": 6, "correct_answer": "定期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛定期结束了。", "explanation": "这里应该直接说“比赛结束了”，不用“定期”。比赛只结束一次，“定期”要求反复出现、有固定间隔。"}, {"text": "请定期离开。", "explanation": "这里应该用〈立即〉。立即表示马上去做，定期表示固定间隔重复，不能用于要求马上执行的动作。"}, {"text": "他定期去了一次北京。", "explanation": "这里应该用〈偶然〉或〈偶尔〉的说法。去北京只发生了一次，没有“每隔一段时间”的重复，不能用“定期”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈定期了去体检。", "corrected_sentence": "妈妈定期去体检。", "error_description": "“定期”是副词，后面不能直接加“了”。错误形式是“定期了去”，正确形式是“定期去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23060, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂很定期检修机器。", "corrected_sentence": "工厂定期检修机器。", "error_description": "错误：「定期」是表示频率的副词，前面不能加「很」修饰。错误形式是「很定期」，正确形式是「定期」。「很」只用来修饰形容词或心理动词，不修饰表示频率的副词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
