INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23066, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让不好的事情不发生。", "primary_collocate": null, "pronunciation": "fáng zhǐ", "ipa": "fɑŋ˧˥ ʈʂɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "出门前关好窗，防止小偷进来。", "target_word": "防止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多洗手可以防止生病。", "target_word": "防止", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把门锁好，防止孩子跑出去。", "target_word": "防止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了防止忘事，我把时间写在本子上。", "target_word": "防止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天冷了，要多穿衣服防止感冒。", "target_word": "防止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师提醒大家，要防止手机丢失。", "target_word": "防止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样做可以防止水流进房间。", "target_word": "防止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把药放高一点，防止小孩拿到。", "target_word": "防止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把饭菜放进冰箱，可以防止食物变质。", "target_word": "防止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要防止火灾，不要在家里玩火。", "target_word": "防止", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "防止了", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词，事先采取办法，使坏事、坏情况不发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d9ab088-f832-4c2b-8bdc-c6dfd9f23bbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23066, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "防止", "is_correct": true, "explanation": "正确：防止（fáng zhǐ），动词，表示事先采取办法使不好的事情不发生。"}, {"text": "房主", "is_correct": false, "explanation": "主（zhǔ）与止（zhǐ）声调相同，韵母不同（u 与 i），意思是房子的主人。"}, {"text": "防治", "is_correct": false, "explanation": "治（zhì，第四声）与止（zhǐ，第三声）声调不同，意思是预防和治疗。"}, {"text": "放置", "is_correct": false, "explanation": "放（fàng，第四声）与防（fáng，第二声）声调不同，置与止声调也不同，意思是放在某处。"}], "explanations": {"防止": "正确：防止（fáng zhǐ），动词，表示事先采取办法使不好的事情不发生。", "房主": "主（zhǔ）与止（zhǐ）声调相同，韵母不同（u 与 i），意思是房子的主人。", "防治": "治（zhì，第四声）与止（zhǐ，第三声）声调不同，意思是预防和治疗。", "放置": "放（fàng，第四声）与防（fáng，第二声）声调不同，置与止声调也不同，意思是放在某处。"}, "sentence_index": null, "correct_answer": "防止"}, "level_3": {"options": [{"text": "防止", "is_correct": true, "explanation": "正确：“防止”表示事先阻止，与“关好窗”的目的相符。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示迎接，“欢迎小偷进来”与“关好窗”的意图相反。"}, {"text": "邀请", "is_correct": false, "explanation": "语义：“邀请”表示请人来，“邀请小偷进来”与前半句的意图矛盾。"}, {"text": "容", "is_correct": false, "explanation": "语域：“容”是书面用法，口语不说“容小偷进来”，且与“关好窗”矛盾。"}], "explanations": {"防止": "正确：“防止”表示事先阻止，与“关好窗”的目的相符。", "欢迎": "语义：“欢迎”表示迎接，“欢迎小偷进来”与“关好窗”的意图相反。", "邀请": "语义：“邀请”表示请人来，“邀请小偷进来”与前半句的意图矛盾。", "容": "语域：“容”是书面用法，口语不说“容小偷进来”，且与“关好窗”矛盾。"}, "sentence_index": 0, "correct_answer": "防止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他防止正在打架的两个人。", "explanation": "这里应该用〈制止〉。“防止”是事先采取办法，使不好的事情不发生，不用于正在进行的打架或人。"}, {"text": "我们要防止成功。", "explanation": "这里应该用〈争取〉。“防止”只用于不好的事情，“成功”是好事。"}, {"text": "为了健康，我们要防止运动。", "explanation": "这里应该用〈坚持〉。“防止”针对不好的事情，“运动”是应当提倡的，不能防止。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23066, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "防止", "is_correct": true, "explanation": "正确：防止（fáng zhǐ），动词，表示事先采取办法使不好的事情不发生。"}, {"text": "房主", "is_correct": false, "explanation": "主（zhǔ）与止（zhǐ）声调相同，韵母不同（u 与 i），意思是房子的主人。"}, {"text": "仿制", "is_correct": false, "explanation": "仿（fǎng，第三声）与防（fáng，第二声）声调不同，制与止声调也不同，意思是模仿制造。"}, {"text": "纺织", "is_correct": false, "explanation": "纺（fǎng，第三声）与防（fáng，第二声）声调不同，织（zhī，第一声）与止声调也不同，意思是把纤维做成布。"}], "explanations": {"防止": "正确：防止（fáng zhǐ），动词，表示事先采取办法使不好的事情不发生。", "房主": "主（zhǔ）与止（zhǐ）声调相同，韵母不同（u 与 i），意思是房子的主人。", "仿制": "仿（fǎng，第三声）与防（fáng，第二声）声调不同，制与止声调也不同，意思是模仿制造。", "纺织": "纺（fǎng，第三声）与防（fáng，第二声）声调不同，织（zhī，第一声）与止声调也不同，意思是把纤维做成布。"}, "sentence_index": null, "correct_answer": "防止"}, "level_3": {"options": [{"text": "防止", "is_correct": true, "explanation": "正确：“防止”表示事先阻止，符合“水流进房间”是不希望发生的事。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”表示以……为乐，“享受水流进房间”说不通。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”要求有意愿的对象，水不能被拒绝，“拒绝水流进房间”不自然。"}, {"text": "迎接", "is_correct": false, "explanation": "语义：“迎接”表示欢迎到来，水流进房间是不好的事，不能迎接。"}], "explanations": {"防止": "正确：“防止”表示事先阻止，符合“水流进房间”是不希望发生的事。", "享受": "语义：“享受”表示以……为乐，“享受水流进房间”说不通。", "拒绝": "搭配：“拒绝”要求有意愿的对象，水不能被拒绝，“拒绝水流进房间”不自然。", "迎接": "语义：“迎接”表示欢迎到来，水流进房间是不好的事，不能迎接。"}, "sentence_index": 6, "correct_answer": "防止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生要防止他的健康。", "explanation": "这里应该用〈恢复〉。“防止”针对不好的事情，不能用于“健康”这种应当争取的状态。"}, {"text": "工人正在防止坏掉的水管。", "explanation": "这里应该用〈修理〉。“防止”是事先预防，水管已经坏了，只能修理。"}, {"text": "我们要防止春天到来。", "explanation": "这里应该用〈迎接〉。“防止”针对不好的事情，“春天到来”是好事，不能防止。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每天多喝水，防止着感冒。", "corrected_sentence": "我们每天多喝水，防止感冒。", "error_description": "体标错误：“防止”是一次性的事先预防动作，后面不能加表示持续状态的“着”。“防止着感冒”错误，应为“防止感冒”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家要注意安全，很防止事故。", "corrected_sentence": "大家要注意安全，防止事故。", "error_description": "“防止”是动词，不能被“很”修饰。“很防止事故”错误，应为“防止事故”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
