INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23068, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或工具让东西动起来。", "primary_collocate": null, "pronunciation": "cāo zuò", "ipa": "tsʰɑu̯˥ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "他会操作这台新机器。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请按照说明书操作电脑。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在操作机器。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机很简单，老人也会操作。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩不能随便操作这些按钮。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么操作显微镜。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用左手操作鼠标，很不习惯。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你操作错了，要先按红色的键。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会操作吊车，工作很稳。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台洗衣机我不会操作，你来帮我吧。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "操作了", "label": "完成体"}, {"form": "操作着", "label": "持续体"}, {"form": "操作过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "操作|动词|用手或工具使机器、设备运转", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b2369b-e895-4499-98cc-06ea7bf3828e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23068, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "操作", "is_correct": true, "explanation": "正确：操作（动词）指用手或工具使机器运转，与“这台新机器”搭配。"}, {"text": "阅读", "is_correct": false, "explanation": "语义：“阅读”的对象是文字，机器不能被读。"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”的宾语须是饮品，不能说“喝这台新机器”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，机器不能唱。"}], "explanations": {"操作": "正确：操作（动词）指用手或工具使机器运转，与“这台新机器”搭配。", "阅读": "语义：“阅读”的对象是文字，机器不能被读。", "喝": "配价：“喝”的宾语须是饮品，不能说“喝这台新机器”。", "唱": "语义：“唱”的对象是歌曲，机器不能唱。"}, "sentence_index": 0, "correct_answer": "操作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他站在台上操作乐队。", "explanation": "这里应用“指挥”。“操作”的对象是机器或设备，不能用来指挥乐队，指挥乐队要用“指挥”。"}, {"text": "老人会操作时间，很有经验。", "explanation": "这里应用“安排”。“操作”的对象是机器或设备，时间不能被“操作”，安排时间要用“安排”。"}, {"text": "他给朋友操作了一封信。", "explanation": "这里应用“写”。“操作”的对象是机器或设备，信要用“写”，不能被“操作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23068, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "操作", "is_correct": true, "explanation": "正确：操作（动词）指用手使鼠标运转，“用左手操作鼠标”符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语须是食物，“用左手吃鼠标”不成立。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”一般指用牙齿咬食物或物体，“咬鼠标”不符合语境。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”的对象是文字或图形，不能写鼠标。"}], "explanations": {"操作": "正确：操作（动词）指用手使鼠标运转，“用左手操作鼠标”符合句意。", "吃": "配价：“吃”的宾语须是食物，“用左手吃鼠标”不成立。", "咬": "语义：“咬”一般指用牙齿咬食物或物体，“咬鼠标”不符合语境。", "写": "语义：“写”的对象是文字或图形，不能写鼠标。"}, "sentence_index": 6, "correct_answer": "操作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我不会操作这首歌，你来唱吧。", "explanation": "这里应用“演唱”。“操作”的对象是机器或设备，歌曲不能被“操作”，唱歌要用“演唱”。"}, {"text": "我会操作这碗饭，你放心吧。", "explanation": "这里应用“煮”。“操作”的对象是机器或设备，饭要用“煮”或“做”，不能被“操作”。"}, {"text": "妈妈每天操作一朵花，很认真。", "explanation": "这里应用“浇”。“操作”的对象是机器或设备，花要用“浇”或“照顾”，不能被“操作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23068, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位工人把那台大型机器操作很熟练。", "corrected_sentence": "这位工人把那台大型机器操作得很熟练。", "error_description": "错误形式：“操作很熟练”。正确形式：“操作得很熟练”。程度补语前须用“得”连接动词与补语“很熟练”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23068, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你能帮我操作一下了这台电脑吗？", "corrected_sentence": "你能帮我操作一下这台电脑吗？", "error_description": "错误形式：“操作一下了这台电脑”。正确形式：“操作一下这台电脑”。动量词“一下”之后不能直接接“了”，多余的“了”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
