INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23070, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一群生活在一起的生物。", "primary_collocate": null, "pronunciation": "qún luò", "ipa": "tɕʰyn˧˥ luɔ˥˩", "syllable_count": 2, "sentences": [{"text": "这片森林里有一个很大的群落。", "target_word": "群落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草地上有一个由昆虫组成的群落。", "target_word": "群落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里的鱼和水草组成了一个群落。", "target_word": "群落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "群落里的每种生物都有自己的位置。", "target_word": "群落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在研究海底的群落。", "target_word": "群落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里的群落比草原上的复杂。", "target_word": "群落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水变脏了，河里的群落也变了。", "target_word": "群落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个池塘里有一个由青蛙和水草组成的群落。", "target_word": "群落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天过后，山上的群落发生了很大的变化。", "target_word": "群落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去看湖边的群落。", "target_word": "群落", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "生物群落", "label": "复合"}, {"form": "植物群落", "label": "复合"}], "register": "书面", "sense_fingerprint": "同一地方生活在一起的各种生物的整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76649259-ba21-4681-8829-56e282963d15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23070, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群落", "is_correct": true, "explanation": "正确：“群落”指同一地方生活在一起的各种生物，“有一个很大的群落”语义通顺。"}, {"text": "人口", "is_correct": false, "explanation": "语义：森林里的是生物，不说“人口”，“人口”指人的总数。"}, {"text": "语言", "is_correct": false, "explanation": "语义：“语言”是人类交流的工具，不是森林里可以存在的实体。"}, {"text": "人员", "is_correct": false, "explanation": "搭配：“人员”指人的集合，不能说“一个很大的人员”，计量用“批”。"}], "explanations": {"群落": "正确：“群落”指同一地方生活在一起的各种生物，“有一个很大的群落”语义通顺。", "人口": "语义：森林里的是生物，不说“人口”，“人口”指人的总数。", "语言": "语义：“语言”是人类交流的工具，不是森林里可以存在的实体。", "人员": "搭配：“人员”指人的集合，不能说“一个很大的人员”，计量用“批”。"}, "sentence_index": 0, "correct_answer": "群落"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个群落的成员都很热情。", "explanation": "这里应该用〈群体〉。群落指同一地区生活在一起的生物，指人的集合要用“群体”。"}, {"text": "这个群落的老人都很热情。", "explanation": "这里应该用〈社区〉。群落指生物的集合，指居民聚居的地方要用“社区”。"}, {"text": "这个群落里住着三百多户人家。", "explanation": "这里应该用〈村落〉。群落指生物的集合，指人聚居的地方要用“村落”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群落", "is_correct": true, "explanation": "正确：“群落”指河里生活的生物集合，随水质变化而变化，语义通顺。"}, {"text": "心情", "is_correct": false, "explanation": "语义：河没有心情，“心情”不会因为水变脏而变化。"}, {"text": "人生", "is_correct": false, "explanation": "语义：“人生”指人的一生，与河里的生物无关。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“歌曲”以“首”计量，河里的歌曲随水变化说不通。"}], "explanations": {"群落": "正确：“群落”指河里生活的生物集合，随水质变化而变化，语义通顺。", "心情": "语义：河没有心情，“心情”不会因为水变脏而变化。", "人生": "语义：“人生”指人的一生，与河里的生物无关。", "歌曲": "搭配：“歌曲”以“首”计量，河里的歌曲随水变化说不通。"}, "sentence_index": 6, "correct_answer": "群落"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "湖边有一张群落。", "explanation": "这里量词应为〈个〉。“张”用于纸、桌子等平面的东西，群落是多种生物的集合，不能用“张”计量。"}, {"text": "草地上有一座群落。", "explanation": "这里量词应为〈个〉。“座”用于山、楼房等大型物体，群落不用“座”。"}, {"text": "森林里有一棵群落。", "explanation": "这里量词应为〈个〉。“棵”用于单株植物，群落是多种生物的集合，不能用“棵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片湖里有一只群落。", "corrected_sentence": "这片湖里有一个群落。", "error_description": "量词错误：“群落”应用“个”计量。“只”用于单个动物，不能指一群生物的集合。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏天的湖边有很多群落们。", "corrected_sentence": "夏天的湖边有很多群落。", "error_description": "“们”用于指人，不能加在“群落”后。群落是非人事物的集合，表示多个时直接用“很多”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23072, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e44e0593-4a94-4af7-9478-59338c772782') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23072, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e44e0593-4a94-4af7-9478-59338c772782') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23072, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使水体、土壤等变成酸性，或使其酸性增强。", "primary_collocate": null, "pronunciation": "suān huà", "ipa": "swan˥ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "酸性物质进入湖泊后，会使湖水酸化。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气中的二氧化碳会酸化海水。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂排出的气体让雨水酸化了。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地的土已经酸化了，花长不好。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖水酸化以后，鱼很难活下去。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太多的化肥会让土地慢慢酸化。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大量排放二氧化硫，会让湖泊酸化。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酸化的海水对小鱼很不好。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他检查了湖水有没有酸化。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球的海洋正在酸化，很多贝类受到影响。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "酸化了", "label": "完成体"}, {"form": "酸化过", "label": "经历体"}, {"form": "酸化作用", "label": "复合词"}], "register": "科技", "sense_fingerprint": "使水体、土壤等变成酸性（pH降低）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a97e88-3abc-4912-87f4-f7c53757717e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23072, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "酸化", "is_correct": true, "explanation": "正确：「会使湖水酸化」指使水变酸，与前句「酸性物质进入湖泊」的因果关系一致。"}, {"text": "净化", "is_correct": false, "explanation": "语义：「净化」指去除杂质、变干净，与酸性物质带来的污染后果相反。"}, {"text": "澄清", "is_correct": false, "explanation": "语义：「澄清」指水变清澈，与酸性物质的危害不符。"}, {"text": "绿化", "is_correct": false, "explanation": "语义：「绿化」指种树种草、美化环境，用于土地、城市，不是酸性物质进入湖泊的后果。"}], "explanations": {"酸化": "正确：「会使湖水酸化」指使水变酸，与前句「酸性物质进入湖泊」的因果关系一致。", "净化": "语义：「净化」指去除杂质、变干净，与酸性物质带来的污染后果相反。", "澄清": "语义：「澄清」指水变清澈，与酸性物质的危害不符。", "绿化": "语义：「绿化」指种树种草、美化环境，用于土地、城市，不是酸性物质进入湖泊的后果。"}, "sentence_index": 0, "correct_answer": "酸化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种酸液酸化了金属管道。", "explanation": "这里应该用〈腐蚀〉。酸化是使物质变酸，酸液损坏金属应说「腐蚀」。"}, {"text": "用石灰酸化了酸性土壤。", "explanation": "这里应该用〈中和〉。石灰是碱性物质，用它处理酸性土壤是为了降低酸性，应说「中和」。"}, {"text": "冰块放在太阳下，很快就酸化了。", "explanation": "这里应该用〈融化〉。固体受热变成液体叫「融化」，「酸化」指使物质变酸，不能用于冰块。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e44e0593-4a94-4af7-9478-59338c772782') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23072, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "酸化", "is_correct": true, "explanation": "正确：「会让湖泊酸化」指排放的二氧化硫使湖水变酸，与前句的因果关系吻合。"}, {"text": "变红", "is_correct": false, "explanation": "语义：湖泊变红不是二氧化硫排放的后果，与句中的因果关系无关。"}, {"text": "美化", "is_correct": false, "explanation": "语义：「美化」指使环境变美，与排放污染物的语境相反。"}, {"text": "变甜", "is_correct": false, "explanation": "搭配：「变甜」一般用于食物或味道，不能用于湖泊。"}], "explanations": {"酸化": "正确：「会让湖泊酸化」指排放的二氧化硫使湖水变酸，与前句的因果关系吻合。", "变红": "语义：湖泊变红不是二氧化硫排放的后果，与句中的因果关系无关。", "美化": "语义：「美化」指使环境变美，与排放污染物的语境相反。", "变甜": "搭配：「变甜」一般用于食物或味道，不能用于湖泊。"}, "sentence_index": 6, "correct_answer": "酸化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "铁在潮湿的空气中酸化了，表面长出了红锈。", "explanation": "这里应该用〈氧化〉。生锈是氧化反应，「酸化」指物质变酸，与此不符。"}, {"text": "这台电脑用了五年，屏幕已经酸化了。", "explanation": "这里应该用〈老化〉。电脑用久了会老化，「酸化」指物质变成酸性，不能用于电子设备。"}, {"text": "衣服晾在太阳下，很快就酸化了。", "explanation": "这里应该用〈烘干〉。衣服变干是水分蒸发，「酸化」指物质变酸，不能用于衣物干燥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e44e0593-4a94-4af7-9478-59338c772782') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些废水让河水了酸化了。", "corrected_sentence": "这些废水让河水酸化了。", "error_description": "「酸化」是一个不可拆分的词，「了」不能插在它前面。错误：「河水了酸化了」多了一个「了」，应删去「酸化」前的「了」，句末「酸化了」表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e44e0593-4a94-4af7-9478-59338c772782') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "酸性废水让河水酸化的很快。", "corrected_sentence": "酸性废水让河水酸化得很快。", "error_description": "「酸化」后接补语要用助词「得」，不用「的」。错误：「酸化的很快」；正确：「酸化得很快」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e44e0593-4a94-4af7-9478-59338c772782') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
