INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23074, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "模型是照着实物做出来的小样子。", "primary_collocate": null, "pronunciation": "mó xíng", "ipa": "mwo˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "桌子上放着一个飞机的模型。", "target_word": "模型", "complexity_tier": "T3", "furigana": "zhuō zi shàng fàng zhe yí gè fēi jī de mó xíng", "sentence_source": "generated"}, {"text": "弟弟用小木块做了一个房子的模型。", "target_word": "模型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一辆汽车的模型，不是真的车。", "target_word": "模型", "complexity_tier": "T3", "furigana": "zhè shì yí liàng qì chē de mó xíng, bú shì zhēn de chē", "sentence_source": "generated"}, {"text": "老师给我们看了一个地球的模型。", "target_word": "模型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很喜欢火车的模型，家里有很多。", "target_word": "模型", "complexity_tier": "T3", "furigana": "tā hěn xǐ huan huǒ chē de mó xíng, jiā li yǒu hěn duō", "sentence_source": "generated"}, {"text": "这个模型是照着真的船做的，只有手那么大。", "target_word": "模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览馆里有一个大楼的模型，比真楼小很多。", "target_word": "模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我花了三天，才做好这个城市的模型。", "target_word": "模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥买了一个坦克的模型，自己慢慢拼起来。", "target_word": "模型", "complexity_tier": "T3", "furigana": "gē ge mǎi le yí gè tǎn kè de mó xíng, zì jǐ màn màn pīn qǐ lái", "sentence_source": "generated"}, {"text": "小朋友们围着恐龙的模型，看了很久。", "target_word": "模型", "complexity_tier": "T3", "furigana": "xiǎo péng you men wéi zhe kǒng lóng de mó xíng, kàn le hěn jiǔ", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "模型飞机", "label": "复合"}, {"form": "汽车模型", "label": "复合"}], "register": "中性", "sense_fingerprint": "模型:照实物做出的小样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96644a94-d766-4004-bc27-ec755acabdc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23074, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "模型", "is_correct": true, "explanation": "正确：模型指照实物做出的小样子，与“桌子上放着”的语境一致。"}, {"text": "花园", "is_correct": false, "explanation": "语义：飞机不会有花园，“飞机的花园”不成立。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，不能作为飞机的一部分放在桌子上。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然的水体，不能放在桌子上，与“飞机的”不搭配。"}], "explanations": {"模型": "正确：模型指照实物做出的小样子，与“桌子上放着”的语境一致。", "花园": "语义：飞机不会有花园，“飞机的花园”不成立。", "厨房": "语义：厨房是房间，不能作为飞机的一部分放在桌子上。", "河流": "语义：河流是自然的水体，不能放在桌子上，与“飞机的”不搭配。"}, "sentence_index": 0, "correct_answer": "模型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把这张全家福拍成了模型。", "explanation": "这里应该用〈照片〉。模型是照着实物做出的样子，把全家福拍下来要说“照片”，“模型”不能这样用。"}, {"text": "我坐着这个飞机模型去了北京。", "explanation": "这里把“模型”当成了真的飞机。模型是照着实物做出的小样子，不能坐人，也不能飞到别的地方。"}, {"text": "他把这个模型吃掉了，觉得很好吃。", "explanation": "这里把“模型”当成了可以吃的食物。模型是照着实物做出的样子，不是食品，不能说“吃掉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88b10bc5-365c-4b4a-ba4f-220876422222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "模型", "is_correct": true, "explanation": "正确：模型指照真东西做的小样子，与“比真楼小很多”的语境一致。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不能是大楼的样子，与“比真楼小”的语境不符。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼是动物，不能是大楼的小样子，与句子的意思不符。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“大楼的饭”不能这样说，“饭”与“大楼”不搭配。"}], "explanations": {"模型": "正确：模型指照真东西做的小样子，与“比真楼小很多”的语境一致。", "作业": "语义：作业是学习任务，不能是大楼的样子，与“比真楼小”的语境不符。", "鱼": "语义：鱼是动物，不能是大楼的小样子，与句子的意思不符。", "饭": "搭配：“大楼的饭”不能这样说，“饭”与“大楼”不搭配。"}, "sentence_index": 6, "correct_answer": "模型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是班里的模型学生，成绩总是第一名。", "explanation": "这里应该用〈模范〉。“模型”指照着实物做出的样子，表示值得学习的人要用“模范”，两词字形相近，不能混用。"}, {"text": "这个模型是我的弟弟，今年刚上小学。", "explanation": "这里把“模型”误当成了有生命的人。模型是照着实物做出的样子，不是人，不能指弟弟。"}, {"text": "这个模型每天晚上都要睡八个小时。", "explanation": "这里把“模型”误当成了需要睡觉的生命体。模型是没有生命的样子，不需要睡觉，句子不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88b10bc5-365c-4b4a-ba4f-220876422222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在店里买了一只坦克的模型。", "corrected_sentence": "他在店里买了一个坦克的模型。", "error_description": "错误：一只坦克的模型。正确：一个坦克的模型。“只”多用于动物或成对东西中的一个，“模型”一般用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88b10bc5-365c-4b4a-ba4f-220876422222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想要一个很大火车模型。", "corrected_sentence": "我想要一个很大的火车模型。", "error_description": "错误：很大火车模型。正确：很大的火车模型。形容词短语修饰名词时，中间要加“的”，不能直接连在名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88b10bc5-365c-4b4a-ba4f-220876422222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23076, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高", "is_correct": true, "explanation": "正确：高与低是反义词，表示气温的高与低相对。"}, {"text": "快", "is_correct": false, "explanation": "快与低没有反义关系，快说速度。"}, {"text": "厚", "is_correct": false, "explanation": "厚与低没有反义关系，厚说厚薄。"}, {"text": "深", "is_correct": false, "explanation": "深与低没有反义关系，深说深浅。"}], "correct_answer": "高", "explanations": {"高": "正确：高与低是反义词，表示气温的高与低相对。", "快": "快与低没有反义关系，快说速度。", "厚": "厚与低没有反义关系，厚说厚薄。", "深": "深与低没有反义关系，深说深浅。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23076, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高", "is_correct": true, "explanation": "正确：高与低是反义词，“价格不低”的相对说法是价格高。"}, {"text": "亮", "is_correct": false, "explanation": "亮与低没有反义关系，亮说光线明暗。"}, {"text": "薄", "is_correct": false, "explanation": "薄与低没有反义关系，薄说厚薄。"}, {"text": "远", "is_correct": false, "explanation": "远与低没有反义关系，远说距离。"}], "correct_answer": "高", "explanations": {"高": "正确：高与低是反义词，“价格不低”的相对说法是价格高。", "亮": "亮与低没有反义关系，亮说光线明暗。", "薄": "薄与低没有反义关系，薄说厚薄。", "远": "远与低没有反义关系，远说距离。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23076, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "低就是从上到下距离小，或数量、程度小。", "primary_collocate": null, "pronunciation": "dī", "ipa": "ti˥", "syllable_count": 1, "sentences": [{"text": "这张桌子太低了。", "target_word": "低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树的树枝很低，孩子伸手就能摸到。", "target_word": "低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的价格比别家低。", "target_word": "低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的气温很低。", "target_word": "低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座桥很低，大车过不去。", "target_word": "低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把椅子太低，我坐着不舒服。", "target_word": "低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的成绩比他低。", "target_word": "低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水温太低，不能游泳。", "target_word": "低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机飞得很低。", "target_word": "低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裤子的价格不低。", "target_word": "低", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "低低", "label": "重叠"}, {"form": "降低", "label": "复合"}, {"form": "低温", "label": "复合"}], "register": "中性", "sense_fingerprint": "从上到下距离小，或数量、程度小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: 3 words above tier T1 (max 2): 棵 (Zipf 3.72), 树枝 (Zipf 3.69), 伸手 (Zipf 3.8)','sentence 4 above tier T1: 3 words above tier T1 (max 2): 那座 (Zipf 3.06), 大车 (Zipf 3.16), 过不去 (Zipf 3.62)']::text[], '9d952261-361f-4475-b6c1-65e9db11d94e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23076, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "低", "is_correct": true, "explanation": "正确：低 dī（第一声），表示从上到下距离小或数量、程度小，与“太低了”相合。"}, {"text": "底", "is_correct": false, "explanation": "dǐ（第三声）与 dī（第一声）声调不同，意思是底部。"}, {"text": "敌", "is_correct": false, "explanation": "dí（第二声）与 dī（第一声）声调不同，意思是敌人。"}, {"text": "梯", "is_correct": false, "explanation": "tī（第一声）与 dī 声母不同（t 与 d），意思是楼梯。"}, {"text": "弟", "is_correct": false, "explanation": "dì（第四声）与 dī（第一声）声调不同，意思是弟弟。"}], "explanations": {"低": "正确：低 dī（第一声），表示从上到下距离小或数量、程度小，与“太低了”相合。", "底": "dǐ（第三声）与 dī（第一声）声调不同，意思是底部。", "敌": "dí（第二声）与 dī（第一声）声调不同，意思是敌人。", "梯": "tī（第一声）与 dī 声母不同（t 与 d），意思是楼梯。", "弟": "dì（第四声）与 dī（第一声）声调不同，意思是弟弟。"}, "sentence_index": null, "correct_answer": "低"}, "level_3": {"options": [{"text": "低", "is_correct": true, "explanation": "正确：低表示从上到下距离小，“太低了”说桌子的高度不合适。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：甜形容味道，不能用来描述桌子的高矮。"}, {"text": "慢", "is_correct": false, "explanation": "语义：慢说速度，与桌子的高矮无关。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：聪明形容人或动物的智力，不能用于桌子。"}], "explanations": {"低": "正确：低表示从上到下距离小，“太低了”说桌子的高度不合适。", "甜": "搭配：甜形容味道，不能用来描述桌子的高矮。", "慢": "语义：慢说速度，与桌子的高矮无关。", "聪明": "搭配：聪明形容人或动物的智力，不能用于桌子。"}, "sentence_index": 0, "correct_answer": "低"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他低着头，不说话。", "explanation": "这里的“低”是动词，意思是“使向下垂”，不是“从上到下距离小”或“数量、程度小”的意思。"}, {"text": "我们低估了这次考试的难度。", "explanation": "这里的“低”是“低估”的意思，表示估计不够高，是动词用法，与“从上到下距离小”或“数量、程度小”的意思不同。"}, {"text": "这张纸很低。", "explanation": "这里应该用〈薄〉。低说高度或位置，不说厚薄，形容纸的厚薄要用薄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23076, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "低", "is_correct": true, "explanation": "正确：低 dī（第一声），表示从上到下距离小或数量、程度小。"}, {"text": "第", "is_correct": false, "explanation": "dì（第四声）与 dī（第一声）声调不同，意思是顺序，如“第一”。"}, {"text": "踢", "is_correct": false, "explanation": "tī（第一声）与 dī 声母不同（t 与 d），意思是用脚击打。"}, {"text": "笛", "is_correct": false, "explanation": "dí（第二声）与 dī（第一声）声调不同，意思是笛子。"}], "explanations": {"低": "正确：低 dī（第一声），表示从上到下距离小或数量、程度小。", "第": "dì（第四声）与 dī（第一声）声调不同，意思是顺序，如“第一”。", "踢": "tī（第一声）与 dī 声母不同（t 与 d），意思是用脚击打。", "笛": "dí（第二声）与 dī（第一声）声调不同，意思是笛子。"}, "sentence_index": null, "correct_answer": "低"}, "level_3": {"options": [{"text": "低", "is_correct": true, "explanation": "正确：“成绩比他低”用低比较成绩的高低，搭配自然。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：矮形容人或物的身高，不能用来说成绩的高低。"}, {"text": "快", "is_correct": false, "explanation": "语义：快说速度，与成绩的高低无关。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：胖形容身体的样子，不能用于成绩。"}], "explanations": {"低": "正确：“成绩比他低”用低比较成绩的高低，搭配自然。", "矮": "体貌：矮形容人或物的身高，不能用来说成绩的高低。", "快": "语义：快说速度，与成绩的高低无关。", "胖": "体貌：胖形容身体的样子，不能用于成绩。"}, "sentence_index": 6, "correct_answer": "低"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影的内容太低俗了。", "explanation": "这里的“低”是“低俗”的意思，形容内容庸俗，与“从上到下距离小”或“数量、程度小”的意思不同。"}, {"text": "不要低估对手的实力。", "explanation": "这里的“低”是“低估”的意思，表示估计不够高，是动词用法，与“从上到下距离小”或“数量、程度小”的意思不同。"}, {"text": "她低下头看书。", "explanation": "这里的“低”是动词，表示把头向下垂，不是形容“距离小或程度小”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把行李放很低。", "corrected_sentence": "他把行李放得很低。", "error_description": "错误形式：“放很低”；正确形式：“放得很低”。动词后接形容词短语作状态补语时，中间要加结构助词“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋顶低很，我们要弯着腰走路。", "corrected_sentence": "屋顶很低，我们要弯着腰走路。", "error_description": "错误形式：“低很”；正确形式：“很低”。“很”作状语修饰形容词，应放在“低”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
