INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23080, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放进坑里，用土盖上。", "primary_collocate": null, "pronunciation": "tián mái", "ipa": "tʰjɛn³⁵ maɪ³⁵", "syllable_count": 2, "sentences": [{"text": "工人把垃圾运到山谷里填埋。", "target_word": "填埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些废物不能烧，只能填埋。", "target_word": "填埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市的垃圾大多送到郊外填埋。", "target_word": "填埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们挖了一个大坑，准备填埋旧轮胎。", "target_word": "填埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "填埋垃圾的地方离村子很远。", "target_word": "填埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们把旧家具运到河边，填埋在坑里。", "target_word": "填埋", "complexity_tier": "T3", "furigana": "gōng rén men bǎ jiù jiā jù yùn dào hé biān, tián mái zài kēng lǐ.", "sentence_source": "generated"}, {"text": "为了保护环境，这里禁止随便填埋废油。", "target_word": "填埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把坏菜叶填埋在地里当肥料。", "target_word": "填埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾填埋以后，上面种了很多草。", "target_word": "填埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "填埋以前，工人先在坑底铺了一层布。", "target_word": "填埋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "填埋了", "label": "体标"}, {"form": "填埋过", "label": "体标"}, {"form": "填埋场", "label": "复合"}], "register": "书面", "sense_fingerprint": "填埋|动词|把东西放进坑里，用土盖上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f735cfaa-c81a-4eea-8896-d7ab5126a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23080, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "填埋", "is_correct": true, "explanation": "正确。填埋指把东西埋进坑里用土盖上，与“运到山谷里”相合。"}, {"text": "种", "is_correct": false, "explanation": "语义：“种”是栽植植物，垃圾不能种到山谷里。"}, {"text": "搭", "is_correct": false, "explanation": "搭配：“搭”用于搭棚子、架桥等建造，不能搭垃圾。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是用水清除污物，与“运到山谷里”的处理方式不合。"}], "explanations": {"填埋": "正确。填埋指把东西埋进坑里用土盖上，与“运到山谷里”相合。", "种": "语义：“种”是栽植植物，垃圾不能种到山谷里。", "搭": "搭配：“搭”用于搭棚子、架桥等建造，不能搭垃圾。", "洗": "语义：“洗”是用水清除污物，与“运到山谷里”的处理方式不合。"}, "sentence_index": 0, "correct_answer": "填埋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在枕头里填埋了羽毛。", "explanation": "这里应该用〈填充〉。填埋指把东西埋进坑里用土盖上，装进枕头里的羽毛要用填充。"}, {"text": "请在表格里填埋姓名。", "explanation": "这里应该用〈填写〉。填写指在表格上写上内容，填埋不能用于写字。"}, {"text": "他用水泥填埋了墙上的裂缝。", "explanation": "这里应该用〈填补〉。填埋用于把废物埋进坑里，补墙上的裂缝要用填补。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23080, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "填埋", "is_correct": true, "explanation": "正确。填埋是把废油埋进坑里用土盖上，与“禁止随便”和环保语境相合。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能以废油为宾语，“唱废油”不成立。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”是把一种语言转成另一种，与废油无关。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”用于拆房屋、机器等有结构的东西，不用于液态的废油。"}], "explanations": {"填埋": "正确。填埋是把废油埋进坑里用土盖上，与“禁止随便”和环保语境相合。", "唱": "搭配：“唱”不能以废油为宾语，“唱废油”不成立。", "翻译": "语义：“翻译”是把一种语言转成另一种，与废油无关。", "拆": "搭配：“拆”用于拆房屋、机器等有结构的东西，不用于液态的废油。"}, "sentence_index": 6, "correct_answer": "填埋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人们在山上填埋了老人。", "explanation": "这里应该用〈埋葬〉。填埋是把废物倒进坑里用土盖上，不用于人；埋葬用于安葬死者。"}, {"text": "他用胶水填埋了破碗。", "explanation": "这里应该用〈修补〉。填埋指把废物埋进坑里，修补破碗要用修补。"}, {"text": "他的才华被填埋了。", "explanation": "这里应该用〈埋没〉。才华不能用土掩埋，“埋没”指才能不被人发现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23080, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把一本废旧轮胎填埋了。", "corrected_sentence": "工人把一个废旧轮胎填埋了。", "error_description": "“轮胎”的量词应用“个”或“条”，不能用“本”；“本”用于书本等装订成册的东西，应说“一个废旧轮胎”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把废油填埋坑里。", "corrected_sentence": "工人把废油填埋在坑里。", "error_description": "“填埋”后面引出处所时要用“在”，漏掉“在”句子不成立，应说“填埋在坑里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
