INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23084, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有机质是土里面和烂掉的东西里的一种物质，能帮助植物长大。", "primary_collocate": null, "pronunciation": "yǒu jī zhì", "ipa": "joʊ˨˩˦ tɕi˥ ʈʂɨ˥˩", "syllable_count": 3, "sentences": [{"text": "土里的有机质能帮花草长大。", "target_word": "有机质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烂叶子里有很多有机质。", "target_word": "有机质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块地的有机质太少，草长不好。", "target_word": "有机质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把烂掉的菜叶放进土里，增加有机质。", "target_word": "有机质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花盆里的土需要有机质。", "target_word": "有机质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有机质让土变得很黑很软。", "target_word": "有机质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明往花盆里加了一些有机质。", "target_word": "有机质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土壤里的有机质越多，菜长得越好。", "target_word": "有机质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，烂掉的水果也能变成有机质。", "target_word": "有机质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好土一般含有很多有机质。", "target_word": "有机质", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "有机质含量", "label": "复合词"}, {"form": "土壤有机质", "label": "复合词"}], "register": "科技", "sense_fingerprint": "土里和烂东西里帮助植物长大的物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a97e88-3abc-4912-87f4-f7c53757717e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23084, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有机质", "is_correct": true, "explanation": "正确：「土里的有机质」能给花草提供养分，与句意一致。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能为花草提供养分，句意不通。"}, {"text": "塑料", "is_correct": false, "explanation": "语义：塑料不能被植物吸收，也不会帮助花草生长。"}, {"text": "钢筋", "is_correct": false, "explanation": "语义：钢筋是金属，不能被植物吸收，也不会帮助花草生长，句意不通。"}], "explanations": {"有机质": "正确：「土里的有机质」能给花草提供养分，与句意一致。", "石头": "语义：石头不能为花草提供养分，句意不通。", "塑料": "语义：塑料不能被植物吸收，也不会帮助花草生长。", "钢筋": "语义：钢筋是金属，不能被植物吸收，也不会帮助花草生长，句意不通。"}, "sentence_index": 0, "correct_answer": "有机质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用有机质擦干净了黑板。", "explanation": "这里应该用〈抹布〉。有机质是土里或烂东西里的物质，不能用来擦黑板。"}, {"text": "墙面上刷了一层白色有机质。", "explanation": "这里应该用〈涂料〉。墙面刷的是涂料，有机质不能用来刷墙。"}, {"text": "他用有机质给手机充电。", "explanation": "这里应该用〈充电宝〉。有机质是土里的物质，不能给手机充电。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e44e0593-4a94-4af7-9478-59338c772782') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23084, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有机质", "is_correct": true, "explanation": "正确：往花盆里加有机质能让土更肥，帮助植物生长。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃碎片不会让土变肥，往花盆里加玻璃不合常理。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气不能说“加了一些”放进花盆。"}, {"text": "钉子", "is_correct": false, "explanation": "语义：钉子是金属，不能帮植物生长，句意不合。"}], "explanations": {"有机质": "正确：往花盆里加有机质能让土更肥，帮助植物生长。", "玻璃": "语义：玻璃碎片不会让土变肥，往花盆里加玻璃不合常理。", "空气": "搭配：空气不能说“加了一些”放进花盆。", "钉子": "语义：钉子是金属，不能帮植物生长，句意不合。"}, "sentence_index": 6, "correct_answer": "有机质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "菜里放了一勺有机质。", "explanation": "这里应该用〈盐〉。有机质不是调味品，做菜放一勺应说「盐」。"}, {"text": "这把刀是用有机质做的。", "explanation": "这里应该用〈钢〉。刀是用钢做的，有机质不能做刀。"}, {"text": "这块透明的玻璃是用有机质制成的。", "explanation": "这里应该用〈沙子〉。玻璃是由沙子等无机材料制成的，有机质不能用来制玻璃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e44e0593-4a94-4af7-9478-59338c772782') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "土里加了不少个有机质。", "corrected_sentence": "土里加了不少有机质。", "error_description": "「有机质」是物质名词，前面不能加量词「个」，应直接说「不少有机质」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e44e0593-4a94-4af7-9478-59338c772782') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片林子的有机质含量得很低。", "corrected_sentence": "这片林子的有机质含量很低。", "error_description": "「有机质含量」后直接接形容词「很低」作谓语，不用助词「得」。错误：「含量得很低」；正确：「含量很低」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e44e0593-4a94-4af7-9478-59338c772782') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
