INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23088, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "温室是一个可以种花种菜的小房子，里面很暖和。", "primary_collocate": null, "pronunciation": "wēn shì", "ipa": "wən˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这个温室很小，里面种着青菜。", "target_word": "温室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪了，可是温室里还很暖和。", "target_word": "温室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在温室里种了一些花。", "target_word": "温室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温室的门一打开，我就觉得很热。", "target_word": "温室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷用塑料布盖了一个小温室。", "target_word": "温室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温室里的黄瓜长得很快。", "target_word": "温室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们跟老师去参观温室。", "target_word": "温室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天还没到，温室里的花已经开了。", "target_word": "温室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个温室可以种菜，也可以种花。", "target_word": "温室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把温室的窗户关好。", "target_word": "温室", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "里面暖和、可以种花种菜的小房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '248b86e3-a7bf-40e2-bf37-3951132d833d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23088, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "温室", "is_correct": true, "explanation": "正确答案。温室是一个可以种花种菜的小房子，里面很暖和。"}, {"text": "问世", "is_correct": false, "explanation": "wèn（第四声）与 wēn（第一声）声调不同，意思是作品或事物公开出现，不是小房子。"}, {"text": "纹饰", "is_correct": false, "explanation": "wén（第二声）与 wēn（第一声）声调不同，意思是器物上的装饰花纹，不是小房子。"}, {"text": "文史", "is_correct": false, "explanation": "wén 与 wēn 声调不同，shǐ 与 shì 声调也不同，意思是文学和历史，不是小房子。"}], "explanations": {"温室": "正确答案。温室是一个可以种花种菜的小房子，里面很暖和。", "问世": "wèn（第四声）与 wēn（第一声）声调不同，意思是作品或事物公开出现，不是小房子。", "纹饰": "wén（第二声）与 wēn（第一声）声调不同，意思是器物上的装饰花纹，不是小房子。", "文史": "wén 与 wēn 声调不同，shǐ 与 shì 声调也不同，意思是文学和历史，不是小房子。"}, "sentence_index": null, "correct_answer": "温室"}, "level_3": {"options": [{"text": "温室", "is_correct": true, "explanation": "正确。「这个温室很小，里面种着青菜」描述的是可以种菜的小房子。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱用来冷藏食物，里面不能种青菜，与后半句矛盾。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：「种着」的对象应是植物所在的空间，「手机」与「里面种着青菜」不搭配。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是金融机构，不能在里面种青菜。"}], "explanations": {"温室": "正确。「这个温室很小，里面种着青菜」描述的是可以种菜的小房子。", "冰箱": "语义：冰箱用来冷藏食物，里面不能种青菜，与后半句矛盾。", "手机": "搭配：「种着」的对象应是植物所在的空间，「手机」与「里面种着青菜」不搭配。", "银行": "语义：银行是金融机构，不能在里面种青菜。"}, "sentence_index": 0, "correct_answer": "温室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冬天我们去温室泡澡，很舒服。", "explanation": "这里应该用〈温泉〉。泡澡要在温泉里，温室是种植植物的小房子，不能泡澡。"}, {"text": "早上起来，屋里的温室只有五度。", "explanation": "这里应该用〈温度〉。温室指种植植物的小房子，不能表示屋里冷热的程度；说温度多少要用〈温度〉。"}, {"text": "早晚的温室相差很大，要多穿衣服。", "explanation": "这里应该用〈温差〉。温室不能表示早晚之间的温度变化；说温度相差多少要用〈温差〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e51765ac-7a12-4cb6-bd4f-0f6d3ccc9522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23088, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不是可以参观的场所，与「去参观」不符。"}, {"text": "电话", "is_correct": false, "explanation": "搭配：「参观」的对象通常是场所或展览，「电话」不能搭配。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日用品，不是能被参观的地方，句意不通。"}, {"text": "温室", "is_correct": true, "explanation": "正确。「孩子们跟老师去参观温室」指去看种植植物的小房子。"}], "explanations": {"闹钟": "语义：闹钟不是可以参观的场所，与「去参观」不符。", "电话": "搭配：「参观」的对象通常是场所或展览，「电话」不能搭配。", "雨伞": "语义：雨伞是日用品，不是能被参观的地方，句意不通。", "温室": "正确。「孩子们跟老师去参观温室」指去看种植植物的小房子。"}, "sentence_index": 6, "correct_answer": "温室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "草莓要放进温室冷藏才行。", "explanation": "这里应该用〈冰箱〉。冷藏食物要用冰箱，温室是种植植物的小房子。"}, {"text": "妈妈用温室烤了一块蛋糕。", "explanation": "这里应该用〈烤箱〉。烤箱用来烤食物，温室不能用来烤蛋糕。"}, {"text": "温室把衣服洗干净了。", "explanation": "这里应该用〈洗衣机〉。洗衣服要用洗衣机，温室是种植植物的小房子，不能用来洗衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e51765ac-7a12-4cb6-bd4f-0f6d3ccc9522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23088, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里有一只小温室，可以种菜。", "corrected_sentence": "院子里有一座小温室，可以种菜。", "error_description": "量词错误：温室是房屋，应用「座」（或「个」），「只」用于动物等，不能修饰温室。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e51765ac-7a12-4cb6-bd4f-0f6d3ccc9522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23088, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈每天在温室上浇花。", "corrected_sentence": "妈妈每天在温室里浇花。", "error_description": "方位词错误：温室是封闭的小房子，应用「里」，「上」用于物体表面，不能说「温室上」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e51765ac-7a12-4cb6-bd4f-0f6d3ccc9522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
