INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23098, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "碳的单质，如石墨、木炭，是黑色固体，可用来写字。", "primary_collocate": null, "pronunciation": "tàn sù", "ipa": "tʰan˥˩ su˥˩", "syllable_count": 2, "sentences": [{"text": "碳素是一种黑色的固体。", "target_word": "碳素", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "碳素是黑色固体，古人常用它来写字。", "target_word": "碳素", "complexity_tier": "T3", "furigana": "tàn sù shì hēi sè gù tǐ，gǔ rén cháng yòng tā lái xiě zì。", "sentence_source": "generated"}, {"text": "铅笔芯里有碳素，所以写出来是黑色的。", "target_word": "碳素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古人用这块黑色的碳素在竹简上写字。", "target_word": "碳素", "complexity_tier": "T3", "furigana": "gǔ rén yòng zhè kuài hēi sè de tàn sù zài zhú jiǎn shàng xiě zì。", "sentence_source": "generated"}, {"text": "碳素是古人写字画画常用的材料。", "target_word": "碳素", "complexity_tier": "T3", "furigana": "tàn sù shì gǔ rén xiě zì huà huà cháng yòng de cái liào。", "sentence_source": "generated"}, {"text": "碳素很黑，一摸手就黑了。", "target_word": "碳素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火烧完以后，木头变成了黑色的碳素。", "target_word": "碳素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古人用碳素在木板上画线，线很黑。", "target_word": "碳素", "complexity_tier": "T3", "furigana": "gǔ rén yòng tàn sù zài mù bǎn shàng huà xiàn，xiàn hěn hēi。", "sentence_source": "generated"}, {"text": "老师说，碳素不会溶在水里。", "target_word": "碳素", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "古代画家用碳素勾勒线条，画出黑白的画。", "target_word": "碳素", "complexity_tier": "T3", "furigana": "gǔ dài huà jiā yòng tàn sù gōu lè xiàn tiáo，huà chū hēi bái de huà。", "sentence_source": "generated"}], "morphological_forms": [{"form": "碳素钢", "label": "复合"}], "register": "书面", "sense_fingerprint": "碳素|黑色固体，可以写字画画", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab623cb5-ee24-4aec-89c3-b126ca65d1ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23098, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "碳素", "is_correct": true, "explanation": "碳素：指黑色固体的碳，符合句意。"}, {"text": "氧气", "is_correct": false, "explanation": "语义：氧气是无色的气体，与“黑色的固体”矛盾。"}, {"text": "水", "is_correct": false, "explanation": "语义：水是无色的液体，不可能是黑色的固体。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“是一种……固体”的主语须是固体物质，空气是混合气体，不搭配。"}], "explanations": {"碳素": "碳素：指黑色固体的碳，符合句意。", "氧气": "语义：氧气是无色的气体，与“黑色的固体”矛盾。", "水": "语义：水是无色的液体，不可能是黑色的固体。", "空气": "搭配：“是一种……固体”的主语须是固体物质，空气是混合气体，不搭配。"}, "sentence_index": 0, "correct_answer": "碳素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯水里溶解了很多碳素。", "explanation": "这里应该用〈食盐〉。碳素是不溶于水的黑色固体，不能说溶解在水里；能溶解的是食盐等可溶物质。"}, {"text": "这块碳素很甜，孩子很爱吃。", "explanation": "这里应该用〈糖果〉。碳素是黑色固体，不是甜味食品，不能说很甜。"}, {"text": "这位画家用碳素画出了彩色的画。", "explanation": "这里应该用〈颜料〉。碳素是黑色的，只能画出黑色的线条，画不出彩色的画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db74969-bc3a-4f78-be8a-a16ad1d7ff90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23098, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "碳素", "is_correct": true, "explanation": "碳素：木头烧后剩下的黑色固体，与句意相合。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：木头烧后变成的是固体碳，不会变成墨水。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“黑色的玻璃”指玻璃制品，木头不会变成玻璃。"}, {"text": "铁", "is_correct": false, "explanation": "语义：木头不会变成金属铁，与“火烧”后的产物不符。"}], "explanations": {"碳素": "碳素：木头烧后剩下的黑色固体，与句意相合。", "墨水": "语义：木头烧后变成的是固体碳，不会变成墨水。", "玻璃": "搭配：“黑色的玻璃”指玻璃制品，木头不会变成玻璃。", "铁": "语义：木头不会变成金属铁，与“火烧”后的产物不符。"}, "sentence_index": 6, "correct_answer": "碳素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块碳素在黑板上写出了白色的字。", "explanation": "这里应该用〈粉笔〉。碳素是黑色的，写出的字不会是白色。"}, {"text": "孩子用碳素画了一朵红色的花。", "explanation": "这里应该用〈蜡笔〉。碳素是黑色的，画不出红色的花。"}, {"text": "墙上刷了一层白色的碳素。", "explanation": "这里应该用〈油漆〉。碳素是黑色的，不能刷成白色的墙面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db74969-bc3a-4f78-be8a-a16ad1d7ff90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23098, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古人用这只碳素写字，字迹很黑。", "corrected_sentence": "古人用这块碳素写字，字迹很黑。", "error_description": "量词错误：碳素是块状固体，量词应用“块”，说“这块碳素”，不能用“这只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db74969-bc3a-4f78-be8a-a16ad1d7ff90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23098, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古人用这条碳素在木板上写字。", "corrected_sentence": "古人用这块碳素在木板上写字。", "error_description": "量词错误：碳素是块状固体，量词应用“块”，说“这块碳素”，不能用“这条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db74969-bc3a-4f78-be8a-a16ad1d7ff90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
