INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23116, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "土壤是花草树木生长的地方，就是泥土。", "primary_collocate": null, "pronunciation": "tǔ rǎng", "ipa": "tʰu˨˩˦ ɻɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这里的土壤很适合种茶。", "target_word": "土壤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物需要水和肥沃的土壤。", "target_word": "土壤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水太多，土壤变得很湿。", "target_word": "土壤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在改善土壤，让庄稼长得更好。", "target_word": "土壤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片土壤里有很多小虫子。", "target_word": "土壤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠的土壤太干，花草很难生长。", "target_word": "土壤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他蹲下来，看了看地里的土壤。", "target_word": "土壤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的污水会污染土壤。", "target_word": "土壤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的土壤能让种子长得快。", "target_word": "土壤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，土壤变软了。", "target_word": "土壤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "土壤层", "label": "复合"}], "register": "中性", "sense_fingerprint": "植物生长的泥土", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ab50cd-4340-49f3-b7d1-188a43322068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23116, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "土壤", "is_correct": true, "explanation": "土壤：植物生长的泥土，所以这里“适合种茶”。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不是植物生长的环境，不能“种茶”，句意不通。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是人，不是种植的环境，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“适合种茶”说土地、气候，不说价格。"}], "explanations": {"土壤": "土壤：植物生长的泥土，所以这里“适合种茶”。", "房子": "语义：房子不是植物生长的环境，不能“种茶”，句意不通。", "老师": "语义：老师是人，不是种植的环境，句意不通。", "价格": "搭配：“适合种茶”说土地、气候，不说价格。"}, "sentence_index": 0, "correct_answer": "土壤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题的土壤很难，大家都没做出来。", "explanation": "这里应该用〈题目〉。土壤指泥土，说题目的难易要用“题目”。"}, {"text": "她的土壤又白又圆。", "explanation": "这里应该用〈脸〉。土壤指泥土，形容人的脸色和脸型要用脸。"}, {"text": "这块土壤是古代留下来的文物。", "explanation": "这里应该用〈瓷器〉。土壤指泥土的成分，不是古代留下来的器物，要说瓷器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23116, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "土壤", "is_correct": true, "explanation": "土壤：地里的泥土，他蹲下来看的就是它。"}, {"text": "电视", "is_correct": false, "explanation": "语义：地里不会有电视，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：地里不会有桌子，句意不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“看”说文字、图像，“歌曲”要用“听”，搭配不当。"}], "explanations": {"土壤": "土壤：地里的泥土，他蹲下来看的就是它。", "电视": "语义：地里不会有电视，句意不通。", "桌子": "语义：地里不会有桌子，句意不通。", "歌曲": "搭配：“看”说文字、图像，“歌曲”要用“听”，搭配不当。"}, "sentence_index": 6, "correct_answer": "土壤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的土壤很光滑。", "explanation": "这里应该用〈皮肤〉。土壤指泥土，形容人的皮肤要用皮肤。"}, {"text": "晴朗的土壤没有一朵云。", "explanation": "这里应该用〈天空〉。土壤指泥土，天上有没有云要说天空。"}, {"text": "这首歌的土壤很好听。", "explanation": "这里应该用〈旋律〉。土壤指泥土，形容歌曲的好听要用旋律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只土壤很肥沃。", "corrected_sentence": "这片土壤很肥沃。", "error_description": "量词错误：“土壤”要用“片”，不能用“只”。“只”多用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里得土壤很肥沃。", "corrected_sentence": "这里的土壤很肥沃。", "error_description": "结构助词错误：修饰名词“土壤”的定语后要用结构助词“的”，不能用“得”（“得”多用于动词后的补语）。应说“这里的土壤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
