INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23120, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "甲烷是一种没有颜色没有味道的气体，可以燃烧。", "primary_collocate": null, "pronunciation": "jiǎ wán", "ipa": "tɕja˨˩˦ wan˧˥", "syllable_count": 2, "sentences": [{"text": "甲烷是一种没有颜色的气体。", "target_word": "甲烷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "甲烷可以燃烧，所以能做燃料。", "target_word": "甲烷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你闻不到甲烷，因为它没有味道。", "target_word": "甲烷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的天然气主要是甲烷。", "target_word": "甲烷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沼气池里有很多甲烷。", "target_word": "甲烷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "甲烷遇到火就会烧起来。", "target_word": "甲烷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用机器检查矿井里有没有甲烷。", "target_word": "甲烷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛每天都会放出一些甲烷。", "target_word": "甲烷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶子里装着甲烷。", "target_word": "甲烷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要少让甲烷跑到空气里。", "target_word": "甲烷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "无色无味、可以燃烧的气体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '248b86e3-a7bf-40e2-bf37-3951132d833d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "甲烷", "is_correct": true, "explanation": "正确。「甲烷是一种没有颜色的气体」说的就是甲烷。"}, {"text": "白糖", "is_correct": false, "explanation": "搭配：「没有颜色的气体」只能修饰气体，白糖是固体，不能说成「白糖是一种……的气体」。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是固体，不是气体，与「气体」的说明矛盾。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是固体材料，不是气体，与「没有颜色的气体」不符。"}], "explanations": {"甲烷": "正确。「甲烷是一种没有颜色的气体」说的就是甲烷。", "白糖": "搭配：「没有颜色的气体」只能修饰气体，白糖是固体，不能说成「白糖是一种……的气体」。", "石头": "语义：石头是固体，不是气体，与「气体」的说明矛盾。", "玻璃": "语义：玻璃是固体材料，不是气体，与「没有颜色的气体」不符。"}, "sentence_index": 0, "correct_answer": "甲烷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "早饭我喝了一杯甲烷。", "explanation": "这里应该用〈牛奶〉。甲烷是气体，不能喝，喝的应是牛奶等液体。"}, {"text": "病人呼吸困难，医生马上给他吸甲烷。", "explanation": "这里应该用〈氧气〉。给病人吸的是氧气，甲烷是可燃气体，不能用来供人呼吸。"}, {"text": "这扇窗户是用甲烷做的。", "explanation": "这里应该用〈玻璃〉。甲烷是气体，不能用来做窗户。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e51765ac-7a12-4cb6-bd4f-0f6d3ccc9522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西瓜", "is_correct": false, "explanation": "语义：检查的对象应是矿井里可能存在的有害气体，西瓜不符合语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：「检查……有没有」的对象不能是家用电器，与「矿井里」搭配不通。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，矿井里不会检测到它，句意不通。"}, {"text": "甲烷", "is_correct": true, "explanation": "正确。矿井中需要用机器检查的是甲烷等有害气体。"}], "explanations": {"西瓜": "语义：检查的对象应是矿井里可能存在的有害气体，西瓜不符合语境。", "冰箱": "搭配：「检查……有没有」的对象不能是家用电器，与「矿井里」搭配不通。", "饼干": "语义：饼干是食品，矿井里不会检测到它，句意不通。", "甲烷": "正确。矿井中需要用机器检查的是甲烷等有害气体。"}, "sentence_index": 6, "correct_answer": "甲烷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师用甲烷写字。", "explanation": "这里应该用〈粉笔〉。写字要用粉笔等书写工具，甲烷是气体，不能用来写字。"}, {"text": "下雨了，他撑着甲烷。", "explanation": "这里应该用〈雨伞〉。撑的是雨伞，甲烷是气体，不能用来撑。"}, {"text": "我喜欢吃甲烷。", "explanation": "这里应该用〈糖〉。甲烷是气体，不能吃，喜欢吃的应是糖之类的食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e51765ac-7a12-4cb6-bd4f-0f6d3ccc9522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个钢瓶里装着一颗甲烷。", "corrected_sentence": "这个钢瓶里装着一罐甲烷。", "error_description": "量词错误：甲烷是气体，应用「罐」等容器量词，「颗」用于小而圆的东西，不能修饰甲烷。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e51765ac-7a12-4cb6-bd4f-0f6d3ccc9522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "瓶子里的甲烷漏来出了。", "corrected_sentence": "瓶子里的甲烷漏出来了。", "error_description": "补语语序错误：「漏出来」是动词加趋向补语的结构，应说「漏出来」，不能说「漏来出」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e51765ac-7a12-4cb6-bd4f-0f6d3ccc9522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
