INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23122, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别人告诉你想法或结果，你再告诉别人。", "primary_collocate": null, "pronunciation": "fǎn kuì", "ipa": "fan˨˩˦ kʰweɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "小王的意见我已经反馈给经理了。", "target_word": "反馈", "complexity_tier": "T3", "furigana": "xiǎo wáng de yìjiàn wǒ yǐjīng fǎnkuì gěi jīnglǐ le", "sentence_source": "generated"}, {"text": "我已经把考试成绩反馈给家长了。", "target_word": "反馈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们的意见班长已经反馈给老师了。", "target_word": "反馈", "complexity_tier": "T3", "furigana": "tóngxuémen de yìjiàn bānzhǎng yǐjīng fǎnkuì gěi lǎoshī le", "sentence_source": "generated"}, {"text": "经理的几点建议我已经反馈给团队了。", "target_word": "反馈", "complexity_tier": "T3", "furigana": "jīnglǐ de jǐ diǎn jiànyì wǒ yǐjīng fǎnkuì gěi tuánduì le", "sentence_source": "generated"}, {"text": "客户的问题我马上反馈给技术部。", "target_word": "反馈", "complexity_tier": "T3", "furigana": "kèhù de wèntí wǒ mǎshàng fǎnkuì gěi jìshùbù", "sentence_source": "generated"}, {"text": "客服已经把这条投诉反馈给后台了。", "target_word": "反馈", "complexity_tier": "T3", "furigana": "kèfú yǐjīng bǎ zhè tiáo tóusù fǎnkuì gěi hòutái le", "sentence_source": "generated"}, {"text": "他把检查结果反馈给了医生。", "target_word": "反馈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你收到的消息记得反馈给我。", "target_word": "反馈", "complexity_tier": "T3", "furigana": "nǐ shōudào de xiāoxi jìde fǎnkuì gěi wǒ", "sentence_source": "generated"}, {"text": "上面的通知她已经反馈给大家了。", "target_word": "反馈", "complexity_tier": "T3", "furigana": "shàngmiàn de tōngzhī tā yǐjīng fǎnkuì gěi dàjiā le", "sentence_source": "generated"}, {"text": "她很快就把这个结果反馈给了同事。", "target_word": "反馈", "complexity_tier": "T3", "furigana": "tā hěn kuài jiù bǎ zhège jiéguǒ fǎnkuì gěi le tóngshì", "sentence_source": "generated"}], "morphological_forms": [{"form": "反馈了", "label": "体标"}, {"form": "反馈过", "label": "体标"}, {"form": "反馈意见", "label": "复合"}], "register": "中性", "sense_fingerprint": "把得到的想法或结果再告诉别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '248b86e3-a7bf-40e2-bf37-3951132d833d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23122, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "反馈", "is_correct": true, "explanation": "正确。听到的是“反馈”fǎnkuì，指把得到的想法或结果再告诉别人。"}, {"text": "反对", "is_correct": false, "explanation": "反对 fǎnduì 与 反馈 只差声母：duì 的 d 与 kuì 的 k 不同，意思是持不同意见或抵制。"}, {"text": "反悔", "is_correct": false, "explanation": "反悔 fǎnhuǐ 与 反馈 只有第二音节不同：huǐ 与 kuì 的声母和声调都不同，意思是后悔、改变承诺。"}, {"text": "返回", "is_correct": false, "explanation": "返回 fǎnhuí 与 反馈 只有第二音节不同：huí（第二声）与 kuì（第四声），意思是回到原处，与反馈无关。"}], "explanations": {"反馈": "正确。听到的是“反馈”fǎnkuì，指把得到的想法或结果再告诉别人。", "反对": "反对 fǎnduì 与 反馈 只差声母：duì 的 d 与 kuì 的 k 不同，意思是持不同意见或抵制。", "反悔": "反悔 fǎnhuǐ 与 反馈 只有第二音节不同：huǐ 与 kuì 的声母和声调都不同，意思是后悔、改变承诺。", "返回": "返回 fǎnhuí 与 反馈 只有第二音节不同：huí（第二声）与 kuì（第四声），意思是回到原处，与反馈无关。"}, "sentence_index": null, "correct_answer": "反馈"}, "level_3": {"options": [{"text": "反馈", "is_correct": true, "explanation": "正确。“反馈给经理”指把意见转告给经理，与“已经……了”的完成语境相符。"}, {"text": "隐瞒", "is_correct": false, "explanation": "配价：“隐瞒”不能用“给”引出对象，应说“对……隐瞒”，而且意思与传递相反。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：“收藏”是留存自用，不是交给经理，与“已经给经理了”相悖。"}, {"text": "扣下", "is_correct": false, "explanation": "语义：“扣下”是留住不给，与“已经给经理了”的完成动作相悖。"}], "explanations": {"反馈": "正确。“反馈给经理”指把意见转告给经理，与“已经……了”的完成语境相符。", "隐瞒": "配价：“隐瞒”不能用“给”引出对象，应说“对……隐瞒”，而且意思与传递相反。", "收藏": "语义：“收藏”是留存自用，不是交给经理，与“已经给经理了”相悖。", "扣下": "语义：“扣下”是留住不给，与“已经给经理了”的完成动作相悖。"}, "sentence_index": 0, "correct_answer": "反馈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书我已经反馈给朋友了。", "explanation": "这里应该用〈分享〉。反馈的宾语是想法、意见或结果，书是实物，不能用反馈。"}, {"text": "我昨天反馈了一台电脑。", "explanation": "这里应该用〈修〉。反馈的宾语是想法、意见或结果，电脑是实物，修电脑要说修。"}, {"text": "我昨天反馈了一场比赛。", "explanation": "这里应该用〈参加〉。反馈的宾语是想法或结果，比赛是活动，不能反馈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e51765ac-7a12-4cb6-bd4f-0f6d3ccc9522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23122, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反馈", "is_correct": true, "explanation": "正确。“反馈给医生”指把检查结果告诉医生，与句子的常规语境相符。"}, {"text": "销毁", "is_correct": false, "explanation": "搭配：“销毁”的对象是物件，不能与“给了医生”搭配，句子读不通。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”是抹去，不是交给医生，与“给了医生”的传递方向相反。"}, {"text": "掩盖", "is_correct": false, "explanation": "语义：“掩盖”是遮住真相，与“给了医生”的传递相反。"}], "explanations": {"反馈": "正确。“反馈给医生”指把检查结果告诉医生，与句子的常规语境相符。", "销毁": "搭配：“销毁”的对象是物件，不能与“给了医生”搭配，句子读不通。", "删除": "语义：“删除”是抹去，不是交给医生，与“给了医生”的传递方向相反。", "掩盖": "语义：“掩盖”是遮住真相，与“给了医生”的传递相反。"}, "sentence_index": 6, "correct_answer": "反馈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我周末去医院反馈生病的朋友。", "explanation": "这里应该用〈看望〉。反馈的宾语是想法或结果，不能是人，也不能表示探望。"}, {"text": "她很快就把这束花反馈给了同事。", "explanation": "这里应该用〈送〉。反馈只用于想法、意见或结果，花是实物，不能用反馈。"}, {"text": "医生很快就把药反馈给了病人。", "explanation": "这里应该用〈开〉。反馈的宾语是想法或结果，药是实物，要说开药或发药。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e51765ac-7a12-4cb6-bd4f-0f6d3ccc9522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把新的看法反馈团队了。", "corrected_sentence": "我把新的看法反馈给团队了。", "error_description": "错误：“反馈”后漏了“给”，应说“反馈给团队了”。“反馈”要用“给”引出接收的人，不能直接把接收者放在后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e51765ac-7a12-4cb6-bd4f-0f6d3ccc9522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把化验结果反馈了给医生。", "corrected_sentence": "她把化验结果反馈给了医生。", "error_description": "错误：“了”放错了位置。“反馈”后先接“给”，再接“了”，应说“反馈给了医生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e51765ac-7a12-4cb6-bd4f-0f6d3ccc9522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23124, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶化", "is_correct": true, "explanation": "恶化：指情况变得更坏，与“改善”（让情况变好）相反。这是正确答案。"}, {"text": "增加", "is_correct": false, "explanation": "增加指数量变多，与“改善”的情况变好没有反义关系。"}, {"text": "搁置", "is_correct": false, "explanation": "搁置指暂时放下不处理，与“改善”不是反义关系。"}, {"text": "保持", "is_correct": false, "explanation": "保持指维持原样，与“改善”不是反义关系。"}], "correct_answer": "恶化", "explanations": {"恶化": "恶化：指情况变得更坏，与“改善”（让情况变好）相反。这是正确答案。", "增加": "增加指数量变多，与“改善”的情况变好没有反义关系。", "搁置": "搁置指暂时放下不处理，与“改善”不是反义关系。", "保持": "保持指维持原样，与“改善”不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23124, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶化", "is_correct": true, "explanation": "恶化：指情况变得更坏，与“改善”相反。这是正确答案。"}, {"text": "维护", "is_correct": false, "explanation": "维护指保护使之不受损害，与“改善”不是反义关系。"}, {"text": "扩大", "is_correct": false, "explanation": "扩大指范围或规模变大，与“改善”不是反义关系。"}, {"text": "延长", "is_correct": false, "explanation": "延长指时间或长度增加，与“改善”不是反义关系。"}], "correct_answer": "恶化", "explanations": {"恶化": "恶化：指情况变得更坏，与“改善”相反。这是正确答案。", "维护": "维护指保护使之不受损害，与“改善”不是反义关系。", "扩大": "扩大指范围或规模变大，与“改善”不是反义关系。", "延长": "延长指时间或长度增加，与“改善”不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23124, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使原来不够好的情况、条件变得更好。", "primary_collocate": null, "pronunciation": "gǎi shàn", "ipa": "kai˨˩˦ ʂan˥˩", "syllable_count": 2, "sentences": [{"text": "政府想办法改善农村的生活条件。", "target_word": "改善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，他的睡眠改善了很多。", "target_word": "改善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多运动可以改善身体状况。", "target_word": "改善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要改善和邻居的关系。", "target_word": "改善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的空气质量正在慢慢改善。", "target_word": "改善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新路修好后，交通情况大大改善了。", "target_word": "改善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想改善员工的工作环境。", "target_word": "改善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了新方法，学习成绩有所改善。", "target_word": "改善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的收入多了，家里的生活改善了。", "target_word": "改善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过努力，两国关系终于得到了改善。", "target_word": "改善", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改善了", "label": "体标"}, {"form": "改善过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使原来不够好的情况、条件变得更好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48420b25-8f0d-4c8e-9a02-21c20436390e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23124, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改善", "is_correct": true, "explanation": "正确：改善指让不好的情况变好，符合“政府想办法……农村的生活条件”。"}, {"text": "恶化", "is_correct": false, "explanation": "语义：恶化指情况变得更坏，与“想办法”的目的相反。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：破坏指损害、毁掉，与政府想办法让生活条件变好的意思相反。"}, {"text": "节约", "is_correct": false, "explanation": "搭配：节约多用于时间、资源、钱财，不能用于生活条件。"}], "explanations": {"改善": "正确：改善指让不好的情况变好，符合“政府想办法……农村的生活条件”。", "恶化": "语义：恶化指情况变得更坏，与“想办法”的目的相反。", "破坏": "语义：破坏指损害、毁掉，与政府想办法让生活条件变好的意思相反。", "节约": "搭配：节约多用于时间、资源、钱财，不能用于生活条件。"}, "sentence_index": 0, "correct_answer": "改善"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他改善了作业里的错别字。", "explanation": "这里应该用〈改正〉。改正用于错误、错别字，改善用于让情况变好。"}, {"text": "这片荒地已经改善成了农田。", "explanation": "这里应该用〈改造〉。改善只表示让原有状况变好，不表示把东西变成另一种样子。"}, {"text": "妈妈改善了坏掉的椅子。", "explanation": "这里应该用〈修理〉。修理用于坏掉的东西，改善不用于具体物品的修复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改善", "is_correct": true, "explanation": "正确：改善指让工作环境变得更好，符合“公司想……员工的工作环境”。"}, {"text": "浪费", "is_correct": false, "explanation": "搭配：浪费多用于时间、资源、钱财，不能用于工作环境。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：拆除指拆掉有形的建筑或设施，不能用于抽象的工作环境。"}, {"text": "戏弄", "is_correct": false, "explanation": "配价：戏弄的对象一般是人，不能用在“工作环境”上。"}], "explanations": {"改善": "正确：改善指让工作环境变得更好，符合“公司想……员工的工作环境”。", "浪费": "搭配：浪费多用于时间、资源、钱财，不能用于工作环境。", "拆除": "搭配：拆除指拆掉有形的建筑或设施，不能用于抽象的工作环境。", "戏弄": "配价：戏弄的对象一般是人，不能用在“工作环境”上。"}, "sentence_index": 6, "correct_answer": "改善"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要改善那个小偷。", "explanation": "这里应该用〈改造〉。改善用于情况和条件，不用于指人本身。"}, {"text": "公司今年改善了员工的人数。", "explanation": "这里应该用〈增加〉。改善指情况或质量变好，不用于数量的增减。"}, {"text": "他的病情改善得很严重。", "explanation": "这里误把改善当成了〈恶化〉的意思：改善指情况变好，不能用来描述病情变坏或严重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他努力锻炼，身体状况改善着不少。", "corrected_sentence": "他努力锻炼，身体状况改善了不少。", "error_description": "错误：“改善着不少”，“着”表示持续状态，这里说的是已经发生的变化，应用“了”。正确：“改善了不少”，“了”表示变化已经完成，“不少”作数量补语放在“了”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次调整后，服务质量改善的很明显。", "corrected_sentence": "这次调整后，服务质量改善得很明显。", "error_description": "错误：“改善的很明显”，补语标记应为“得”而不是“的”。“得”引出程度补语，说明改善达到的程度。正确：“改善得很明显”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
