INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23126, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把药物、肥料等用到人或植物身上，如用药治病。", "primary_collocate": null, "pronunciation": "shī yòng", "ipa": "ʂʅ˥ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "医生每天给他施用两次这种针剂。", "target_word": "施用", "complexity_tier": "T3", "furigana": "yī shēng měi tiān gěi tā shī yòng liǎng cì zhè zhǒng zhēn jì。", "sentence_source": "generated"}, {"text": "这种药膏应直接施用于患处。", "target_word": "施用", "complexity_tier": "T3", "furigana": "zhè zhǒng yào gāo yīng zhí jiē shī yòng yú huàn chù。", "sentence_source": "generated"}, {"text": "儿童不宜随便施用成人的药物。", "target_word": "施用", "complexity_tier": "T3", "furigana": "ér tóng bù yí suí biàn shī yòng chéng rén de yào wù。", "sentence_source": "generated"}, {"text": "医生教奶奶怎样施用这瓶药。", "target_word": "施用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "施用这种针剂后，他的疼痛明显减轻。", "target_word": "施用", "complexity_tier": "T3", "furigana": "shī yòng zhè zhǒng zhēn jì hòu，tā de téng tòng míng xiǎn jiǎn qīng。", "sentence_source": "generated"}, {"text": "药要按说明书施用，不能多也不能少。", "target_word": "施用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生给病人施用了新药，病很快就好了。", "target_word": "施用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生在手术中施用这种麻醉药，效果很好。", "target_word": "施用", "complexity_tier": "T3", "furigana": "yī shēng zài shǒu shù zhōng shī yòng zhè zhǒng má zuì yào，xiào guǒ hěn hǎo。", "sentence_source": "generated"}, {"text": "这种针剂每次只能施用一支，不能多用。", "target_word": "施用", "complexity_tier": "T3", "furigana": "zhè zhǒng zhēn jì měi cì zhǐ néng shī yòng yì zhī，bù néng duō yòng。", "sentence_source": "generated"}, {"text": "请在医生的帮助下施用这种药。", "target_word": "施用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "施用了", "label": "体标（了）"}, {"form": "施用过", "label": "体标（过）"}], "register": "书面", "sense_fingerprint": "施用|用药治病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab623cb5-ee24-4aec-89c3-b126ca65d1ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23126, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "施用", "is_correct": true, "explanation": "施用 shī yòng：用药治病，即所听到的词。"}, {"text": "实用", "is_correct": false, "explanation": "实用 shí yòng 与 shī yòng 第一个音节的声调不同（第二声与第一声），意思是实际有用。"}, {"text": "试用", "is_correct": false, "explanation": "试用 shì yòng 与 shī yòng 第一个音节的声调不同（第四声与第一声），意思是先使用看效果。"}, {"text": "私用", "is_correct": false, "explanation": "私用 sī yòng 与 shī yòng 第一个音节的声母不同（s 与 sh），意思是为私人使用。"}], "explanations": {"施用": "施用 shī yòng：用药治病，即所听到的词。", "实用": "实用 shí yòng 与 shī yòng 第一个音节的声调不同（第二声与第一声），意思是实际有用。", "试用": "试用 shì yòng 与 shī yòng 第一个音节的声调不同（第四声与第一声），意思是先使用看效果。", "私用": "私用 sī yòng 与 shī yòng 第一个音节的声母不同（s 与 sh），意思是为私人使用。"}, "sentence_index": null, "correct_answer": "施用"}, "level_3": {"options": [{"text": "施用", "is_correct": true, "explanation": "施用：给病人用药，与句意相合。"}, {"text": "收集", "is_correct": false, "explanation": "语义：收集是把东西聚拢，不是给病人用药，与“给他……两次”不合。"}, {"text": "冲洗", "is_correct": false, "explanation": "搭配：“冲洗”用于伤口或器物，不说冲洗给病人的针剂。"}, {"text": "粉碎", "is_correct": false, "explanation": "语义：粉碎会毁掉针剂，无法给病人用药。"}], "explanations": {"施用": "施用：给病人用药，与句意相合。", "收集": "语义：收集是把东西聚拢，不是给病人用药，与“给他……两次”不合。", "冲洗": "搭配：“冲洗”用于伤口或器物，不说冲洗给病人的针剂。", "粉碎": "语义：粉碎会毁掉针剂，无法给病人用药。"}, "sentence_index": 0, "correct_answer": "施用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶每天施用两个苹果。", "explanation": "这里应该用〈吃〉。施用指把药物、肥料用到人或植物身上，苹果是食物，要说“吃”。"}, {"text": "妈妈用抹布施用桌子。", "explanation": "这里应该用〈擦〉。施用不用于清洁物体，擦桌子要说“擦”。"}, {"text": "他每天施用衣服。", "explanation": "这里应该用〈穿〉。施用不用于衣物，穿衣服要说“穿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db74969-bc3a-4f78-be8a-a16ad1d7ff90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23126, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "施用", "is_correct": true, "explanation": "施用：给病人用了新药，与“病很快就好了”相合。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：销毁药物会让病人无药可用，与“病很快就好了”矛盾。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：扔掉药物不能使病人好转，与句意相反。"}, {"text": "退回", "is_correct": false, "explanation": "语义：把新药退回去，病人没有用药，病不会很快好，与句意矛盾。"}], "explanations": {"施用": "施用：给病人用了新药，与“病很快就好了”相合。", "销毁": "语义：销毁药物会让病人无药可用，与“病很快就好了”矛盾。", "扔掉": "语义：扔掉药物不能使病人好转，与句意相反。", "退回": "语义：把新药退回去，病人没有用药，病不会很快好，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "施用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对门施用了很大的力。", "explanation": "这里应该用〈施加〉。施用指把药物、肥料用到人或植物上，力气要说“施加”。"}, {"text": "妈妈在厨房施用米饭。", "explanation": "这里应该用〈煮〉。施用不用于烹饪，做米饭要说“煮”。"}, {"text": "他每天施用房间。", "explanation": "这里应该用〈打扫〉。施用不用于清扫场所，打扫房间要说“打扫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db74969-bc3a-4f78-be8a-a16ad1d7ff90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种软膏应当直接施用伤口。", "corrected_sentence": "这种软膏应当直接施用于伤口。", "error_description": "介词缺失：“施用”后带处所时须加“于”，应说“施用于伤口”，漏掉“于”即为错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db74969-bc3a-4f78-be8a-a16ad1d7ff90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位病人以前施用了过这种针剂。", "corrected_sentence": "这位病人以前施用过这种针剂。", "error_description": "体标语序错误：“过”须紧接动词，应说“施用过”；“了过”的语序不合规范，不能说“施用了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db74969-bc3a-4f78-be8a-a16ad1d7ff90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
