INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23132, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把肥料、药物、魔法等加于某物或某人。", "primary_collocate": null, "pronunciation": "shī", "ipa": "ʂɻ̩˥", "syllable_count": 1, "sentences": [{"text": "农民给麦田施了很多肥。", "target_word": "施", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈每个月给花施一次肥。", "target_word": "施", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "巫师对王子施了魔法。", "target_word": "施", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小女孩想学施魔法，变出一只小狗。", "target_word": "施", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块地去年没施过肥，今年草长得不好。", "target_word": "施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民给果树施了药，虫子少多了。", "target_word": "施", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "魔法师向敌人施了一个强大的魔法。", "target_word": "施", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "种菜时先松土，再施一些有机肥。", "target_word": "施", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别给草坪施太多肥，草会烧坏的。", "target_word": "施", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个女巫给我施过魔法，我现在还有点怕。", "target_word": "施", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "施了", "label": "完成体（了）"}, {"form": "施过", "label": "经历体（过）"}], "register": "中性", "sense_fingerprint": "施：把肥料、药物、魔法等加于某物或某人（施肥、施药、施魔法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5767e3cf-4ef0-4302-87d2-21171c97c702') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23132, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "施", "is_correct": true, "explanation": "施（shī）：把肥料、魔法等加于某物或某人，如施肥、施魔法。"}, {"text": "十", "is_correct": false, "explanation": "十（shí）与施（shī）声调不同（第二声与第一声），意思是数字十。"}, {"text": "是", "is_correct": false, "explanation": "是（shì）与施（shī）声调不同（第四声与第一声），意思是“是非”的是。"}, {"text": "思", "is_correct": false, "explanation": "思（sī）与施（shī）声母不同（s 与 sh），意思是想。"}, {"text": "史", "is_correct": false, "explanation": "史（shǐ）与施（shī）声调不同（第三声与第一声），意思是历史。"}], "explanations": {"施": "施（shī）：把肥料、魔法等加于某物或某人，如施肥、施魔法。", "十": "十（shí）与施（shī）声调不同（第二声与第一声），意思是数字十。", "是": "是（shì）与施（shī）声调不同（第四声与第一声），意思是“是非”的是。", "思": "思（sī）与施（shī）声母不同（s 与 sh），意思是想。", "史": "史（shǐ）与施（shī）声调不同（第三声与第一声），意思是历史。"}, "sentence_index": null, "correct_answer": "施"}, "level_3": {"options": [{"text": "施", "is_correct": true, "explanation": "施：把肥料加于麦田，给麦田施肥，与语境一致。"}, {"text": "晒", "is_correct": false, "explanation": "语义：“晒”是日晒，不能用来指给麦田加肥料。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”多接柴火、煤炭，不说“烧肥”。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”是掘取，与给麦田加肥的意思不合。"}], "explanations": {"施": "施：把肥料加于麦田，给麦田施肥，与语境一致。", "晒": "语义：“晒”是日晒，不能用来指给麦田加肥料。", "烧": "搭配：“烧”多接柴火、煤炭，不说“烧肥”。", "挖": "语义：“挖”是掘取，与给麦田加肥的意思不合。"}, "sentence_index": 0, "correct_answer": "施"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民每天都要施农活，很辛苦。", "explanation": "这里应该用〈做〉。施多用于施肥、施药、施魔法等，不用于农活。"}, {"text": "妈妈给我施了一首歌。", "explanation": "这里应该用〈唱〉。施多用于肥料、药物、魔法等，唱歌要说“唱”，不能用施。"}, {"text": "他每天都施这把剑，很认真。", "explanation": "这里应该用〈使用〉。施不用于武器，剑要说“使用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '284e6d2a-0e7c-47c0-840f-71f44bcd6f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23132, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "施", "is_correct": true, "explanation": "施（shī）：把肥料、药物、魔法等加于某物或某人，如施魔法、施药。"}, {"text": "时", "is_correct": false, "explanation": "时（shí）与施（shī）声调不同（第二声与第一声），意思是时间。"}, {"text": "市", "is_correct": false, "explanation": "市（shì）与施（shī）声调不同（第四声与第一声），意思是市场。"}, {"text": "丝", "is_correct": false, "explanation": "丝（sī）与施（shī）声母不同（s 与 sh），意思是丝线。"}, {"text": "石", "is_correct": false, "explanation": "石（shí）与施（shī）声调不同（第二声与第一声），意思是石头。"}], "explanations": {"施": "施（shī）：把肥料、药物、魔法等加于某物或某人，如施魔法、施药。", "时": "时（shí）与施（shī）声调不同（第二声与第一声），意思是时间。", "市": "市（shì）与施（shī）声调不同（第四声与第一声），意思是市场。", "丝": "丝（sī）与施（shī）声母不同（s 与 sh），意思是丝线。", "石": "石（shí）与施（shī）声调不同（第二声与第一声），意思是石头。"}, "sentence_index": null, "correct_answer": "施"}, "level_3": {"options": [{"text": "施", "is_correct": true, "explanation": "施：把魔法施放于敌人，与语境一致。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”多接房屋、机器，不说“修魔法”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”是进食，与对敌人施法的意思不符。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”是言语攻击，与施放魔法的意思不合。"}], "explanations": {"施": "施：把魔法施放于敌人，与语境一致。", "修": "搭配：“修”多接房屋、机器，不说“修魔法”。", "吃": "语义：“吃”是进食，与对敌人施法的意思不符。", "骂": "语义：“骂”是言语攻击，与施放魔法的意思不合。"}, "sentence_index": 6, "correct_answer": "施"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民给花施了一次水。", "explanation": "这里应该用〈浇〉。施多用于肥料、药物、魔法，给花浇水要用“浇”。"}, {"text": "妈妈给我施了一个拥抱。", "explanation": "这里应该用〈送〉。施多用于肥料、药物、魔法等，拥抱是动作，表示给予应说“送”，不能用施。"}, {"text": "他对我施了一句话，我没听清。", "explanation": "这里应该用〈说〉。施不用于说话，应说“说了一句话”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '284e6d2a-0e7c-47c0-840f-71f44bcd6f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块地去年没施了肥。", "corrected_sentence": "这块地去年没施过肥。", "error_description": "体标错误：“没”否定过去的动作时，“施”后不能用“了”；表示没有这种经历，应说“没施过肥”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '284e6d2a-0e7c-47c0-840f-71f44bcd6f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "园丁昨天给玫瑰施着一次有机肥。", "corrected_sentence": "园丁昨天给玫瑰施了一次有机肥。", "error_description": "体标错误：“昨天”施肥是已经完成的动作，又带动量词“一次”，“施”后应用“了”，不能用表示持续的“着”。正确说法是“施了一次有机肥”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '284e6d2a-0e7c-47c0-840f-71f44bcd6f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
