INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23140, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把坏掉的东西再盖起来。", "primary_collocate": null, "pronunciation": "chóng jiàn", "ipa": "tʂʰʊŋ˧˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "地震后，人们开始重建自己的家。", "target_word": "重建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大水冲坏了这座老桥，政府决定重建。", "target_word": "重建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校着火后，大家一起重建了教室。", "target_word": "重建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束了，他们要重建这座城市。", "target_word": "重建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古塔在去年重建好了。", "target_word": "重建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们打算在旧房子的地方重建一座新楼。", "target_word": "重建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水过后，村民忙着重建冲坏的房子。", "target_word": "重建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在重建倒下的围墙。", "target_word": "重建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的仓库烧了，老板决定重建。", "target_word": "重建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重建这座桥要花一年时间。", "target_word": "重建", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重建了", "label": "体标"}, {"form": "重建过", "label": "体标"}, {"form": "灾后重建", "label": "复合"}], "register": "中性", "sense_fingerprint": "房屋、桥梁等被毁坏后重新建造", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48420b25-8f0d-4c8e-9a02-21c20436390e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23140, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重建", "is_correct": true, "explanation": "正确：“重建”指把毁坏的房屋重新建起来，与“地震后”的语境相符。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”用于植物或田地，不能用于房屋。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”用于动物，不能用于房屋。"}, {"text": "复活", "is_correct": false, "explanation": "语义：“复活”指生命重新恢复，房屋不会复活，句中不合。"}], "explanations": {"重建": "正确：“重建”指把毁坏的房屋重新建起来，与“地震后”的语境相符。", "浇灌": "搭配：“浇灌”用于植物或田地，不能用于房屋。", "饲养": "搭配：“饲养”用于动物，不能用于房屋。", "复活": "语义：“复活”指生命重新恢复，房屋不会复活，句中不合。"}, "sentence_index": 0, "correct_answer": "重建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人重建了坏掉的门。", "explanation": "这里应该用〈修理〉。重建指毁坏的大型建筑再盖起来，门坏了只需修理。"}, {"text": "他们重建了这张刚买的桌子。", "explanation": "这里应该用〈组装〉。重建指把毁坏的大型建筑再盖起来，刚买的桌子没有毁坏，只需组装。"}, {"text": "他们重建了旧沙发。", "explanation": "这里应该用〈翻新〉。重建指毁坏后再建，旧沙发只需翻新，不是重建。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重建", "is_correct": true, "explanation": "正确：“重建”指把冲坏的房子重新建起来，与“洪水过后”的语境相符。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”用于植物，不能用于“冲坏的房子”。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”用于枝叶、头发等，不能用于房子。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”针对语言或文字，与房屋无关，句中不合。"}], "explanations": {"重建": "正确：“重建”指把冲坏的房子重新建起来，与“洪水过后”的语境相符。", "种植": "搭配：“种植”用于植物，不能用于“冲坏的房子”。", "修剪": "搭配：“修剪”用于枝叶、头发等，不能用于房子。", "翻译": "语义：“翻译”针对语言或文字，与房屋无关，句中不合。"}, "sentence_index": 6, "correct_answer": "重建"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们重建了昨天的会议。", "explanation": "这里应该用〈重开〉。重建指把毁坏的东西再盖起来，会议不是建筑，应说重开。"}, {"text": "重建这条裂缝要花一天时间。", "explanation": "这里应该用〈修补〉。重建指把毁坏的建筑重新盖起，裂缝只需修补。"}, {"text": "我的自行车坏了，我要重建它。", "explanation": "这里应该用〈修理〉。重建指把毁坏的房屋、桥梁等重新盖起来，自行车坏了只需修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村民们把冲坏的房子重建了好。", "corrected_sentence": "村民们把冲坏的房子重建好了。", "error_description": "错误形式：“重建了好”。正确形式：“重建好了”。结果补语“好”应紧跟动词“重建”，“了”放在补语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村民们决定重建了那座被洪水冲毁的桥。", "corrected_sentence": "村民们决定重建那座被洪水冲毁的桥。", "error_description": "错误形式：“决定重建了”。正确形式：“决定重建”。“决定”后的动作尚未发生，不能在动词后加“了”表示完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
