INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23144, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做实验时，用来比较的那一组。", "primary_collocate": null, "pronunciation": "duì zhào zǔ", "ipa": "tweɪ˥˩ ʈʂɑʊ˥˩ tsu˨˩˦", "syllable_count": 3, "sentences": [{"text": "小明的实验有两组，其中一组是对照组。", "target_word": "对照组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，对照组不用加肥料。", "target_word": "对照组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们给对照组的花只浇清水。", "target_word": "对照组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对照组是用来比较的那一组。", "target_word": "对照组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验组和对照组的结果不一样。", "target_word": "对照组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们为豆子实验准备了对照组。", "target_word": "对照组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对照组的豆子长得比较慢。", "target_word": "对照组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要先分好实验组和对照组，再开始做。", "target_word": "对照组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对照组的水杯里没有放盐。", "target_word": "对照组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们记下对照组的变化。", "target_word": "对照组", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "對照組", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对照组：做实验时用来和实验组比较的那一组", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5767e3cf-4ef0-4302-87d2-21171c97c702') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23144, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对照组", "is_correct": true, "explanation": "正确：对照组是做实验时用来比较的一组，符合“两组”中“其中一组”的语境。"}, {"text": "天平", "is_correct": false, "explanation": "语义：天平是测量仪器，不是实验中的分组，句意不通。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不是实验中的一组，与句子语境不符。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：“其中一组”指可以分组的实验对象，“老师”不能作为实验的分组。"}], "explanations": {"对照组": "正确：对照组是做实验时用来比较的一组，符合“两组”中“其中一组”的语境。", "天平": "语义：天平是测量仪器，不是实验中的分组，句意不通。", "作业": "语义：作业是学习任务，不是实验中的一组，与句子语境不符。", "老师": "搭配：“其中一组”指可以分组的实验对象，“老师”不能作为实验的分组。"}, "sentence_index": 0, "correct_answer": "对照组"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "对照组是接受新药处理的那一组。", "explanation": "这里应该用〈实验组〉。接受新药处理的是实验组，对照组只作为比较的基准。"}, {"text": "我们只改变了一个对照组，其他条件不变。", "explanation": "这里应该用〈变量〉。被改变的是变量，对照组是用来比较的那一组，不能被改变。"}, {"text": "老师让我们把溶液倒进对照组里。", "explanation": "这里应该用〈试管〉。对照组是一组实验对象，不是盛放溶液的容器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '284e6d2a-0e7c-47c0-840f-71f44bcd6f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对照组", "is_correct": true, "explanation": "正确：对照组是比较基准，它的豆子长得慢是该组的实验结果。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“长得比较慢”的主语应是生物，“天气”不能“长”。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不是实验中的一组豆子，句意不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不会生长，不能作为豆子的所属对象，句意不通。"}], "explanations": {"对照组": "正确：对照组是比较基准，它的豆子长得慢是该组的实验结果。", "天气": "搭配：“长得比较慢”的主语应是生物，“天气”不能“长”。", "书包": "语义：书包是物品，不是实验中的一组豆子，句意不通。", "手机": "语义：手机不会生长，不能作为豆子的所属对象，句意不通。"}, "sentence_index": 6, "correct_answer": "对照组"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "实验结束后，我们写出了对照组。", "explanation": "这里应该用〈结论〉。对照组是实验中的一组对象，不是实验得出的结果。"}, {"text": "老师让我们用对照组量取五十毫升水。", "explanation": "这里应该用〈量杯〉。对照组是一组对象，不能用来测量。"}, {"text": "老师让我们把对照组贴在墙上。", "explanation": "这里应该用〈表格〉。对照组是实验对象，不能贴在墙上，贴在墙上的是表格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '284e6d2a-0e7c-47c0-840f-71f44bcd6f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次实验一共有两只对照组。", "corrected_sentence": "这次实验一共有两个对照组。", "error_description": "量词错误：“对照组”应用量词〈个〉（或〈组〉）计数，“只”用于动物或单个小物件，应改为“两个对照组”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '284e6d2a-0e7c-47c0-840f-71f44bcd6f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们为豆子实验准备了一条对照组。", "corrected_sentence": "我们为豆子实验准备了一个对照组。", "error_description": "量词错误：“对照组”应用量词〈个〉计数，“条”用于细长的东西，应改为“一个对照组”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '284e6d2a-0e7c-47c0-840f-71f44bcd6f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23146, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db74969-bc3a-4f78-be8a-a16ad1d7ff90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
