INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23148, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容空间又深又远，如深谷、海底。", "primary_collocate": null, "pronunciation": "shēn yuǎn", "ipa": "ʂən˥ ɥɛn˨˩", "syllable_count": 2, "sentences": [{"text": "山谷深远，望不到尽头。", "target_word": "深远", "complexity_tier": "T3", "furigana": "shēn yuǎn", "sentence_source": "generated"}, {"text": "他站在深远的峡谷边，心里有点害怕。", "target_word": "深远", "complexity_tier": "T3", "furigana": "shēn yuǎn", "sentence_source": "generated"}, {"text": "山洞深远，里面黑得什么都看不见。", "target_word": "深远", "complexity_tier": "T3", "furigana": "shēn yuǎn", "sentence_source": "generated"}, {"text": "夜色里的树林深远幽暗，没人敢进去。", "target_word": "深远", "complexity_tier": "T3", "furigana": "shēn yuǎn", "sentence_source": "generated"}, {"text": "这条隧道深远曲折，走起来很费力。", "target_word": "深远", "complexity_tier": "T3", "furigana": "shēn yuǎn", "sentence_source": "generated"}, {"text": "沿着这条深远的河谷，我们一直走到天黑。", "target_word": "深远", "complexity_tier": "T3", "furigana": "shēn yuǎn", "sentence_source": "generated"}, {"text": "海底深远，阳光很难照到那里。", "target_word": "深远", "complexity_tier": "T3", "furigana": "shēn yuǎn", "sentence_source": "generated"}, {"text": "洞穴深远幽黑，手电筒的光照不到底。", "target_word": "深远", "complexity_tier": "T3", "furigana": "shēn yuǎn", "sentence_source": "generated"}, {"text": "峡谷深远，喊一声，回声很久才消失。", "target_word": "深远", "complexity_tier": "T3", "furigana": "shēn yuǎn", "sentence_source": "generated"}, {"text": "这座深山深远幽静，我们走了一整天也没见到人。", "target_word": "深远", "complexity_tier": "T3", "furigana": "shēn yuǎn", "sentence_source": "generated"}], "morphological_forms": [{"form": "深遠", "label": "繁体"}], "register": "书面", "sense_fingerprint": "空间又深又远（山谷、峡谷、海底等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce010c66-d877-4df7-8147-8f6d54c7cf13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23148, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深远", "is_correct": true, "explanation": "正确：「深远」指山谷又深又远，与「望不到尽头」相合。"}, {"text": "近", "is_correct": false, "explanation": "语义：「近」说距离短，与「望不到尽头」矛盾。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：「矮」一般用于人或物的高度，不说山谷矮。"}, {"text": "浅", "is_correct": false, "explanation": "语义：「浅」说深度不够，与山谷的特点相反。"}], "explanations": {"深远": "正确：「深远」指山谷又深又远，与「望不到尽头」相合。", "近": "语义：「近」说距离短，与「望不到尽头」矛盾。", "矮": "搭配：「矮」一般用于人或物的高度，不说山谷矮。", "浅": "语义：「浅」说深度不够，与山谷的特点相反。"}, "sentence_index": 0, "correct_answer": "深远"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服很深远，穿着很暖和。", "explanation": "这里应该用〈厚〉。衣服的厚薄要说「厚」，「深远」只形容空间又深又远。"}, {"text": "他说话的声音很深远，大家都听清楚了。", "explanation": "这里应该用〈洪亮〉。声音大而清楚要说「洪亮」，「深远」只形容空间又深又远。"}, {"text": "这碗汤的味道很深远，喝一口就停不下来。", "explanation": "这里应该用〈浓郁〉。「深远」形容空间的深和远或影响，味道的浓厚要用「浓郁」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23148, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深远", "is_correct": true, "explanation": "正确：「深远」形容海底又深又远，与「阳光很难照到那里」相合。"}, {"text": "高", "is_correct": false, "explanation": "搭配：「高」用于位置高低，不说「海底高」，也与海底的位置特点不合。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：「明亮」说光线充足，与「阳光很难照到那里」矛盾。"}, {"text": "温柔", "is_correct": false, "explanation": "搭配：「温柔」形容人的性情，不能用来形容海底。"}], "explanations": {"深远": "正确：「深远」形容海底又深又远，与「阳光很难照到那里」相合。", "高": "搭配：「高」用于位置高低，不说「海底高」，也与海底的位置特点不合。", "明亮": "语义：「明亮」说光线充足，与「阳光很难照到那里」矛盾。", "温柔": "搭配：「温柔」形容人的性情，不能用来形容海底。"}, "sentence_index": 6, "correct_answer": "深远"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布的颜色很深远，看起来很舒服。", "explanation": "这里应该用〈浓〉。颜色的浓淡要说「浓」，「深远」只形容空间或影响，不形容颜色。"}, {"text": "我们等了一个深远的下午。", "explanation": "这里应该用〈漫长〉。「深远」只用于空间，形容时间久要用「漫长」。"}, {"text": "老师讲得很深远，大家都听懂了。", "explanation": "这里应该用〈深入〉。「深远」形容空间或影响，讲解问题的透彻程度要用「深入」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23148, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河比那条河很深远。", "corrected_sentence": "这条河比那条河更深远。", "error_description": "「比」字句中不能再用「很」，应改为「更」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23148, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条河谷深深远，水流很急。", "corrected_sentence": "那条河谷深远，水流很急。", "error_description": "错误形式：「深深远」。正确形式：「深远」。「深」多加了一次，「深远」是双音形容词，不能重叠成「深深远」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
