INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23150, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生态学是研究动物、植物和它们住的地方怎么一起生活的学问。", "primary_collocate": null, "pronunciation": "shēng tài xué", "ipa": "ʂɤŋ˥˥ tʰaɪ˥˩ ɕɥɛ˧˥", "syllable_count": 3, "sentences": [{"text": "生态学是研究动物和植物怎么生活的学问。", "target_word": "生态学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了生态学，我知道鱼不能离开水。", "target_word": "生态学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生态学课上，老师给我们看了一片森林。", "target_word": "生态学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生态学告诉我们，小鸟也需要树。", "target_word": "生态学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢生态学，因为我爱小动物。", "target_word": "生态学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子长大后想学生态学。", "target_word": "生态学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生态学可以说明草地上的虫子为什么重要。", "target_word": "生态学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生态学的书里有很多动物的照片。", "target_word": "生态学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用生态学的方法，讲了池塘里的小动物。", "target_word": "生态学", "complexity_tier": "T3", "furigana": "lǎo shī yòng shēng tài xué de fāng fǎ, jiǎng le chí táng lǐ de xiǎo dòng wù.", "sentence_source": "generated"}, {"text": "生态学让我明白，大家都要保护自然。", "target_word": "生态学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "行为生态学", "label": "复合"}, {"form": "生态学家", "label": "复合"}], "register": "中性", "sense_fingerprint": "生态学|研究动植物和居住环境如何共同生活的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77bd49ee-81b2-46c0-a146-5020ea436bdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23150, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生态学", "is_correct": true, "explanation": "正确：「生态学」是研究生物与环境关系的学科，可以作「是……的学问」的主语。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学研究数量和图形，不研究动物和植物怎么生活。"}, {"text": "历史学", "is_correct": false, "explanation": "语义：历史学研究过去的人类社会，不研究动植物的生活习性。"}, {"text": "动物园", "is_correct": false, "explanation": "搭配：「动物园」是场所名词，不能用「是……的学问」来定义。"}], "explanations": {"生态学": "正确：「生态学」是研究生物与环境关系的学科，可以作「是……的学问」的主语。", "数学": "语义：数学研究数量和图形，不研究动物和植物怎么生活。", "历史学": "语义：历史学研究过去的人类社会，不研究动植物的生活习性。", "动物园": "搭配：「动物园」是场所名词，不能用「是……的学问」来定义。"}, "sentence_index": 0, "correct_answer": "生态学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片湖的生态学很好，鱼很多。", "explanation": "这里应该用〈生态〉。「生态」指自然环境的状况，可以说「生态好」；「生态学」是学科名，不能用来形容湖的状况。"}, {"text": "我们要保护这片森林的生态学。", "explanation": "这里应该用〈生态〉。要保护的是森林的自然环境状况，即「生态」；「生态学」是一门学问，不能被保护。"}, {"text": "生态学在森林里互相帮助。", "explanation": "这里应该用〈生物〉。「生物」是有生命的动植物，才能互相帮助；「生态学」是一门学问，不能做这种动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23150, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生态学", "is_correct": true, "explanation": "正确：「生态学」研究生物与环境的关系，可以用来说明生物为什么重要。"}, {"text": "天文学", "is_correct": false, "explanation": "语义：天文学研究星星和宇宙，不研究草地上的虫子。"}, {"text": "机场", "is_correct": false, "explanation": "搭配：「说明……为什么重要」需要理论或研究类主语，「机场」不能作这类主语。"}, {"text": "运动会", "is_correct": false, "explanation": "语义：运动会是比赛活动，不能用来说明虫子为什么重要。"}], "explanations": {"生态学": "正确：「生态学」研究生物与环境的关系，可以用来说明生物为什么重要。", "天文学": "语义：天文学研究星星和宇宙，不研究草地上的虫子。", "机场": "搭配：「说明……为什么重要」需要理论或研究类主语，「机场」不能作这类主语。", "运动会": "语义：运动会是比赛活动，不能用来说明虫子为什么重要。"}, "sentence_index": 6, "correct_answer": "生态学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去生态学玩了一天。", "explanation": "这里应该用〈生态园〉。生态园是可以去游玩的地方；「生态学」是学科名，不是场所，不能去玩。"}, {"text": "这条河的生态学被破坏了。", "explanation": "这里应该用〈生态〉。被破坏的是河的自然环境状况，即「生态」；「生态学」是学科名，不会被破坏。"}, {"text": "生态学在树上唱歌。", "explanation": "这里应该用〈小鸟〉。唱歌是有生命的动物做的动作；「生态学」是学问，不能唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在大学选修了一片生态学。", "corrected_sentence": "我在大学选修了一门生态学。", "error_description": "错误：「一片生态学」。正确：「一门生态学」。「门」用于学科和课程，「片」用于森林、草地等大片地方，不能用于学科。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的父亲教了一张生态学。", "corrected_sentence": "他的父亲教了一门生态学。", "error_description": "错误：「一张生态学」。正确：「一门生态学」。「张」用于纸、桌子等扁平的东西，学科应该用「门」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
