INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23152, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "里面含有。", "primary_collocate": null, "pronunciation": "yùn hán", "ipa": "yn˥˩ xan˧˥", "syllable_count": 2, "sentences": [{"text": "这片土地下蕴含着丰富的石油。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大海里蕴含着很多我们不知道的宝藏。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个简单的故事蕴含着深刻的道理。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小小的种子里蕴含着生命的力量。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子的墙里蕴含着一家人的回忆。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的歌声蕴含着说不出的悲伤。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的每一页都蕴含着作者的心血。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "深山里蕴含着大量的水力资源。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看似普通的石头却蕴含着宝贵的矿物。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地蕴含的资源，足够全村人用很多年。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蕴含着", "label": "体标"}, {"form": "蕴含了", "label": "体标"}], "register": "书面", "sense_fingerprint": "蕴含:里面含有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3e4321f-de6e-46a4-8743-02c784fb0964') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生长", "is_correct": false, "explanation": "搭配：“生长”指植物等的发育，不能用于石油。"}, {"text": "蕴含", "is_correct": true, "explanation": "蕴含指事物中含有，与“土地下的石油”搭配，填入后语义通顺。"}, {"text": "漂浮", "is_correct": false, "explanation": "语义：“漂浮”指浮在水面或空中，与“土地下”的位置相矛盾。"}, {"text": "堆放", "is_correct": false, "explanation": "语义：“堆放”指把东西摞在一起，与“土地下”的地下空间不符。"}], "explanations": {"生长": "搭配：“生长”指植物等的发育，不能用于石油。", "蕴含": "蕴含指事物中含有，与“土地下的石油”搭配，填入后语义通顺。", "漂浮": "语义：“漂浮”指浮在水面或空中，与“土地下”的位置相矛盾。", "堆放": "语义：“堆放”指把东西摞在一起，与“土地下”的地下空间不符。"}, "sentence_index": 0, "correct_answer": "蕴含"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那条河里蕴含着一艘船。", "explanation": "这里应该用〈行驶〉。蕴含指事物内部隐含的内容，不用于说具体的船只在河上航行。"}, {"text": "屋子里蕴含着很多家具。", "explanation": "这里应该用〈摆〉。蕴含不用于说具体的家具陈设在某处。"}, {"text": "这棵树上蕴含着很多苹果。", "explanation": "这里应该用〈结〉。蕴含不用于说果实挂在树上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "兑换", "is_correct": false, "explanation": "搭配：“兑换”的对象多是货币、积分等，不能接“心血”，句意讲不通。"}, {"text": "蕴含", "is_correct": true, "explanation": "蕴含指事物中隐含的内容，与“作者的心血”搭配，填入后语义通顺。"}, {"text": "占据", "is_correct": false, "explanation": "搭配：“占据”的宾语多是空间或位置，不能接“心血”。"}, {"text": "嫌弃", "is_correct": false, "explanation": "配价：“嫌弃”的宾语多是人或事，不能与“心血”搭配。"}], "explanations": {"兑换": "搭配：“兑换”的对象多是货币、积分等，不能接“心血”，句意讲不通。", "蕴含": "蕴含指事物中隐含的内容，与“作者的心血”搭配，填入后语义通顺。", "占据": "搭配：“占据”的宾语多是空间或位置，不能接“心血”。", "嫌弃": "配价：“嫌弃”的宾语多是人或事，不能与“心血”搭配。"}, "sentence_index": 6, "correct_answer": "蕴含"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里蕴含了一场比赛。", "explanation": "这里应该用〈举行〉。蕴含指事物中隐含的内容，不能用来说比赛这类活动在此进行。"}, {"text": "这个小组蕴含着很多成员。", "explanation": "这里应该用〈有〉。蕴含的主语是事物，不能说某个群体内部隐含着具体的人。"}, {"text": "去年这个村蕴含了一场洪水。", "explanation": "这里应该用〈遭受〉。蕴含指事物内部隐含的内容，不能用来说外来的灾害降临。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座山里蕴含了着丰富的矿藏。", "corrected_sentence": "这座山里蕴含着丰富的矿藏。", "error_description": "错误：“蕴含”后同时用了“了”和“着”，体标重复。正确应只用“着”表示持续的状态：“这座山里蕴含着丰富的矿藏”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片森林深处很蕴含着许多秘密。", "corrected_sentence": "这片森林深处蕴含着许多秘密。", "error_description": "错误：“蕴含”前多加了副词“很”。“蕴含”不能受“很”修饰；正确为“这片森林深处蕴含着许多秘密”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
