INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23154, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一件事做了之后，在别的地方或别的人身上产生的结果。", "primary_collocate": null, "pronunciation": "xiào yìng", "ipa": "ɕjɑʊ˥˩ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他的好心帮助，在同学们身上产生了很好的效应。", "target_word": "效应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师一夸，全班都努力，这个效应真好。", "target_word": "效应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都买这个，就会有跟风的效应。", "target_word": "效应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件小事的效应，比我们想的大得多。", "target_word": "效应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天早起，对全家人产生了很好的效应。", "target_word": "效应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新地铁站开通，对附近的店产生了效应。", "target_word": "效应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一笑，大家都笑了，这就是笑的效应。", "target_word": "效应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你做的每件事，都会有一些效应。", "target_word": "效应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，要想想这个办法的效应。", "target_word": "效应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王的话在朋友中间产生了很大的效应。", "target_word": "效应", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种效应", "label": "量词"}], "register": "通用", "sense_fingerprint": "一件事做了之后，在别处或别人身上产生的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98d740-f54a-4403-9fa2-3db6e5ff3669') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23154, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "效应", "is_correct": true, "explanation": "效应指一件事做了之后，在别处或别人身上产生的结果，是本题的目标词。"}, {"text": "笑意", "is_correct": false, "explanation": "xiào yìng 与 xiào yì 的区别在于韵尾（有没有 -ng），笑意指笑的意思或笑容。"}, {"text": "校印", "is_correct": false, "explanation": "yìng 与 yìn 的区别在于韵尾（-ng 与 -n），校印指学校使用的印章。"}, {"text": "效益", "is_correct": false, "explanation": "yìng 与 yì 的区别在于韵尾（有没有 -ng），效益指经济上的收获。"}], "explanations": {"效应": "效应指一件事做了之后，在别处或别人身上产生的结果，是本题的目标词。", "笑意": "xiào yìng 与 xiào yì 的区别在于韵尾（有没有 -ng），笑意指笑的意思或笑容。", "校印": "yìng 与 yìn 的区别在于韵尾（-ng 与 -n），校印指学校使用的印章。", "效益": "yìng 与 yì 的区别在于韵尾（有没有 -ng），效益指经济上的收获。"}, "sentence_index": null, "correct_answer": "效应"}, "level_3": {"options": [{"text": "效应", "is_correct": true, "explanation": "“很好的效应”指好心帮助在同学身上产生的良好结果，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能与“很好的”组合来描述帮助产生的结果，说“很好的颜色”不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”指人或事物存在的时长，不能用来形容帮助产生的结果。"}, {"text": "罪过", "is_correct": false, "explanation": "语义：“罪过”含有错误、负面的意味，与“好心帮助”和“很好的”相矛盾。"}], "explanations": {"效应": "“很好的效应”指好心帮助在同学身上产生的良好结果，与句意相符。", "颜色": "搭配：“颜色”不能与“很好的”组合来描述帮助产生的结果，说“很好的颜色”不通。", "年龄": "搭配：“年龄”指人或事物存在的时长，不能用来形容帮助产生的结果。", "罪过": "语义：“罪过”含有错误、负面的意味，与“好心帮助”和“很好的”相矛盾。"}, "sentence_index": 0, "correct_answer": "效应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张优惠券仍然具有效应，可以在店里使用。", "explanation": "这里应该用〈效力〉。“具有……效力”指凭证或规定仍然有作用，效应不能这样用。"}, {"text": "这件衣服的效应很鲜艳，我每天都愿意穿。", "explanation": "这里应该用〈颜色〉。效应指一件事对别人或别处产生的结果，不能用来形容颜色，应说“颜色很鲜艳”。"}, {"text": "这盏灯的效应很亮，每个角落都看得清。", "explanation": "这里应该用〈亮度〉。效应指一件事产生的结果，不指灯的亮暗，说灯亮要用“亮度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23154, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "效应", "is_correct": true, "explanation": "“笑的效应”指大家笑起来这一结果，与句中“大家都笑了”相符。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“重量”描述物体的轻重，不能用来指“笑”带来的结果。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”指商品的价值标准，与“笑”的结果不相关。"}, {"text": "哭声", "is_correct": false, "explanation": "语义：“哭声”与“大家都笑了”的情景相矛盾，不能作为“笑”的结果。"}], "explanations": {"效应": "“笑的效应”指大家笑起来这一结果，与句中“大家都笑了”相符。", "重量": "搭配：“重量”描述物体的轻重，不能用来指“笑”带来的结果。", "价格": "搭配：“价格”指商品的价值标准，与“笑”的结果不相关。", "哭声": "语义：“哭声”与“大家都笑了”的情景相矛盾，不能作为“笑”的结果。"}, "sentence_index": 6, "correct_answer": "效应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套新软件的效应很高，打开文件只要两秒。", "explanation": "这里应该用〈效能〉。效能指工具或设备发挥作用的能力，说软件运行快要用“效能”；效应指事情产生的结果，不指性能。"}, {"text": "这次培训的效应很丰富，大家都学会了新技能。", "explanation": "这里应该用〈内容〉。效应指一件事对别处或别人产生的结果，不能用来形容内容多少，应说“内容很丰富”。"}, {"text": "这支笔的效应很粗，写出来的字很大。", "explanation": "这里应该用〈笔尖〉。效应指一件事产生的结果，不指笔的形状，应说“笔尖很粗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次讲座在大家中间产生了一条积极的效应。", "corrected_sentence": "这次讲座在大家中间产生了一种积极的效应。", "error_description": "错误形式是“一条效应”，正确形式是“一种效应”。“条”用于细长的东西，效应要用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种新方法地效应非常好，大家都愿意尝试。", "corrected_sentence": "这种新方法的效应非常好，大家都愿意尝试。", "error_description": "错误形式是“新方法地效应”，正确形式是“新方法的效应”。“地”用于修饰动词，修饰名词“效应”要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
