INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23157, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事情出现了，或者出现了新情况。", "primary_collocate": null, "pronunciation": "fā shēng", "ipa": "fa˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "学校里发生了一件有趣的事。", "target_word": "发生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没想到会发生这样的事。", "target_word": "发生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们之间发生了一点儿误会。", "target_word": "发生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我，到底发生了什么。", "target_word": "发生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一切都发生得太快了。", "target_word": "发生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天发生的事，我已经忘了。", "target_word": "发生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中发生了意外，大家都很吃惊。", "target_word": "发生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的事在生活中常常发生。", "target_word": "发生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里发生了大事，他马上回去了。", "target_word": "发生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天晚上发生过什么，没有人知道。", "target_word": "发生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发生了", "label": "体标"}, {"form": "发生过", "label": "体标"}], "register": "中性", "sense_fingerprint": "事情出现了或出现新情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faaf0adf-bcc7-4fc0-9a0d-0cbdbb6e51dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23157, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发生", "is_correct": true, "explanation": "“发生”指事情出现，与“一件有趣的事”搭配，句意通顺。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”指去看场所或展览，“学校里”不能参观一件事。"}, {"text": "拜访", "is_correct": false, "explanation": "语义：“拜访”的对象是人，“一件有趣的事”不能被拜访。"}, {"text": "出差", "is_correct": false, "explanation": "配价：“出差”的主体是人，学校不能出差。"}], "explanations": {"发生": "“发生”指事情出现，与“一件有趣的事”搭配，句意通顺。", "参观": "语义：“参观”指去看场所或展览，“学校里”不能参观一件事。", "拜访": "语义：“拜访”的对象是人，“一件有趣的事”不能被拜访。", "出差": "配价：“出差”的主体是人，学校不能出差。"}, "sentence_index": 0, "correct_answer": "发生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他发生了一封信。", "explanation": "这里应该用〈写〉。发生指事情出现，不能指人动笔写出东西。"}, {"text": "她发生了一首歌。", "explanation": "这里应该用〈唱〉。发生不能指人演唱歌曲，唱歌要用唱。"}, {"text": "他发生了比赛。", "explanation": "这里应该用〈赢得〉。发生不能指人取胜，赢得比赛要用赢得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9db8d3-8690-40c9-852d-62d2b3d3f523') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23157, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发生", "is_correct": true, "explanation": "“发生”指事情出现，与“意外”搭配，句意通顺。"}, {"text": "举行", "is_correct": false, "explanation": "搭配：“举行”用于活动、仪式，不能说“举行了意外”。"}, {"text": "进行", "is_correct": false, "explanation": "搭配：“进行”后接行动或活动，“意外”不能被进行。"}, {"text": "出席", "is_correct": false, "explanation": "配价：“出席”的主体是人，“比赛中”不能出席一件意外。"}], "explanations": {"发生": "“发生”指事情出现，与“意外”搭配，句意通顺。", "举行": "搭配：“举行”用于活动、仪式，不能说“举行了意外”。", "进行": "搭配：“进行”后接行动或活动，“意外”不能被进行。", "出席": "配价：“出席”的主体是人，“比赛中”不能出席一件意外。"}, "sentence_index": 6, "correct_answer": "发生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人发生了机器。", "explanation": "这里应该用〈修理〉。发生不能指人对机器进行维修，修理机器要用修理。"}, {"text": "她发生了一份礼物。", "explanation": "这里应该用〈收到〉。发生不能指人接受礼物，收到礼物要用收到。"}, {"text": "他发生了作业。", "explanation": "这里应该用〈完成〉。发生不能指人做完作业，完成作业要用完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9db8d3-8690-40c9-852d-62d2b3d3f523') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23157, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次事故被发生在夜里。", "corrected_sentence": "这次事故发生在夜里。", "error_description": "“发生”是不及物动词，不能用于“被”字句。应说“这次事故发生在夜里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9db8d3-8690-40c9-852d-62d2b3d3f523') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23157, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这样的事常常发生在了周末。", "corrected_sentence": "这样的事常常发生在周末。", "error_description": "“常常”表示经常性，与表示完成的“了”不能同用，应去掉“了”，说“常常发生在周末”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9db8d3-8690-40c9-852d-62d2b3d3f523') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
