INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23160, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "沃土是能让植物长得好的土。", "primary_collocate": null, "pronunciation": "wò tǔ", "ipa": "wo˥˩ tʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "种菜要选沃土，菜才会长得又大又绿。", "target_word": "沃土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盆花长得好，因为我用的是沃土。", "target_word": "沃土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沃土里有很多养分，草也长得高。", "target_word": "沃土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在院子里换上沃土，准备种玫瑰。", "target_word": "沃土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙地上长不好树，沃土上就不一样。", "target_word": "沃土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小山下面的沃土，一年能收两次粮食。", "target_word": "沃土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些沃土是农民多年用心养出来的。", "target_word": "沃土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在花店买了一袋沃土。", "target_word": "沃土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水让河岸的沃土更加松软。", "target_word": "沃土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在学校的沃土里种了豆子。", "target_word": "沃土", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片沃土", "label": "量词"}], "register": "书面", "sense_fingerprint": "能让植物长得好的土", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faaf0adf-bcc7-4fc0-9a0d-0cbdbb6e51dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23160, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沃土", "is_correct": true, "explanation": "正确：沃土能为蔬菜提供养分，符合“菜才会长得又大又绿”的语境。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：沙子缺少养分，选它不能让菜长得又大又绿。"}, {"text": "碎石", "is_correct": false, "explanation": "搭配：“种菜”需要能保水保肥的土壤，碎石不能用来种菜。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不能让蔬菜生长，与“长得又大又绿”的结果相矛盾。"}], "explanations": {"沃土": "正确：沃土能为蔬菜提供养分，符合“菜才会长得又大又绿”的语境。", "沙子": "语义：沙子缺少养分，选它不能让菜长得又大又绿。", "碎石": "搭配：“种菜”需要能保水保肥的土壤，碎石不能用来种菜。", "垃圾": "语义：垃圾不能让蔬菜生长，与“长得又大又绿”的结果相矛盾。"}, "sentence_index": 0, "correct_answer": "沃土"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂用沃土做玻璃。", "explanation": "这里应该用〈沙子〉。做玻璃的原料是沙子；沃土是能让植物长好的土，不能用来做玻璃。"}, {"text": "他每天用沃土洗手。", "explanation": "这里应该用〈肥皂〉。洗手要用肥皂，沃土是能让植物长好的土，不能用来洗手。"}, {"text": "他每天给花浇沃土。", "explanation": "这里应该用〈水〉。浇花要用水，沃土是土，不能用来浇花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9db8d3-8690-40c9-852d-62d2b3d3f523') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沃土", "is_correct": true, "explanation": "正确：沃土是农民长期施肥、耕作养出来的，与“多年用心养出来”相符。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：土地可以靠农民多年耕作、施肥“养”得肥沃，钢铁是工厂炼出来的，不能靠农民养出来。"}, {"text": "塑料", "is_correct": false, "explanation": "语义：塑料是工业合成材料，不可能靠农民养出来。"}, {"text": "废纸", "is_correct": false, "explanation": "语义：废纸是废弃的纸，不能被“养出来”，与句意冲突。"}], "explanations": {"沃土": "正确：沃土是农民长期施肥、耕作养出来的，与“多年用心养出来”相符。", "钢铁": "语义：土地可以靠农民多年耕作、施肥“养”得肥沃，钢铁是工厂炼出来的，不能靠农民养出来。", "塑料": "语义：塑料是工业合成材料，不可能靠农民养出来。", "废纸": "语义：废纸是废弃的纸，不能被“养出来”，与句意冲突。"}, "sentence_index": 6, "correct_answer": "沃土"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民在地里种了沃土。", "explanation": "这里应该用〈玉米〉。种下去的是植物，沃土是能让植物生长的土，不能被种下。"}, {"text": "我每天吃一个沃土当早餐。", "explanation": "这里应该用〈苹果〉。沃土不能食用，早餐应吃苹果等食物。"}, {"text": "老师让我们每人喝一杯沃土。", "explanation": "这里应该用〈牛奶〉。沃土不能饮用，应该喝牛奶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9db8d3-8690-40c9-852d-62d2b3d3f523') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "换上一颗沃土以后，番茄苗一下子长高了。", "corrected_sentence": "换上一袋沃土以后，番茄苗一下子长高了。", "error_description": "量词“颗”用于颗粒状的小东西，“沃土”是成袋装的土，应说“一袋沃土”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9db8d3-8690-40c9-852d-62d2b3d3f523') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们院子里的沃土了特别松，蔬菜长得很快。", "corrected_sentence": "我们院子里的沃土特别松，蔬菜长得很快。", "error_description": "“了”不能直接接在名词“沃土”后面，此处是多余的。应去掉“了”，说“我们院子里的沃土特别松”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9db8d3-8690-40c9-852d-62d2b3d3f523') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
