INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23164, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事物或人经过根本性的变化，从旧的样子变成全新的样子，例如小虫子变成蝴蝶。", "primary_collocate": null, "pronunciation": "tuì biàn", "ipa": "tʰweɪ˥˩ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "毛毛虫经过蜕变，成了漂亮的蝴蝶。", "target_word": "蜕变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小公司慢慢蜕变成了大企业。", "target_word": "蜕变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一年的训练，他蜕变成了真正的运动员。", "target_word": "蜕变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青蛙小时候要先蜕变，才能上岸生活。", "target_word": "蜕变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从害羞的女孩蜕变为自信的老师。", "target_word": "蜕变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座小城正在蜕变成一个现代化的城市。", "target_word": "蜕变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失败让他蜕变了，不再像以前那样懒。", "target_word": "蜕变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毛毛虫要先蜕变，才能变成蝴蝶飞起来。", "target_word": "蜕变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行让我从小孩蜕变成大人。", "target_word": "蜕变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子这几年蜕变得很快。", "target_word": "蜕变", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蜕变了", "label": "体标"}, {"form": "蜕变过", "label": "体标"}, {"form": "蜕变成", "label": "动结形式"}], "register": "中性", "sense_fingerprint": "经过变化，从旧的样子变成全新的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '893d22fe-4f1c-4df4-bc7b-16eb250f9a8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23164, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蜕变", "is_correct": true, "explanation": "蜕变：指经过变化、从旧样子变成新样子，与「毛毛虫经过」搭配，符合句意。"}, {"text": "放大", "is_correct": false, "explanation": "语义：「放大」是使东西变大，不能让毛毛虫变成蝴蝶。"}, {"text": "燃烧", "is_correct": false, "explanation": "语义：「燃烧」是物体着火化为灰烬，与「成了漂亮的蝴蝶」不相符。"}, {"text": "吹牛", "is_correct": false, "explanation": "语义：「吹牛」指说大话，不能表示毛毛虫变成蝴蝶的过程。"}], "explanations": {"蜕变": "蜕变：指经过变化、从旧样子变成新样子，与「毛毛虫经过」搭配，符合句意。", "放大": "语义：「放大」是使东西变大，不能让毛毛虫变成蝴蝶。", "燃烧": "语义：「燃烧」是物体着火化为灰烬，与「成了漂亮的蝴蝶」不相符。", "吹牛": "语义：「吹牛」指说大话，不能表示毛毛虫变成蝴蝶的过程。"}, "sentence_index": 0, "correct_answer": "蜕变"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蛇每年要蜕变两三次。", "explanation": "这里应该用〈蜕皮〉。蛇只是换一层皮，没有变成另一种形态，蜕变用于整体形态的转变。"}, {"text": "这次感冒让他蜕变得很厉害，整个人都没精神了。", "explanation": "这里应该用〈加重〉。蜕变指事物的形态或性质发生根本转变，病情变严重要用加重，不能用蜕变。"}, {"text": "牛奶放久了会蜕变。", "explanation": "这里应该用〈变质〉。蜕变指积极的、整体的形态转变，牛奶变坏要用变质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜕变", "is_correct": true, "explanation": "蜕变：指人经过失败后发生了根本变化，与「让他」搭配，符合句意。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：「冻结」是变成固体或停止不动，不能用来形容失败后人的变化。"}, {"text": "减肥", "is_correct": false, "explanation": "语义：「减肥」指减轻体重，与「失败」带来的性格变化无关。"}, {"text": "拍马屁", "is_correct": false, "explanation": "语域：「拍马屁」是口语化的讨好说法，不适合用在描述性格转变的句子中。"}], "explanations": {"蜕变": "蜕变：指人经过失败后发生了根本变化，与「让他」搭配，符合句意。", "冻结": "语义：「冻结」是变成固体或停止不动，不能用来形容失败后人的变化。", "减肥": "语义：「减肥」指减轻体重，与「失败」带来的性格变化无关。", "拍马屁": "语域：「拍马屁」是口语化的讨好说法，不适合用在描述性格转变的句子中。"}, "sentence_index": 6, "correct_answer": "蜕变"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个村子的人口蜕变了很多。", "explanation": "这里应该用〈增加〉。蜕变指事物整体形态或性质的转变，人口变多要用增加。"}, {"text": "这几年村里的垃圾蜕变了很多。", "explanation": "这里应该用〈减少〉。垃圾数量变少要用减少，蜕变不能用于数量的减少。"}, {"text": "这座小城的规模蜕变了不少。", "explanation": "这里应该用〈扩大〉。规模、范围的增长要用扩大，蜕变指整体形态的转变，不用于规模。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只小蝌蚪慢慢蜕变到了青蛙。", "corrected_sentence": "这只小蝌蚪慢慢蜕变成了青蛙。", "error_description": "错误：结果补语用错了。表示变成另一种事物要用「成」，不能用「到」，应说「蜕变成了青蛙」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校蜕变在一所现代化的大学。", "corrected_sentence": "这所学校蜕变为一所现代化的大学。", "error_description": "错误：结果补语「在」用错了。表示变成另一种事物要用「为」或「成」，不能用「在」，应说「蜕变为一所现代化的大学」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
