INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23166, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西原来在的地方变成了另一个地方。", "primary_collocate": null, "pronunciation": "wèi yí", "ipa": "wei˥˩ i˧˥", "syllable_count": 2, "sentences": [{"text": "大雨后，山上的石头发生了位移。", "target_word": "位移", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震让这栋楼发生了很小的位移。", "target_word": "位移", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书架没有位移，是我记错了位置。", "target_word": "位移", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人量了一下管子的位移。", "target_word": "位移", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边的沙子每年都有位移。", "target_word": "位移", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地板下面的水管出现了位移，所以漏水了。", "target_word": "位移", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张照片显示了墙体的位移，裂缝很明显。", "target_word": "位移", "complexity_tier": "T3", "furigana": "Zhè zhāng zhàopiàn xiǎnshì le qiángtǐ de wèiyí, lièfèng hěn míngxiǎn.", "sentence_source": "generated"}, {"text": "强风使帐篷发生了位移。", "target_word": "位移", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河的河床慢慢发生位移，岸边变了样。", "target_word": "位移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我发现门口的花盆有位移，一定有人动过它。", "target_word": "位移", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "位移|东西所在位置的改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab623cb5-ee24-4aec-89c3-b126ca65d1ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23166, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "位移", "is_correct": true, "explanation": "正确：“山上的石头发生了位移”指石头原来的位置发生了改变，语义通顺。"}, {"text": "香味", "is_correct": false, "explanation": "语义：石头不会发生“香味”的变化，“香味”是气味，与石头的位置无关。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“发生了”后不接“工资”，且与石头无关。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”是人或动物行走的动作，石头没有脚步。"}], "explanations": {"位移": "正确：“山上的石头发生了位移”指石头原来的位置发生了改变，语义通顺。", "香味": "语义：石头不会发生“香味”的变化，“香味”是气味，与石头的位置无关。", "工资": "搭配：“发生了”后不接“工资”，且与石头无关。", "脚步": "语义：“脚步”是人或动物行走的动作，石头没有脚步。"}, "sentence_index": 0, "correct_answer": "位移"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们昨天位移了，搬到了新房子里。", "explanation": "这里应该用〈搬家〉。“位移”只用于东西原来位置的改变，不用于人或家庭的迁居。"}, {"text": "他的心情突然发生了位移，大家都没察觉。", "explanation": "这里应该用〈变化〉。“位移”只指东西位置的改变，不用于心情。"}, {"text": "我的工作发生了位移，现在我当老师了。", "explanation": "这里应该用〈变动〉。“位移”只指东西所在位置的改变，不用于工作的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db74969-bc3a-4f78-be8a-a16ad1d7ff90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23166, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "位移", "is_correct": true, "explanation": "正确：“这张照片显示了墙体的位移”指墙体位置的改变，与“裂缝很明显”相符。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”属于人，不能用来形容墙体，与裂缝无关。"}, {"text": "味道", "is_correct": false, "explanation": "语义：照片无法显示墙体的味道，“味道”与裂缝毫无关系。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“墙体的手机”搭配不当，“手机”不是墙体的特征。"}], "explanations": {"位移": "正确：“这张照片显示了墙体的位移”指墙体位置的改变，与“裂缝很明显”相符。", "性格": "语义：“性格”属于人，不能用来形容墙体，与裂缝无关。", "味道": "语义：照片无法显示墙体的味道，“味道”与裂缝毫无关系。", "手机": "搭配：“墙体的手机”搭配不当，“手机”不是墙体的特征。"}, "sentence_index": 6, "correct_answer": "位移"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成绩从第一名位移到第五名。", "explanation": "这里应该用〈下降〉。“位移”只指东西位置的改变，不用于成绩或排名。"}, {"text": "他的想法发生了位移，不再同意我们了。", "explanation": "这里应该用〈改变〉。“位移”只指东西位置的改变，不用于想法。"}, {"text": "我弟弟昨天位移到了广州工作。", "explanation": "这里应该用〈去〉。“位移”只用于东西原来位置的改变，人迁往外地不用“位移”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db74969-bc3a-4f78-be8a-a16ad1d7ff90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墙上的画因为地震发生了一颗位移。", "corrected_sentence": "墙上的画因为地震发生了位移。", "error_description": "错误形式“发生了一颗位移”，正确形式“发生了位移”。“位移”是名词，这里直接与“发生了”搭配，不加“颗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db74969-bc3a-4f78-be8a-a16ad1d7ff90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "房梁做了位移，裂缝很明显。", "corrected_sentence": "房梁发生了位移，裂缝很明显。", "error_description": "错误形式“房梁做了位移”，正确形式“房梁发生了位移”。“位移”与“做”不搭配，表示结构位置改变时应用“发生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db74969-bc3a-4f78-be8a-a16ad1d7ff90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
