INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23170, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23170, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "意思是“特别”，比如“他学习尤为认真”，就是说他学习特别认真。", "primary_collocate": null, "pronunciation": "yóu wéi", "ipa": "joʊ˧˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这个问题对新手来说尤为重要。", "target_word": "尤为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的傍晚，这条河边尤为热闹。", "target_word": "尤为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的安全尤为关键。", "target_word": "尤为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨后，山路尤为难走。", "target_word": "尤为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对数学尤为感兴趣。", "target_word": "尤为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的冬天，早晨的寒冷尤为明显。", "target_word": "尤为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在所有学生里，她的进步尤为突出。", "target_word": "尤为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老年人在冬天尤为需要保暖。", "target_word": "尤为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行的经历尤为难忘。", "target_word": "尤为", "complexity_tier": "T3", "furigana": "zhè cì lǚ xíng de jīng lì yóu wéi nán wàng", "sentence_source": "generated"}, {"text": "这几种水果里，苹果尤为受欢迎。", "target_word": "尤为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "副词，表示程度特别高，用在形容词或动词前，多见于书面语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c158727a-e2ac-46d3-b271-c699b7ec501e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23170, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尤为", "is_correct": true, "explanation": "正确：“尤为”是程度副词，表示特别，修饰“重要”语义通顺。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”只说明时间，不表示程度，句意不通。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”表示过去，与“这个问题对新手来说”的现在判断不符。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”一般与否定词连用，不直接修饰“重要”。"}], "explanations": {"尤为": "正确：“尤为”是程度副词，表示特别，修饰“重要”语义通顺。", "已经": "语义：“已经”只说明时间，不表示程度，句意不通。", "曾经": "语义：“曾经”表示过去，与“这个问题对新手来说”的现在判断不符。", "根本": "搭配：“根本”一般与否定词连用，不直接修饰“重要”。"}, "sentence_index": 0, "correct_answer": "尤为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他尤为送了我一本书。", "explanation": "这里应该用〈还〉。“还”表示在原有的基础上增加，如“还送了我一本书”；“尤为”表示程度，不能表示另外送东西的动作。"}, {"text": "我的书包尤为在桌子上。", "explanation": "这里应该用〈放在〉。“放在”表示物品被放置在某处；“尤为”只表示程度，不能表示放置的动作。"}, {"text": "这件事尤为发生了。", "explanation": "这里应该用〈已经〉。“已经”表示动作已经完成，“尤为”是程度副词，不能修饰“发生”这类非程度的动词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尤为", "is_correct": true, "explanation": "正确：“尤为”表示程度特别高，与“在所有学生里”的比较语境相符。"}, {"text": "忽然", "is_correct": false, "explanation": "搭配：“忽然”表示突然发生，不能用来修饰“突出”这类表示状态的词，句子不通。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”表示共同做某事，不能修饰“突出”这类性质词，句子不通。"}, {"text": "一共", "is_correct": false, "explanation": "搭配：“一共”表示总计数量，不能修饰“突出”这类性质词，句子不通。"}], "explanations": {"尤为": "正确：“尤为”表示程度特别高，与“在所有学生里”的比较语境相符。", "忽然": "搭配：“忽然”表示突然发生，不能用来修饰“突出”这类表示状态的词，句子不通。", "一起": "搭配：“一起”表示共同做某事，不能修饰“突出”这类性质词，句子不通。", "一共": "搭配：“一共”表示总计数量，不能修饰“突出”这类性质词，句子不通。"}, "sentence_index": 6, "correct_answer": "尤为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天天气尤为冷了。", "explanation": "这里应该用〈更〉。“更”可表示程度加深、用于变化，如“更冷了”；“尤为”表示突出的程度，不能用于变化的过程。"}, {"text": "我尤为把作业做完了。", "explanation": "这里应该用〈终于〉。“终于”表示经过很久后终于实现，“尤为”表示程度，不能表示完成的时间。"}, {"text": "他尤为来了。", "explanation": "这里应该用〈又〉。“又”表示动作再次发生，“尤为”表示程度，不能表示再次来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市的夜景尤为的漂亮。", "corrected_sentence": "这座城市的夜景尤为漂亮。", "error_description": "错误在助词：“尤为”是程度副词，直接修饰形容词，中间不能加“的”。应说“尤为漂亮”，不说“尤为的漂亮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路在夜里尤为很危险。", "corrected_sentence": "这条路在夜里尤为危险。", "error_description": "错误在程度副词叠用：“尤为”已经表示程度，不能再加“很”，应说“尤为危险”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
