INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23172, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "终点是走路或跑步最后停下来的地方。", "primary_collocate": null, "pronunciation": "zhōng diǎn", "ipa": "ʈʂʊŋ⁵⁵ tiɛn²¹⁴", "syllable_count": 2, "sentences": [{"text": "爬了三个小时，我们到了终点。", "target_word": "终点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场长跑的终点在公园门口。", "target_word": "终点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑到终点后，他坐在地上休息。", "target_word": "终点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "终点离这里还有两公里。", "target_word": "终点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明第一个跑到终点。", "target_word": "终点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们在终点等着我们。", "target_word": "终点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走到终点，大家都累坏了。", "target_word": "终点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小路的终点是一座小山。", "target_word": "终点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭着跑过了终点。", "target_word": "终点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看见终点前站着很多人。", "target_word": "终点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个终点", "label": "量词"}, {"form": "终点站", "label": "复合"}], "register": "中性", "sense_fingerprint": "走路或跑步最后停下来的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faaf0adf-bcc7-4fc0-9a0d-0cbdbb6e51dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23172, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "终点", "is_correct": true, "explanation": "终点：走路或跑步最后停下来的地方，与听到的读音一致。"}, {"text": "重点", "is_correct": false, "explanation": "zhòng（第四声）与 zhōng（第一声）声调不同，意思是重要的地方。"}, {"text": "重典", "is_correct": false, "explanation": "zhòng（第四声）与 zhōng（第一声）声调不同，意思是严厉的法律。"}, {"text": "争点", "is_correct": false, "explanation": "zhēng（第一声）与 zhōng（第一声）韵母不同（eng/ong），意思是争论的焦点。"}], "explanations": {"终点": "终点：走路或跑步最后停下来的地方，与听到的读音一致。", "重点": "zhòng（第四声）与 zhōng（第一声）声调不同，意思是重要的地方。", "重典": "zhòng（第四声）与 zhōng（第一声）声调不同，意思是严厉的法律。", "争点": "zhēng（第一声）与 zhōng（第一声）韵母不同（eng/ong），意思是争论的焦点。"}, "sentence_index": null, "correct_answer": "终点"}, "level_3": {"options": [{"text": "终点", "is_correct": true, "explanation": "“终点”是走到后停下的地方，句意通顺。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：“夏天”是时间，不是走路要到达的地点；“爬了三个小时”之后应到达的是地点，“到了夏天”与句意不符。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”是物品，“爬了三个小时”后不能到达它。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：“午饭”指饭食，不是走路要到达的地点，句中“到了”应接地点。"}], "explanations": {"终点": "“终点”是走到后停下的地方，句意通顺。", "夏天": "语义：“夏天”是时间，不是走路要到达的地点；“爬了三个小时”之后应到达的是地点，“到了夏天”与句意不符。", "黑板": "语义：“黑板”是物品，“爬了三个小时”后不能到达它。", "午饭": "语义：“午饭”指饭食，不是走路要到达的地点，句中“到了”应接地点。"}, "sentence_index": 0, "correct_answer": "终点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们走进了终点。", "explanation": "这里应该用〈教室〉。终点指路程或比赛结束的位置，走进房间要说教室。"}, {"text": "妈妈在终点做饭。", "explanation": "这里应该用〈厨房〉。终点指路程或过程结束的位置，做饭要在厨房。"}, {"text": "运动员站在终点上准备。", "explanation": "这里应该用〈起跑线〉。准备起跑的人应站在起跑线上，终点是跑完停下的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9db8d3-8690-40c9-852d-62d2b3d3f523') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "终点", "is_correct": true, "explanation": "“终点”是走到后停下的地方，句意通顺。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“走到”后接地方，“书包”是物品，不能走到。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”是乐器，不能作“走到”的目标地点。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：“走到”接地点，不说“走到水果”。"}], "explanations": {"终点": "“终点”是走到后停下的地方，句意通顺。", "书包": "语义：“走到”后接地方，“书包”是物品，不能走到。", "钢琴": "语义：“钢琴”是乐器，不能作“走到”的目标地点。", "水果": "搭配：“走到”接地点，不说“走到水果”。"}, "sentence_index": 6, "correct_answer": "终点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们从终点进去。", "explanation": "这里应该用〈入口〉。终点是路程结束的地方，进入场所要从入口进去。"}, {"text": "他去终点看病。", "explanation": "这里应该用〈医院〉。终点指路程或过程结束的位置，看病要去医院。"}, {"text": "我们在终点看书。", "explanation": "这里应该用〈图书馆〉。终点指路程或过程结束的位置，看书要去图书馆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9db8d3-8690-40c9-852d-62d2b3d3f523') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于跑在终点了。", "corrected_sentence": "他终于跑到终点了。", "error_description": "“跑”与“终点”之间应用“到”表示到达，不能用“在”。应说“跑到终点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9db8d3-8690-40c9-852d-62d2b3d3f523') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场比赛只有一只终点。", "corrected_sentence": "这场比赛只有一个终点。", "error_description": "“终点”的量词应用“个”，“只”多用于动物，不能说“一只终点”。应说“只有一个终点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9db8d3-8690-40c9-852d-62d2b3d3f523') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
