INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23180, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个事情引起另一个事情，这样一直下去。", "primary_collocate": null, "pronunciation": "liàn shì fǎn yìng", "ipa": "ljɛn⁵¹ ʂʐ̩⁵¹ fan²¹⁴ iŋ⁵¹", "syllable_count": 4, "sentences": [{"text": "一件小事会引起链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他迟到了，结果出现了链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个坏消息引起了链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的车停下来，后面的车也停下来，这是链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水价上涨，带来了链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要小看这件事，它可能引起链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他起床晚，全家都晚了，真是链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的结果引起了链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骨牌一个接一个倒下，就是链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的好心情在办公室里引起了链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场链式反应", "label": "量词"}], "register": "中性", "sense_fingerprint": "一件事引起另一件事，连续不断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faaf0adf-bcc7-4fc0-9a0d-0cbdbb6e51dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23180, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "链式反应", "is_correct": true, "explanation": "正确。“一件小事会引起链式反应”指一件事接连引出后续事件，与句意相符。"}, {"text": "身材", "is_correct": false, "explanation": "语义：“身材”指人的体型，不能作为小事引起的后果。"}, {"text": "饮水机", "is_correct": false, "explanation": "语义：“饮水机”是一种家电，不是事件，不能作为小事引起的结果。"}, {"text": "天气预报", "is_correct": false, "explanation": "搭配：“引起”后接的是事件或后果，“天气预报”是播报内容，不能作为引起的结果。"}], "explanations": {"链式反应": "正确。“一件小事会引起链式反应”指一件事接连引出后续事件，与句意相符。", "身材": "语义：“身材”指人的体型，不能作为小事引起的后果。", "饮水机": "语义：“饮水机”是一种家电，不是事件，不能作为小事引起的结果。", "天气预报": "搭配：“引起”后接的是事件或后果，“天气预报”是播报内容，不能作为引起的结果。"}, "sentence_index": 0, "correct_answer": "链式反应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她对我的道歉没有链式反应，只是低头走开了。", "explanation": "这里应该用〈回应〉。链式反应指一连串事件相继发生，对道歉的单次应答要用“回应”。"}, {"text": "这家商店的链式反应很便宜。", "explanation": "这里应该用〈东西〉。链式反应指一连串事件相继发生，不是商品，不能说便宜。"}, {"text": "这次比赛他的链式反应很好。", "explanation": "这里应该用〈成绩〉。链式反应不是成绩，不能用来评价一个人这次比赛的表现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9db8d3-8690-40c9-852d-62d2b3d3f523') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "链式反应", "is_correct": true, "explanation": "正确。“真是链式反应”用来形容一件事接连引起的连锁后果，与“全家都晚了”相符。"}, {"text": "牙膏", "is_correct": false, "explanation": "语义：“牙膏”是日用品，不能用来形容一连串的连锁结果。"}, {"text": "流体力学", "is_correct": false, "explanation": "语域：“流体力学”是学术术语，不适合用在日常口语的感叹句中。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：“图书馆”指一个场所，不能用来概括这种接连发生的结果。"}], "explanations": {"链式反应": "正确。“真是链式反应”用来形容一件事接连引起的连锁后果，与“全家都晚了”相符。", "牙膏": "语义：“牙膏”是日用品，不能用来形容一连串的连锁结果。", "流体力学": "语域：“流体力学”是学术术语，不适合用在日常口语的感叹句中。", "图书馆": "语义：“图书馆”指一个场所，不能用来概括这种接连发生的结果。"}, "sentence_index": 6, "correct_answer": "链式反应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家对这个活动的链式反应很高。", "explanation": "这里应该用〈热情〉。链式反应描述事件的连续发生，不能用来表示人的热情高低。"}, {"text": "她对老家的链式反应很深。", "explanation": "这里应该用〈感情〉。链式反应不是情感，不能用来表示对老家的感情深浅。"}, {"text": "他对这位老师的链式反应很好。", "explanation": "这里应该用〈印象〉。链式反应不表示对某人的印象好坏，应该用“印象”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9db8d3-8690-40c9-852d-62d2b3d3f523') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个小失误就能引起到一场链式反应。", "corrected_sentence": "一个小失误就能引起一场链式反应。", "error_description": "补语错误：“引起”后直接带宾语，不能插入“到”。应删去“到”，改为“一个小失误就能引起一场链式反应。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9db8d3-8690-40c9-852d-62d2b3d3f523') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一次小争执引起了一片链式反应。", "corrected_sentence": "一次小争执引起了一场链式反应。", "error_description": "量词错误：“片”用于叶子、田野等平面的东西，不能用于事件。“链式反应”可用量词“场”，应改为“一场链式反应”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9db8d3-8690-40c9-852d-62d2b3d3f523') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23182, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "观察", "is_correct": false, "explanation": "无关：“观察”指仔细看，与“建构”没有反义关系。"}, {"text": "拆开", "is_correct": true, "explanation": "反义：“拆开”指把搭好的东西一块块分开，与“建构”相对。"}, {"text": "欣赏", "is_correct": false, "explanation": "无关：“欣赏”指觉得美好而喜爱，与“建构”没有反义关系。"}, {"text": "购买", "is_correct": false, "explanation": "无关：“购买”指花钱买东西，与“建构”没有反义关系。"}], "correct_answer": "拆开", "explanations": {"观察": "无关：“观察”指仔细看，与“建构”没有反义关系。", "拆开": "反义：“拆开”指把搭好的东西一块块分开，与“建构”相对。", "欣赏": "无关：“欣赏”指觉得美好而喜爱，与“建构”没有反义关系。", "购买": "无关：“购买”指花钱买东西，与“建构”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23182, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "挑选", "is_correct": false, "explanation": "无关：“挑选”指从多个中选出想要的，与“建构”没有反义关系。"}, {"text": "收藏", "is_correct": false, "explanation": "无关：“收藏”指把东西保存起来，与“建构”没有反义关系。"}, {"text": "拆解", "is_correct": true, "explanation": "反义：“拆解”指把搭好的东西一块块拆开，与“建构”相对。"}, {"text": "搬运", "is_correct": false, "explanation": "无关：“搬运”指把东西从一处移到另一处，与“建构”没有反义关系。"}], "correct_answer": "拆解", "explanations": {"挑选": "无关：“挑选”指从多个中选出想要的，与“建构”没有反义关系。", "收藏": "无关：“收藏”指把东西保存起来，与“建构”没有反义关系。", "拆解": "反义：“拆解”指把搭好的东西一块块拆开，与“建构”相对。", "搬运": "无关：“搬运”指把东西从一处移到另一处，与“建构”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23182, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西搭好、盖好，比如搭积木盖房子。", "primary_collocate": null, "pronunciation": "jiàn gòu", "ipa": "tɕjɛn˥˩ kou̯˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们用积木建构了一座小城堡。", "target_word": "建构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹用积木建构了一个小房子，很开心。", "target_word": "建构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在活动课上建构了一座积木房子。", "target_word": "建构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用纸盒建构了一座漂亮的桥。", "target_word": "建构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在课上建构了一个小城市模型。", "target_word": "建构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明正在建构他的积木城市。", "target_word": "建构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用彩色积木建构了一座小楼。", "target_word": "建构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在桌上用积木建构了一座小塔。", "target_word": "建构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩这个游戏，你可以建构自己的小镇。", "target_word": "建构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想用这些方块建构一个高高的塔。", "target_word": "建构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "建构了", "label": "完成体"}, {"form": "建构着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "把东西一块一块搭起来、盖起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f735cfaa-c81a-4eea-8896-d7ab5126a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23182, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能接“小城堡”作宾语，积木也不能吃。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指用笔写字，不能用积木写出城堡。"}, {"text": "建构", "is_correct": true, "explanation": "正确：“建构”指用积木搭成城堡，符合句意。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”用于衣物、器皿等，不能和“小城堡”搭配。"}], "explanations": {"吃": "搭配：“吃”不能接“小城堡”作宾语，积木也不能吃。", "写": "语义：“写”指用笔写字，不能用积木写出城堡。", "建构": "正确：“建构”指用积木搭成城堡，符合句意。", "洗": "搭配：“洗”用于衣物、器皿等，不能和“小城堡”搭配。"}, "sentence_index": 0, "correct_answer": "建构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用面粉建构了一块蛋糕。", "explanation": "这里应该用〈制作〉。建构指搭建有结构的东西，做蛋糕这类食物要用制作。"}, {"text": "她用毛线建构了一条围巾。", "explanation": "这里应该用〈编织〉。建构指搭建有结构的物体，用毛线织围巾要用编织。"}, {"text": "他建构了一套新服装。", "explanation": "这里应该用〈设计〉。建构指把东西搭成有结构的实体，设计服装是画出款式，建构不用于服装。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喂", "is_correct": false, "explanation": "搭配：“喂”用于人或动物，不能接“小楼”作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与用积木搭楼的意思不相符。"}, {"text": "建构", "is_correct": true, "explanation": "正确：“建构”指用彩色积木搭成小楼，符合句意。"}, {"text": "陪", "is_correct": false, "explanation": "配价：“陪”的对象须是有生命的人，不能用于“小楼”。"}], "explanations": {"喂": "搭配：“喂”用于人或动物，不能接“小楼”作宾语。", "唱": "语义：“唱”指发出歌声，与用积木搭楼的意思不相符。", "建构": "正确：“建构”指用彩色积木搭成小楼，符合句意。", "陪": "配价：“陪”的对象须是有生命的人，不能用于“小楼”。"}, "sentence_index": 6, "correct_answer": "建构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸建构了那把坏掉的椅子。", "explanation": "这里应该用〈修理〉。修理是把坏的东西修好，建构指搭建新的结构，不能表示修复旧物。"}, {"text": "妈妈建构了一桌好菜。", "explanation": "这里应该用〈烹饪〉。烹饪指做菜，建构不用于做饭。"}, {"text": "她建构了一幅山水画。", "explanation": "这里应该用〈画〉。画是用笔描绘图形，建构是搭建立体结构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们用钢筋建构着了一座新桥。", "corrected_sentence": "工人们用钢筋建构了一座新桥。", "error_description": "“着”表示动作持续，“了”表示动作完成，二者不能同时标在“建构”上；应去掉“着”，说“建构了一座新桥”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她被这些木条建构了一个三角形的架子。", "corrected_sentence": "她用这些木条建构了一个三角形的架子。", "error_description": "表示工具的“用”被误用成“被”：“被”引出被动的施事，这里“这些木条”是工具，应说“用这些木条建构”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
