INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23184, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容一件事像在做仪式，很正式。", "primary_collocate": null, "pronunciation": "yí shì xìng", "ipa": "i˧˥ ʂʐ̩˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "新年的第一顿饭很有仪式性。", "target_word": "仪式性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天泡茶的动作带着仪式性。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业时的握手有点仪式性。", "target_word": "仪式性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个欢迎会太有仪式性，大家都很紧张。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把送礼物做得很有仪式性。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每次出门前都要照镜子，很有仪式性。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的晚餐不用太仪式性，随便吃吧。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "签字的动作看起来很仪式性。", "target_word": "仪式性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打开箱子的过程有一种仪式性。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "升旗时大家站得笔直，非常有仪式性。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "儀式性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "仪式性：一件事做起来像仪式，很正式、很郑重", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3701140-a2a2-4137-8b61-b34e446ee27a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23184, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仪式性", "is_correct": true, "explanation": "正确：“很有仪式性”形容这顿饭郑重、讲究形式，符合新年的氛围。"}, {"text": "竞争性", "is_correct": false, "explanation": "语义：“竞争性”指争夺胜负，与新年团圆的饭不相符。"}, {"text": "危险性", "is_correct": false, "explanation": "语义：“危险性”指可能带来危险，新年的第一顿饭没有危险，说不通。"}, {"text": "攻击性", "is_correct": false, "explanation": "语义：“攻击性”与团圆、和气的氛围完全相反。"}], "explanations": {"仪式性": "正确：“很有仪式性”形容这顿饭郑重、讲究形式，符合新年的氛围。", "竞争性": "语义：“竞争性”指争夺胜负，与新年团圆的饭不相符。", "危险性": "语义：“危险性”指可能带来危险，新年的第一顿饭没有危险，说不通。", "攻击性": "语义：“攻击性”与团圆、和气的氛围完全相反。"}, "sentence_index": 0, "correct_answer": "仪式性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们午饭吃得很仪式性，五分钟就完了。", "explanation": "这里应该用〈快〉。“仪式性”形容郑重讲究的仪式特点，与五分钟就吃完的快速相矛盾。"}, {"text": "他仪式性地打了个哈欠。", "explanation": "这里应该用〈无意识〉。“仪式性”指刻意、郑重地做事，打哈欠是无意识的生理反应，不能说“仪式性地”。"}, {"text": "他随口问了一句，语气很仪式性。", "explanation": "这里应该用〈随意〉。“仪式性”形容事情像在做仪式、很正式，不用来形容随口一问的语气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b01744-fea4-45c1-a265-f99cdcb32ce5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23184, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仪式性", "is_correct": true, "explanation": "正确：“不用太仪式性”表示不必过于讲究形式，与后半句“随便吃吧”一致。"}, {"text": "随便", "is_correct": false, "explanation": "语义：“不用太随便”与后半句“随便吃吧”自相矛盾。"}, {"text": "马虎", "is_correct": false, "explanation": "搭配：“马虎”多形容做事、做作业不认真，不用来形容晚餐的形式。"}, {"text": "草率", "is_correct": false, "explanation": "语义：“草率”含不认真、不慎重之意，用在晚餐上语义不当。"}], "explanations": {"仪式性": "正确：“不用太仪式性”表示不必过于讲究形式，与后半句“随便吃吧”一致。", "随便": "语义：“不用太随便”与后半句“随便吃吧”自相矛盾。", "马虎": "搭配：“马虎”多形容做事、做作业不认真，不用来形容晚餐的形式。", "草率": "语义：“草率”含不认真、不慎重之意，用在晚餐上语义不当。"}, "sentence_index": 6, "correct_answer": "仪式性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "街边的小吃摊很仪式性，老板大声吆喝。", "explanation": "这里应该用〈热闹〉。“仪式性”形容事情像在做仪式、很正式，不用来形容街边小吃摊的吆喝。"}, {"text": "孩子们在操场上玩得很仪式性。", "explanation": "这里应该用〈活泼〉。“仪式性”形容郑重的仪式特点，不用来形容孩子玩耍的状态。"}, {"text": "这台冰箱很仪式性，能装很多东西。", "explanation": "这里应该用〈大〉。“仪式性”形容做事郑重、像仪式，不用来形容冰箱的容量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b01744-fea4-45c1-a265-f99cdcb32ce5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一刻有很仪式性，大家都安静下来。", "corrected_sentence": "这一刻很有仪式性，大家都安静下来。", "error_description": "错误：“有很仪式性”，“很”与“有”的语序颠倒。正确：“很有仪式性”，“很”修饰“有”，“有”带宾语“仪式性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b01744-fea4-45c1-a265-f99cdcb32ce5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次告别有一个仪式性，大家都很郑重。", "corrected_sentence": "这次告别有一种仪式性，大家都很郑重。", "error_description": "错误形式：“有一个仪式性”；正确形式：“有一种仪式性”。“仪式性”是抽象性质，不用量词“个”，应说“一种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b01744-fea4-45c1-a265-f99cdcb32ce5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
