INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23186, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使化学反应或变化过程加快。", "primary_collocate": null, "pronunciation": "cuī huà", "ipa": "tsʰweɪ˥ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "实验里加了铁粉，可以催化反应。", "target_word": "催化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，催化就是让反应变快。", "target_word": "催化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人体里的酶能催化食物的消化。", "target_word": "催化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光也能催化这个反应。", "target_word": "催化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酵母能催化面团发酵。", "target_word": "催化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唾液能催化淀粉分解。", "target_word": "催化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用黑色粉末催化了这个反应。", "target_word": "催化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车的净化装置能催化废气变成无害气体。", "target_word": "催化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种物质也可以催化这个变化。", "target_word": "催化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想找一种金属来催化这个反应。", "target_word": "催化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "催化了", "label": "体标"}, {"form": "催化剂", "label": "复合"}, {"form": "催化作用", "label": "复合"}], "register": "中性", "sense_fingerprint": "本义：使化学反应或变化过程加快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6400fda1-5aa5-4407-a552-0ac0924ed60e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23186, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "催化", "is_correct": true, "explanation": "正确。“催化”指促使化学反应加快，与“加了铁粉”的作用一致。"}, {"text": "吸收", "is_correct": false, "explanation": "搭配：“吸收”的宾语是能量、液体等，不能说“吸收反应”。"}, {"text": "承受", "is_correct": false, "explanation": "搭配：“承受”的宾语是压力、打击等，不能用于化学反应。"}, {"text": "报废", "is_correct": false, "explanation": "语义：“报废”指废弃不能再用，与“加了铁粉”促进反应的作用相反。"}], "explanations": {"催化": "正确。“催化”指促使化学反应加快，与“加了铁粉”的作用一致。", "吸收": "搭配：“吸收”的宾语是能量、液体等，不能说“吸收反应”。", "承受": "搭配：“承受”的宾语是压力、打击等，不能用于化学反应。", "报废": "语义：“报废”指废弃不能再用，与“加了铁粉”促进反应的作用相反。"}, "sentence_index": 0, "correct_answer": "催化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈催化了那个箱子。", "explanation": "这里应该用〈搬〉。催化是使化学反应加快，不能用于搬动箱子这类物理动作。"}, {"text": "他催化了一首歌。", "explanation": "这里应该用〈唱〉。催化指使化学反应或变化过程加快，不指演唱歌曲。"}, {"text": "仪器催化了反应的温度。", "explanation": "这里应该用〈测量〉。催化是使反应加快，不是测量反应的温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23186, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "催化", "is_correct": true, "explanation": "正确。“催化”表示使化学反应加快，与“用黑色粉末”的语境一致。"}, {"text": "撕碎", "is_correct": false, "explanation": "搭配：“撕碎”的对象是纸张等具体物体，不能用于反应。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”与“用黑色粉末”促进化学反应的作用毫不相关。"}, {"text": "涂抹", "is_correct": false, "explanation": "搭配：“涂抹”的对象是物体表面，不能说“涂抹反应”。"}], "explanations": {"催化": "正确。“催化”表示使化学反应加快，与“用黑色粉末”的语境一致。", "撕碎": "搭配：“撕碎”的对象是纸张等具体物体，不能用于反应。", "装饰": "语义：“装饰”与“用黑色粉末”促进化学反应的作用毫不相关。", "涂抹": "搭配：“涂抹”的对象是物体表面，不能说“涂抹反应”。"}, "sentence_index": 6, "correct_answer": "催化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这层滤网催化了杂质。", "explanation": "这里应该用〈过滤〉。催化指使化学反应加快，不能用于滤除杂质。"}, {"text": "工人催化了管道。", "explanation": "这里应该用〈修复〉。催化用于化学反应，不能用于修理管道。"}, {"text": "这种试剂催化了细胞。", "explanation": "这里应该用〈染色〉。催化用于化学反应，不能用于给细胞着色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "加入这种催化剂可以催化了脂肪的氧化。", "corrected_sentence": "加入这种催化剂可以催化脂肪的氧化。", "error_description": "能愿动词“可以”后面不能直接加“了”。正确形式是“可以催化”，“了”应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种金属没催化了这个反应。", "corrected_sentence": "这种金属没催化这个反应。", "error_description": "错误：“没催化了”；正确：“没催化”。用“没”否定已发生的动作时，动词后不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23188, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "站", "is_correct": true, "explanation": "正确：“站”与“坐”相对，指两脚着地直立，与把身体放在椅子上相反。"}, {"text": "吃", "is_correct": false, "explanation": "吃是进食，与“坐”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱是发出乐音，与“坐”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写是书写文字，与“坐”没有反义关系。"}], "correct_answer": "站", "explanations": {"站": "正确：“站”与“坐”相对，指两脚着地直立，与把身体放在椅子上相反。", "吃": "吃是进食，与“坐”没有反义关系。", "唱": "唱是发出乐音，与“坐”没有反义关系。", "写": "写是书写文字，与“坐”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
