INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23190, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下班", "is_correct": true, "explanation": "下班与“上班”相对，指结束工作离开单位，是反义词。"}, {"text": "散步", "is_correct": false, "explanation": "散步指慢慢走路取乐或锻炼，与“上班”没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "读书指看书学习，与“上班”没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳指在水中运动，与“上班”没有反义关系。"}], "correct_answer": "下班", "explanations": {"下班": "下班与“上班”相对，指结束工作离开单位，是反义词。", "散步": "散步指慢慢走路取乐或锻炼，与“上班”没有反义关系。", "读书": "读书指看书学习，与“上班”没有反义关系。", "游泳": "游泳指在水中运动，与“上班”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
