INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23190, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "去工作的地方做事。", "primary_collocate": null, "pronunciation": "shàng bān", "ipa": "ʂɑŋ˥˩ pan˥", "syllable_count": 2, "sentences": [{"text": "爸爸每天早上八点去上班。", "target_word": "上班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我坐地铁上班，大约四十分钟。", "target_word": "上班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈今天不上班，在家休息。", "target_word": "上班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你每天几点上班？", "target_word": "上班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上班的时候很少看手机。", "target_word": "上班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天感冒了，没去上班。", "target_word": "上班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐在银行上班，工作很忙。", "target_word": "上班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我只好走路上班。", "target_word": "上班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她刚上班一个月，就学会了很多东西。", "target_word": "上班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末不用上班，我们去爬山。", "target_word": "上班", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上了班", "label": "离合形式（完成体）"}, {"form": "上过班", "label": "离合形式（经历体）"}, {"form": "上班族", "label": "复合词"}], "register": "中性", "sense_fingerprint": "去工作的地方做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f735cfaa-c81a-4eea-8896-d7ab5126a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23190, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上班", "is_correct": true, "explanation": "正确。“去上班”指去工作单位工作，与“每天早上八点”相合。"}, {"text": "下班", "is_correct": false, "explanation": "语义：下班指结束工作离开单位，与“早上八点去”的时间和方向相反。"}, {"text": "放假", "is_correct": false, "explanation": "搭配：“放假”指假期开始，不能用“去”引出，“去放假”不成立。"}, {"text": "放学", "is_correct": false, "explanation": "搭配：放学是学生的事，不能用于爸爸，“去放学”不成立。"}], "explanations": {"上班": "正确。“去上班”指去工作单位工作，与“每天早上八点”相合。", "下班": "语义：下班指结束工作离开单位，与“早上八点去”的时间和方向相反。", "放假": "搭配：“放假”指假期开始，不能用“去”引出，“去放假”不成立。", "放学": "搭配：放学是学生的事，不能用于爸爸，“去放学”不成立。"}, "sentence_index": 0, "correct_answer": "上班"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "三岁的小弟弟每天七点去上班。", "explanation": "这里应该用〈上幼儿园〉。上班指成年人去单位做事，三岁的小孩每天去的是幼儿园。"}, {"text": "妈妈每天五点上班回家。", "explanation": "这里应该用〈下班〉。上班指开始工作，与“回家”前结束工作的动作相反，应说下班。"}, {"text": "同学们每天八点上班。", "explanation": "这里应该用〈上课〉。学生在学校学习要说上课，上班是成年人在单位工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上班", "is_correct": true, "explanation": "正确。“在银行上班”指在银行工作，与“工作很忙”相合。"}, {"text": "退休", "is_correct": false, "explanation": "语义：退休是离开工作岗位，与“工作很忙”矛盾。"}, {"text": "辞职", "is_correct": false, "explanation": "语义：辞职是离开工作，不能同时说“工作很忙”。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：散步不以银行为场所，“在银行散步”不成立。"}], "explanations": {"上班": "正确。“在银行上班”指在银行工作，与“工作很忙”相合。", "退休": "语义：退休是离开工作岗位，与“工作很忙”矛盾。", "辞职": "语义：辞职是离开工作，不能同时说“工作很忙”。", "散步": "搭配：散步不以银行为场所，“在银行散步”不成立。"}, "sentence_index": 6, "correct_answer": "上班"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "游客每天早上去上班。", "explanation": "这里应该用〈游览〉。上班指去单位工作，游客是去游览，不能说上班。"}, {"text": "我们周末去海边上班，玩了一整天。", "explanation": "这里应该用〈旅游〉。上班指去单位做事，周末去海边玩应说去旅游，不能用上班。"}, {"text": "乘客在车站上班。", "explanation": "这里应该用〈上车〉。上班指去单位工作，乘客在车站应说上车，不能说上班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天公司上班。", "corrected_sentence": "我每天在公司上班。", "error_description": "表示在某个单位工作时，地点要用介词“在”引出，漏掉“在”就错了，应说“在公司上班”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我哥哥医院上班，很辛苦。", "corrected_sentence": "我哥哥在医院上班，很辛苦。", "error_description": "表示在某个地方工作时，地点前要用介词“在”，应说“在医院上班”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
