INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23196, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "表示事情的基础或最重要的部分。", "primary_collocate": null, "pronunciation": "gēn běn", "ipa": "kən˥ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "信任是朋友之间的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公司把客人放在第一位，这是它的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有找到事情的根本，才能把它做好。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书是提高自己的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家庭是社会的根本，家人要互相照顾。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把安全当成工作的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土地是农民生活的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意要守住诚信这个根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的习惯是成长的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡好觉是保持健康的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根本性", "label": "复合"}], "register": "中性", "sense_fingerprint": "根本：名词，事情的基础或最重要的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab623cb5-ee24-4aec-89c3-b126ca65d1ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23196, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根本", "is_correct": true, "explanation": "正确：“根本”指事情的基础，用在“朋友之间的”语境中意思通顺。"}, {"text": "香蕉", "is_correct": false, "explanation": "语义：“香蕉”是水果，不能作为朋友之间的基础。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”多用于买卖，不说“朋友之间的价格”。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：“地毯”是铺在地上的物品，与朋友之间的关系无关。"}], "explanations": {"根本": "正确：“根本”指事情的基础，用在“朋友之间的”语境中意思通顺。", "香蕉": "语义：“香蕉”是水果，不能作为朋友之间的基础。", "价格": "搭配：“价格”多用于买卖，不说“朋友之间的价格”。", "地毯": "语义：“地毯”是铺在地上的物品，与朋友之间的关系无关。"}, "sentence_index": 0, "correct_answer": "根本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路的根本是一座山。", "explanation": "这里应该用〈尽头〉。“根本”指事情的基础或最重要的部分，不指路的终点位置。"}, {"text": "她每天早上都给阳台上的根本浇水。", "explanation": "这里应该用〈花〉。“根本”指事情的基础或最重要的部分，不指具体的植物。"}, {"text": "这个人的根本很漂亮。", "explanation": "这里应该用〈外表〉。“根本”指事物的基础或最重要部分，不指人的外貌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db74969-bc3a-4f78-be8a-a16ad1d7ff90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根本", "is_correct": true, "explanation": "正确：“农民生活的根本”指生活的基础，与句中语境吻合。"}, {"text": "电影", "is_correct": false, "explanation": "语义：“电影”是娱乐作品，不能作为农民生活的基础。"}, {"text": "口号", "is_correct": false, "explanation": "语义：“口号”是标语，不能作为农民生活的基础。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：“游戏”是消遣，与土地对农民生活的作用不相符。"}], "explanations": {"根本": "正确：“农民生活的根本”指生活的基础，与句中语境吻合。", "电影": "语义：“电影”是娱乐作品，不能作为农民生活的基础。", "口号": "语义：“口号”是标语，不能作为农民生活的基础。", "游戏": "语义：“游戏”是消遣，与土地对农民生活的作用不相符。"}, "sentence_index": 6, "correct_answer": "根本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋楼的根本很结实，经得起地震。", "explanation": "这里应该用〈地基〉。“根本”不指建筑的地基，房屋的地基应说“地基”。"}, {"text": "竹子的根本很长，能固定土壤。", "explanation": "这里应该用〈根〉。“根本”指基础或最重要的部分，不指植物的根。"}, {"text": "他是这支乐队的根本成员。", "explanation": "这里应该用〈核心〉。“根本”指抽象的基础，不用来指人，应说“核心成员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db74969-bc3a-4f78-be8a-a16ad1d7ff90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "坚持不懈是成功的一条根本。", "corrected_sentence": "坚持不懈是成功的根本。", "error_description": "错误形式“一条根本”，正确形式“根本”。“条”用于细长的东西，抽象名词“根本”前不用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db74969-bc3a-4f78-be8a-a16ad1d7ff90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "规律作息是保持健康的一把根本。", "corrected_sentence": "规律作息是保持健康的根本。", "error_description": "错误形式“一把根本”，正确形式“根本”。“把”用于有柄的东西，抽象名词“根本”前不用“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db74969-bc3a-4f78-be8a-a16ad1d7ff90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23198, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "停车", "is_correct": true, "explanation": "正确答案。「开车」是让车子行驶，「停车」是让车子停下，两者是一对反义词。"}, {"text": "吃饭", "is_correct": false, "explanation": "「吃饭」与「开车」没有反义关系，是完全不同的两种动作。"}, {"text": "读书", "is_correct": false, "explanation": "「读书」与「开车」没有反义关系，二者不在同一类动作中相对。"}, {"text": "散步", "is_correct": false, "explanation": "「散步」与「开车」没有反义关系，只是两种不同的出行或活动方式。"}], "correct_answer": "停车", "explanations": {"停车": "正确答案。「开车」是让车子行驶，「停车」是让车子停下，两者是一对反义词。", "吃饭": "「吃饭」与「开车」没有反义关系，是完全不同的两种动作。", "读书": "「读书」与「开车」没有反义关系，二者不在同一类动作中相对。", "散步": "「散步」与「开车」没有反义关系，只是两种不同的出行或活动方式。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23198, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "停车", "is_correct": true, "explanation": "正确答案。「开车」是让车子行驶，「停车」是让车子停下，两者是一对反义词。"}, {"text": "跑步", "is_correct": false, "explanation": "「跑步」与「开车」没有反义关系，是不同的运动方式。"}, {"text": "画画", "is_correct": false, "explanation": "「画画」与「开车」没有反义关系，是完全不相关的活动。"}, {"text": "睡觉", "is_correct": false, "explanation": "「睡觉」与「开车」没有反义关系，二者不在同一类行为中相对。"}], "correct_answer": "停车", "explanations": {"停车": "正确答案。「开车」是让车子行驶，「停车」是让车子停下，两者是一对反义词。", "跑步": "「跑步」与「开车」没有反义关系，是不同的运动方式。", "画画": "「画画」与「开车」没有反义关系，是完全不相关的活动。", "睡觉": "「睡觉」与「开车」没有反义关系，二者不在同一类行为中相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23198, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让车子跑起来。", "primary_collocate": null, "pronunciation": "kāi chē", "ipa": "kʰaɪ˥ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "爸爸每天开车上班。", "target_word": "开车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会开车吗？", "target_word": "开车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车的时候不要看手机。", "target_word": "开车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们开车去海边玩。", "target_word": "开车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我开车去机场接朋友。", "target_word": "开车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她刚学会开车，还有点儿紧张。", "target_word": "开车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝了酒就不能开车。", "target_word": "开车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开车开得很稳。", "target_word": "开车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天开车要慢一点儿。", "target_word": "开车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想开车，我们坐地铁吧。", "target_word": "开车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开着车", "label": "体标"}, {"form": "开过车", "label": "体标"}], "register": "口语", "sense_fingerprint": "驾驶汽车等车辆，让车子行驶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76649259-ba21-4681-8829-56e282963d15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23198, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开车", "is_correct": true, "explanation": "正确答案。「开车」指驾驶汽车，与「上班」的交通方式相符。"}, {"text": "开门", "is_correct": false, "explanation": "搭配：「开门」接的是门，不能用来表示上班的交通方式。"}, {"text": "修理", "is_correct": false, "explanation": "配价：「修理」的宾语须是需要修的物品，不能与「上班」组合。"}, {"text": "踢球", "is_correct": false, "explanation": "语义：「踢球」与「上班」搭不上，句意不通。"}], "explanations": {"开车": "正确答案。「开车」指驾驶汽车，与「上班」的交通方式相符。", "开门": "搭配：「开门」接的是门，不能用来表示上班的交通方式。", "修理": "配价：「修理」的宾语须是需要修的物品，不能与「上班」组合。", "踢球": "语义：「踢球」与「上班」搭不上，句意不通。"}, "sentence_index": 0, "correct_answer": "开车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们坐在小船里，开车到湖中间，钓了一下午鱼。", "explanation": "这里应该用〈开船〉。开车指驾驶汽车等陆上车辆，小船要用开船。"}, {"text": "学校下周开车，同学们都很兴奋。", "explanation": "这里应该用〈开学〉。开车指车辆运行，学校开始上课要用开学。"}, {"text": "中午十二点开车，大家都来吃饭了。", "explanation": "这里应该用〈开饭〉。开车指车辆运行，中午端上饭菜要用开饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23198, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开车", "is_correct": true, "explanation": "正确答案。「喝了酒就不能……」是常见的劝诫，填「开车」最合适。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：「喝了酒就不能呼吸」句意不通，「呼吸」与语境无关。"}, {"text": "断奶", "is_correct": false, "explanation": "搭配：「断奶」多用于婴儿，不能用在这个成人的行为限制里。"}, {"text": "诞生", "is_correct": false, "explanation": "语义：「诞生」指新事物出现，与句子中的劝诫意思不合。"}], "explanations": {"开车": "正确答案。「喝了酒就不能……」是常见的劝诫，填「开车」最合适。", "呼吸": "语义：「喝了酒就不能呼吸」句意不通，「呼吸」与语境无关。", "断奶": "搭配：「断奶」多用于婴儿，不能用在这个成人的行为限制里。", "诞生": "语义：「诞生」指新事物出现，与句子中的劝诫意思不合。"}, "sentence_index": 6, "correct_answer": "开车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里开车，准备做饭。", "explanation": "这里应该用〈开火〉。开车指使车辆运行，点火做饭要用开火。"}, {"text": "这台电脑昨天就开车了。", "explanation": "这里应该用〈开机〉。开车指车辆运行，电脑启动要用开机。"}, {"text": "音乐会八点开车，大家都进场了。", "explanation": "这里应该用〈开场〉。开车指车辆运行，演出开始要用开场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23198, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我开车了去海边。", "corrected_sentence": "我开车去了海边。", "error_description": "「开车了去海边」错误：「了」不能紧跟「开车」这个整体之后。「开车」是离合词，「了」可插在「开」和「车」之间（开了车去海边），或放在整个动作「去」之后（开车去了海边）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23198, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他开车着去上班。", "corrected_sentence": "他开着车去上班。", "error_description": "「开车着」错误，正确是「开着车」。持续态助词「着」要放在「开」和「车」之间，不能放在「开车」之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
