INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23206, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23206, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西出来。", "primary_collocate": null, "pronunciation": "fàng chū", "ipa": "faŋ˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "小女孩把盒子里的蝴蝶放出来了。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课了，老师把孩子们放出来玩。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里烟太多，我打开窗户，把烟放出去。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把关在房间里的猫放出来。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把关在地下室里的老鼠放出来了。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烤箱一打开，里面的热气就放出来了。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把气球里的气放出了一点。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他解开绳子，把绑着的小狗放出来了。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把被困在树洞里的小松鼠放出来了。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打开笼子，把仓鼠放出来玩一会儿。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放出了", "label": "体标"}, {"form": "放出来", "label": "复合"}], "register": "中性", "sense_fingerprint": "打开或松开后，让里面的东西出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63f12163-19cc-4b51-bb0d-63aa4777bd4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23206, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放出", "is_correct": true, "explanation": "正确：“放出来”表示把关在盒子里的蝴蝶放走，与句中“盒子里”的情境相合。"}, {"text": "装进", "is_correct": false, "explanation": "语义：蝴蝶本来就在盒子里，“装进来”方向相反，与句意矛盾。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”用于花果、叶子等植物，不能说摘蝴蝶。"}, {"text": "关进", "is_correct": false, "explanation": "语义：蝴蝶本来就在盒子里，“关进”说的是再把它关进去，与句意的状况相矛盾。"}], "explanations": {"放出": "正确：“放出来”表示把关在盒子里的蝴蝶放走，与句中“盒子里”的情境相合。", "装进": "语义：蝴蝶本来就在盒子里，“装进来”方向相反，与句意矛盾。", "摘": "搭配：“摘”用于花果、叶子等植物，不能说摘蝴蝶。", "关进": "语义：蝴蝶本来就在盒子里，“关进”说的是再把它关进去，与句意的状况相矛盾。"}, "sentence_index": 0, "correct_answer": "放出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从包里放出了一本书。", "explanation": "这里应该用〈拿出〉。放出指把关着或被困的东西放走，从包里拿东西要用拿出。"}, {"text": "小猫从门缝里放出了头。", "explanation": "这里应该用〈探出〉。放出指释放被关住的东西，把头伸出去要用探出。"}, {"text": "他把桌上的水杯放出来喝水。", "explanation": "这里应该用〈拿起〉。放出指把关着或被困的东西放走，水杯并没有被关住，应用拿起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23206, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放出", "is_correct": true, "explanation": "正确：“放出了一点”表示气球里的气被放掉一些，与句意相合。"}, {"text": "放下", "is_correct": false, "explanation": "搭配：“放下”的对象是可以拿起的物件，不能说放下气。"}, {"text": "收起", "is_correct": false, "explanation": "搭配：“收起”用于收拾物件，不能用于气体。"}, {"text": "充入", "is_correct": false, "explanation": "语义：“充入”是往里灌，与“气球里的气”已在球内、要放出去的情况相反。"}], "explanations": {"放出": "正确：“放出了一点”表示气球里的气被放掉一些，与句意相合。", "放下": "搭配：“放下”的对象是可以拿起的物件，不能说放下气。", "收起": "搭配：“收起”用于收拾物件，不能用于气体。", "充入": "语义：“充入”是往里灌，与“气球里的气”已在球内、要放出去的情况相反。"}, "sentence_index": 6, "correct_answer": "放出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他放出一个大哈欠。", "explanation": "这里应该用〈打〉。放出指释放被关住或被困的东西，哈欠要说打哈欠，不能说放出。"}, {"text": "妈妈在菜里放出了一勺盐。", "explanation": "这里应该用〈放入〉。放出指把关着的东西放走，往菜里加调料要用放入。"}, {"text": "他从怀里放出一张照片。", "explanation": "这里应该用〈掏出〉。放出指把被关住的东西放走，从怀里拿东西要用掏出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把小狗放出来着。", "corrected_sentence": "他把小狗放出来了。", "error_description": "错误：“放出来着”；正确：“放出来了”。“放出来”表示动作有了结果，后面要用“了”表示完成，不能用表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈打开鸟笼，把小鸟放出来了飞一会儿。", "corrected_sentence": "妈妈打开鸟笼，把小鸟放出来飞一会儿。", "error_description": "错误：“放出来了飞”；正确：“放出来飞”。“了”表示完成，接在动词后面；这里“放出来”后还要接下一个动作，“了”不能夹在“放出来”和“飞”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
