INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23208, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23208, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "我们住的大圆球，有很多很多水、树木和人。", "primary_collocate": null, "pronunciation": "dì qiú", "ipa": "ti˥˩ tɕʰjoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "地球是我们的家。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球上有很多水和树木。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球围着太阳转。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保护地球，少用塑料。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从太空看，地球是蓝色的。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球上的人越来越多了。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宇航员第一次看到了远处的地球。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球一天转一圈。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在课本上画了一个地球。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，地球只有一个。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "地球仪", "label": "复合"}, {"form": "地球村", "label": "复合"}], "register": "中性", "sense_fingerprint": "地球：人类居住的行星", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6750d34-8059-4248-b24c-0c46300c707b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23208, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地球", "is_correct": true, "explanation": "正确。地球是人类居住的行星，读作 dì qiú。"}, {"text": "地区", "is_correct": false, "explanation": "qū（第一声）与 qiú（第二声）韵母与声调都不同，意思是地区，不是行星。"}, {"text": "第九", "is_correct": false, "explanation": "jiǔ（第三声）与 qiú（第二声）声母与声调都不同，意思是“第九”，与“地球”不同。"}, {"text": "皮球", "is_correct": false, "explanation": "pí（第二声）与 dì（第四声）声母与声调都不同，意思是皮球，不是行星。"}], "explanations": {"地球": "正确。地球是人类居住的行星，读作 dì qiú。", "地区": "qū（第一声）与 qiú（第二声）韵母与声调都不同，意思是地区，不是行星。", "第九": "jiǔ（第三声）与 qiú（第二声）声母与声调都不同，意思是“第九”，与“地球”不同。", "皮球": "pí（第二声）与 dì（第四声）声母与声调都不同，意思是皮球，不是行星。"}, "sentence_index": null, "correct_answer": "地球"}, "level_3": {"options": [{"text": "地球", "is_correct": true, "explanation": "正确。地球是人类居住的行星，可以说是我们的家。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是恒星，人类不能在上面居住，不能说是“我们的家”。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“是……的家”要接居住之所，“手机”是随身物品，不能这样搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是人居住的地方，不能说是“我们的家”。"}], "explanations": {"地球": "正确。地球是人类居住的行星，可以说是我们的家。", "太阳": "语义：太阳是恒星，人类不能在上面居住，不能说是“我们的家”。", "手机": "搭配：“是……的家”要接居住之所，“手机”是随身物品，不能这样搭配。", "桌子": "语义：桌子是家具，不是人居住的地方，不能说是“我们的家”。"}, "sentence_index": 0, "correct_answer": "地球"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火星是一颗很冷的地球。", "explanation": "这里指火星，应该用〈星球〉。地球专指人类居住的这颗行星，不能用来称呼其他星球。"}, {"text": "他一脚踩空，摔在了地球旁边的草地上。", "explanation": "这里指草地的位置，应该用〈草地〉。“地球”指整个行星，不能用来定位一块草地。"}, {"text": "夜晚抬头看，地球上满是星星。", "explanation": "这里指天空，应该用〈天上〉。地球指人类居住的行星，星星在天上，不在地球上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23208, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地球", "is_correct": true, "explanation": "正确。地球是人类居住的行星，宇航员在太空中可以看到远处的地球。"}, {"text": "操场", "is_correct": false, "explanation": "语义：宇航员身处太空，看不到地面上的操场，不能说“远处的操场”。"}, {"text": "出租车", "is_correct": false, "explanation": "语义：出租车只在地面行驶，宇航员在太空中看不到它。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱放在地面上的屋子里，宇航员在太空中看不到它。"}], "explanations": {"地球": "正确。地球是人类居住的行星，宇航员在太空中可以看到远处的地球。", "操场": "语义：宇航员身处太空，看不到地面上的操场，不能说“远处的操场”。", "出租车": "语义：出租车只在地面行驶，宇航员在太空中看不到它。", "冰箱": "语义：冰箱放在地面上的屋子里，宇航员在太空中看不到它。"}, "sentence_index": 6, "correct_answer": "地球"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中国是一个大地球。", "explanation": "这里指国家，应该用〈国家〉。地球指人类居住的行星，不能用来称呼一个国家。"}, {"text": "他一脚把地球踢进了球门。", "explanation": "这里指足球，应该用〈足球〉。地球是行星，不能当球来踢。"}, {"text": "我们的老师是一个地球。", "explanation": "这里用“地球”指人，不能用来比喻或称呼老师。“地球”指人类居住的行星。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人类生活地球上。", "corrected_sentence": "人类生活在地球上。", "error_description": "错误：“生活”后面的处所要用“在……上”结构，这里漏掉了“在”。正确说法是：人类生活在地球上。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些行星里只有地球们有生命。", "corrected_sentence": "这些行星里只有地球有生命。", "error_description": "错误：“地球”是无生命的事物，不能加“们”表示复数。正确说法是：只有地球有生命。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
