INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23210, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "公交车走的路线。", "primary_collocate": null, "pronunciation": "gōng jiāo xiàn lù", "ipa": "kʊŋ˥ tɕjɑʊ˥ ɕjɛn˥˩ lu˥˩", "syllable_count": 4, "sentences": [{"text": "这条公交线路有二十个站。", "target_word": "公交线路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家门口有三条公交线路。", "target_word": "公交线路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哪条公交线路能到火车站？", "target_word": "公交线路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在手机上查公交线路。", "target_word": "公交线路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条公交线路从早上六点开始。", "target_word": "公交线路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条公交线路要走四十分钟。", "target_word": "公交线路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天，这条公交线路人特别多。", "target_word": "公交线路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们讲了坐哪条公交线路去公园。", "target_word": "公交线路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条公交线路经过一家大医院。", "target_word": "公交线路", "complexity_tier": "T3", "furigana": "zhè tiáo gōngjiāo xiànlù jīngguò yī jiā dà yīyuàn", "sentence_source": "generated"}, {"text": "我不熟悉这里的公交线路，所以问了司机。", "target_word": "公交线路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条公交线路", "label": "量词"}, {"form": "公交线路图", "label": "复合"}], "register": "口语", "sense_fingerprint": "公交线路：公交车走的路线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63f12163-19cc-4b51-bb0d-63aa4777bd4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公交线路", "is_correct": true, "explanation": "公交线路：公交车走的路线，有二十个站，与句意一致。"}, {"text": "河", "is_correct": false, "explanation": "语义：河上不设站，“有二十个站”句意不通。"}, {"text": "台阶", "is_correct": false, "explanation": "搭配：“站”指车站或站点，台阶不说“有二十个站”。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：围巾不会设站点，与句意冲突。"}], "explanations": {"公交线路": "公交线路：公交车走的路线，有二十个站，与句意一致。", "河": "语义：河上不设站，“有二十个站”句意不通。", "台阶": "搭配：“站”指车站或站点，台阶不说“有二十个站”。", "围巾": "语义：围巾不会设站点，与句意冲突。"}, "sentence_index": 0, "correct_answer": "公交线路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在手机上买公交线路。", "explanation": "这里应该用〈车票〉。“买”的是票，“公交线路”指路线，不能购买。"}, {"text": "他吃了一碗公交线路，觉得很饱。", "explanation": "这里应该用〈面条〉。“吃”的是食物，“公交线路”指路线，不能吃。"}, {"text": "这条公交线路断了，屋里一片黑。", "explanation": "这里应该用〈电线〉。屋里变黑是因为电线断了，“公交线路”指公交车走的路线，与屋里的电无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公交线路", "is_correct": true, "explanation": "公交线路：公交车走的路线，下雨天这条线路人特别多，句意通顺。"}, {"text": "河", "is_correct": false, "explanation": "语义：河不会因为下雨而人特别多，句意不通。"}, {"text": "围栏", "is_correct": false, "explanation": "语义：围栏不是人聚集的地方，句意不通。"}, {"text": "项链", "is_correct": false, "explanation": "搭配：“人特别多”只说地点，不说饰品，项链不能搭配“人特别多”。"}], "explanations": {"公交线路": "公交线路：公交车走的路线，下雨天这条线路人特别多，句意通顺。", "河": "语义：河不会因为下雨而人特别多，句意不通。", "围栏": "语义：围栏不是人聚集的地方，句意不通。", "项链": "搭配：“人特别多”只说地点，不说饰品，项链不能搭配“人特别多”。"}, "sentence_index": 6, "correct_answer": "公交线路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天在门口等公交线路，等了很久。", "explanation": "这里应该用〈公交车〉。“等”等的是车，“公交线路”指路线，不能等待。"}, {"text": "我不熟悉这里的路，所以请公交线路带我去。", "explanation": "这里应该用〈司机〉。“带路”需要人，“公交线路”是路线，不能带人。"}, {"text": "车上人太多，公交线路里很挤。", "explanation": "这里应该用〈车厢〉。“里很挤”指车内空间，“公交线路”是路线，不是空间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小区附近有一辆公交线路，去地铁站很近。", "corrected_sentence": "这个小区附近有一条公交线路，去地铁站很近。", "error_description": "量词错误：“线路”应用“条”，“辆”用于车辆，应说“一条公交线路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这条公交线路记上来了。", "corrected_sentence": "我把这条公交线路记下来了。", "error_description": "结果补语错误：“记”后应用“下来”（表示把内容留存下来），“上来”不搭配，应说“我把这条公交线路记下来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
