INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23212, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们想好房子、道路、公园建在哪里，让城市变得更好。", "primary_collocate": null, "pronunciation": "chéng shì guī huà", "ipa": "tʂʰɤŋ˧˥ ʂɻ̩˥˩ kweɪ˥ xwa˥˩", "syllable_count": 4, "sentences": [{"text": "好的城市规划能让交通更方便。", "target_word": "城市规划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市规划里有三个新公园。", "target_word": "城市规划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府公布了新的城市规划。", "target_word": "城市规划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学习城市规划，想设计漂亮的城市。", "target_word": "城市规划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市规划要考虑道路和房子。", "target_word": "城市规划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市规划做得不好，路上常常堵车。", "target_word": "城市规划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了城市规划的知识。", "target_word": "城市规划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据城市规划，这里会建一所学校。", "target_word": "城市规划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图是城市规划的地图。", "target_word": "城市规划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了好的城市规划，孩子们能在公园玩。", "target_word": "城市规划", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "城市规划师", "label": "复合"}], "register": "中性", "sense_fingerprint": "提前安排城市里房子、道路、公园的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0457a638-19e5-4662-9085-4b0c62c030be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23212, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "城市规划", "is_correct": true, "explanation": "“城市规划”指城市布局的安排，与“让交通更方便”的因果相合。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园本身不能“让交通更方便”，句子的因果关系不通。"}, {"text": "食品", "is_correct": false, "explanation": "语义：食品与交通无关，无法作为“让交通更方便”的原因。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“感情”不能作为“让交通更方便”的主语，此处应说城市层面的安排。"}], "explanations": {"城市规划": "“城市规划”指城市布局的安排，与“让交通更方便”的因果相合。", "公园": "语义：公园本身不能“让交通更方便”，句子的因果关系不通。", "食品": "语义：食品与交通无关，无法作为“让交通更方便”的原因。", "感情": "搭配：“感情”不能作为“让交通更方便”的主语，此处应说城市层面的安排。"}, "sentence_index": 0, "correct_answer": "城市规划"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的城市规划很清楚：先上大学，再找工作。", "explanation": "这里应该用〈人生规划〉。城市规划指城市的布局与建设，说个人的安排要用“人生规划”。"}, {"text": "我的城市规划很清楚。", "explanation": "这里应该用〈人生规划〉。城市规划指城市的布局与建设，说个人的安排要用“人生规划”。"}, {"text": "这个房间的城市规划很合理。", "explanation": "这里应该用〈布局〉。“城市规划”只用于城市层面的安排，房间内的安排应说布局。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "城市规划", "is_correct": true, "explanation": "“城市规划”是可以讲授的学科内容，与“讲了……的知识”相合。"}, {"text": "哭声", "is_correct": false, "explanation": "语义：“哭声”不是可以讲授的知识领域，句子无法成立。"}, {"text": "笑声", "is_correct": false, "explanation": "语义：“笑声”不能作为讲授的知识内容。"}, {"text": "脚步", "is_correct": false, "explanation": "配价：“讲”要求讲授的内容是知识或学科，“脚步”不能充当这一宾语。"}], "explanations": {"城市规划": "“城市规划”是可以讲授的学科内容，与“讲了……的知识”相合。", "哭声": "语义：“哭声”不是可以讲授的知识领域，句子无法成立。", "笑声": "语义：“笑声”不能作为讲授的知识内容。", "脚步": "配价：“讲”要求讲授的内容是知识或学科，“脚步”不能充当这一宾语。"}, "sentence_index": 6, "correct_answer": "城市规划"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的旅行城市规划很完整。", "explanation": "这里应该用〈计划〉。旅行的安排说“计划”，“城市规划”只用于城市。"}, {"text": "这次活动是他城市规划的。", "explanation": "这里应该用〈策划〉。组织活动的安排说“策划”，不能说“城市规划”。"}, {"text": "这本书的城市规划很整齐。", "explanation": "这里应该用〈排版〉。书页的版式安排说“排版”，不能说“城市规划”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项城市规划们很详细。", "corrected_sentence": "这项城市规划很详细。", "error_description": "错误：多加了“们”。正确：去掉“们”。“们”只用于指人的名词，“城市规划”不能加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一名城市规划。", "corrected_sentence": "他是一名城市规划师。", "error_description": "错误：漏了“师”。正确：“城市规划师”。“城市规划”指规划工作，指人要说“城市规划师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
