INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23222, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "汽车是一种可以坐人的车，它用轮子跑。", "primary_collocate": null, "pronunciation": "qì chē", "ipa": "tɕʰi˥˩ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "爸爸每天开汽车去公司上班。", "target_word": "汽车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车的轮子坏了，我们只好在路边等人来帮忙。", "target_word": "汽车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆汽车很新，坐着非常舒服。", "target_word": "汽车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车没有油就不能跑了。", "target_word": "汽车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐汽车去外地，明天回来。", "target_word": "汽车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "马路上有很多汽车，过马路要小心。", "target_word": "汽车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想买一辆便宜的汽车，可是钱不够。", "target_word": "汽车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把汽车停在学校门口，然后走进了教室。", "target_word": "汽车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车开得太快很危险。", "target_word": "汽车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我小时候没坐过汽车，第一次坐很害怕。", "target_word": "汽车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "汽车站", "label": "复合"}, {"form": "公共汽车", "label": "复合"}, {"form": "汽車", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用轮子行驶、可以载人的机动车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebcaa39-880a-494e-9b7b-c3edf04ba17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23222, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汽车", "is_correct": true, "explanation": "汽车：可以开的交通工具，符合“开……去公司上班”的句意。"}, {"text": "玩笑", "is_correct": false, "explanation": "语义：“开玩笑”的“开”不表示驾驶，“玩笑”不能用来去公司。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“开”可以接“窗户”，但“开窗户去公司”无法成立，与“去公司上班”冲突。"}, {"text": "灯", "is_correct": false, "explanation": "语义：“开灯”是打开照明，不能用来去公司上班。"}], "explanations": {"汽车": "汽车：可以开的交通工具，符合“开……去公司上班”的句意。", "玩笑": "语义：“开玩笑”的“开”不表示驾驶，“玩笑”不能用来去公司。", "窗户": "搭配：“开”可以接“窗户”，但“开窗户去公司”无法成立，与“去公司上班”冲突。", "灯": "语义：“开灯”是打开照明，不能用来去公司上班。"}, "sentence_index": 0, "correct_answer": "汽车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门口停着一只汽车，是爸爸的。", "explanation": "量词错误：汽车应该用〈辆〉。“只”多用于动物，不用来数汽车。"}, {"text": "我们家买了一本汽车。", "explanation": "量词错误：汽车应该用〈辆〉。“本”用于书册，不用来数汽车。"}, {"text": "院子里停着一条汽车。", "explanation": "量词错误：汽车应该用〈辆〉。“条”多用于细长的东西，不用来数汽车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23222, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汽车", "is_correct": true, "explanation": "汽车：可以购买的交通工具，符合“买一辆便宜的……”的句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被购买，“买一辆便宜的空气”句意不通。"}, {"text": "朋友", "is_correct": false, "explanation": "搭配：“买”一般不接“朋友”，“买一辆便宜的朋友”不成立。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事不是可以用“一辆”计量、用钱购买的东西，与句意冲突。"}], "explanations": {"汽车": "汽车：可以购买的交通工具，符合“买一辆便宜的……”的句意。", "空气": "语义：空气不能被购买，“买一辆便宜的空气”句意不通。", "朋友": "搭配：“买”一般不接“朋友”，“买一辆便宜的朋友”不成立。", "故事": "语义：故事不是可以用“一辆”计量、用钱购买的东西，与句意冲突。"}, "sentence_index": 6, "correct_answer": "汽车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天骑汽车去上学。", "explanation": "这里应该用〈自行车〉。“骑”用于自行车、摩托车，不能用于汽车，汽车要用“坐”或“开”。"}, {"text": "我们打汽车去机场吧。", "explanation": "这里应该用〈出租车〉。“打”用于出租车（打车），汽车不能说“打”，要用“坐”。"}, {"text": "奶奶骑汽车去买菜。", "explanation": "这里应该用〈三轮车〉。“骑”用于三轮车、自行车，汽车要用“坐”或“开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把汽车走开了。", "corrected_sentence": "他把汽车开走了。", "error_description": "错误：“走开”表示人离开，不能带“汽车”作宾语。正确：表示车被开走，补语应是“开走”，写作“把汽车开走了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他坐一只汽车去外地了。", "corrected_sentence": "他坐一辆汽车去外地了。", "error_description": "错误：汽车应使用量词“辆”，不能用“只”。正确形式是“一辆汽车”，应写作“他坐一辆汽车去外地了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
