INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23224, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "骑就是坐在马或自行车上，让它带着你走。", "primary_collocate": null, "pronunciation": "qí", "ipa": "tɕʰi˧˥", "syllable_count": 1, "sentences": [{"text": "我想骑马去山里看看。", "target_word": "骑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她每天骑自行车送孩子上学。", "target_word": "骑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑自行车比走路快，也不用等公交车。", "target_word": "骑", "complexity_tier": "T3", "furigana": "qí", "sentence_source": "generated"}, {"text": "你会骑自行车吗？", "target_word": "骑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他骑上马，很快就走远了。", "target_word": "骑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个小孩骑着一辆红色的小自行车。", "target_word": "骑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天骑摩托车不太安全。", "target_word": "骑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我骑过一次马，觉得很有意思。", "target_word": "骑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥骑得很快，我跟不上他。", "target_word": "骑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里可以骑自行车，也可以走路。", "target_word": "骑", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "骑了", "label": "体标（了）"}, {"form": "骑过", "label": "体标（过）"}, {"form": "骑着", "label": "体标（着）"}], "register": "中性", "sense_fingerprint": "坐在马或车上让它载着人前进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8e71cc5-9b9d-4321-b5b4-b169b9601a86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23224, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "骑", "is_correct": true, "explanation": "正确：「骑」读 qí，指坐在马或车上让它载着前进。"}, {"text": "起", "is_correct": false, "explanation": "qǐ（第三声）与 qí（第二声）声调不同，意思是起来、起身。"}, {"text": "气", "is_correct": false, "explanation": "qì（第四声）与 qí（第二声）声调不同，意思是气体、气息。"}, {"text": "七", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，意思是数字七。"}, {"text": "期", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，意思是期限、日期。"}], "explanations": {"骑": "正确：「骑」读 qí，指坐在马或车上让它载着前进。", "起": "qǐ（第三声）与 qí（第二声）声调不同，意思是起来、起身。", "气": "qì（第四声）与 qí（第二声）声调不同，意思是气体、气息。", "七": "qī（第一声）与 qí（第二声）声调不同，意思是数字七。", "期": "qī（第一声）与 qí（第二声）声调不同，意思是期限、日期。"}, "sentence_index": null, "correct_answer": "骑"}, "level_3": {"options": [{"text": "骑", "is_correct": true, "explanation": "正确：「骑马去山里」指坐在马背上前往，句意通顺。"}, {"text": "坐", "is_correct": false, "explanation": "搭配：「坐马」不说，骑马才指坐在马背上前进。"}, {"text": "抬", "is_correct": false, "explanation": "语义：「抬」是用手或肩承载，不能表示坐在马背上前行。"}, {"text": "修", "is_correct": false, "explanation": "语义：「修」是修理，与「去山里看看」的出行无关。"}], "explanations": {"骑": "正确：「骑马去山里」指坐在马背上前往，句意通顺。", "坐": "搭配：「坐马」不说，骑马才指坐在马背上前进。", "抬": "语义：「抬」是用手或肩承载，不能表示坐在马背上前行。", "修": "语义：「修」是修理，与「去山里看看」的出行无关。"}, "sentence_index": 0, "correct_answer": "骑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你会骑火车吗？", "explanation": "这里应该用〈坐〉。火车是坐的，骑只用于跨坐在马或车上。"}, {"text": "我们骑飞机去北京。", "explanation": "这里应该用〈乘〉。飞机是乘坐的，不能骑，骑只用于跨坐在马或车上。"}, {"text": "我骑了一次电梯。", "explanation": "这里应该用〈坐〉。电梯不能骑，骑指跨坐在马或车上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '090bd7af-56cc-4348-851b-eb7c6ba1a89e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23224, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "骑", "is_correct": true, "explanation": "正确：「骑」读 qí，指跨坐在马或车上前行。"}, {"text": "启", "is_correct": false, "explanation": "qǐ（第三声）与 qí（第二声）声调不同，意思是开启、启发。"}, {"text": "汽", "is_correct": false, "explanation": "qì（第四声）与 qí（第二声）声调不同，意思是蒸汽、汽车的汽。"}, {"text": "欺", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，意思是欺负。"}, {"text": "漆", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，意思是油漆。"}], "explanations": {"骑": "正确：「骑」读 qí，指跨坐在马或车上前行。", "启": "qǐ（第三声）与 qí（第二声）声调不同，意思是开启、启发。", "汽": "qì（第四声）与 qí（第二声）声调不同，意思是蒸汽、汽车的汽。", "欺": "qī（第一声）与 qí（第二声）声调不同，意思是欺负。", "漆": "qī（第一声）与 qí（第二声）声调不同，意思是油漆。"}, "sentence_index": null, "correct_answer": "骑"}, "level_3": {"options": [{"text": "骑", "is_correct": true, "explanation": "正确：「下雨天骑摩托车」指骑车上路，与「不太安全」相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能以摩托车为对象，句子说不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能以摩托车为对象，句子说不通。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”不能以摩托车为对象，句子说不通。"}], "explanations": {"骑": "正确：「下雨天骑摩托车」指骑车上路，与「不太安全」相符。", "吃": "语义：“吃”不能以摩托车为对象，句子说不通。", "唱": "语义：“唱”不能以摩托车为对象，句子说不通。", "写": "语义：“写”不能以摩托车为对象，句子说不通。"}, "sentence_index": 6, "correct_answer": "骑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天骑公交车去公园。", "explanation": "这里应该用〈坐〉。公交车是坐的，骑只用于跨坐在马或车上。"}, {"text": "我们可以骑电脑去学校，也可以走路。", "explanation": "这里应该用〈背〉。电脑不能被骑，应说背电脑去学校。"}, {"text": "他骑着鸡去菜市场。", "explanation": "这里应该用〈提〉。鸡不能被骑，骑只用于人跨坐在马或车上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '090bd7af-56cc-4348-851b-eb7c6ba1a89e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他骑着了马去山里。", "corrected_sentence": "他骑了马去山里。", "error_description": "错误在于体标「着」和「了」叠用，同一动词「骑」上不能同时带两者。应只保留「了」，说「骑了马」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '090bd7af-56cc-4348-851b-eb7c6ba1a89e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
