INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23226, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "丑陋", "is_correct": true, "explanation": "丑陋与美丽意思相反，指样子难看。"}, {"text": "高大", "is_correct": false, "explanation": "高大指身材或体积大，与美丽没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮指光线充足或颜色亮，与美丽没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静指没有声音或动静，与美丽没有反义关系。"}], "correct_answer": "丑陋", "explanations": {"丑陋": "丑陋与美丽意思相反，指样子难看。", "高大": "高大指身材或体积大，与美丽没有反义关系。", "明亮": "明亮指光线充足或颜色亮，与美丽没有反义关系。", "安静": "安静指没有声音或动静，与美丽没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
