INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23226, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很好看，让人看了很开心。", "primary_collocate": null, "pronunciation": "měi lì", "ipa": "meɪ̯˨˩˦ li˥˩", "syllable_count": 2, "sentences": [{"text": "这座小城非常美丽。", "target_word": "美丽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春天的公园很美丽。", "target_word": "美丽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她有一双美丽的眼睛。", "target_word": "美丽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山上的风景美丽极了。", "target_word": "美丽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们住在一个美丽的海边小镇。", "target_word": "美丽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天的夜晚，天上的星星特别美丽。", "target_word": "美丽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她穿着一条美丽的红裙子，站在花园里。", "target_word": "美丽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有很多美丽的湖，每年都有人来玩。", "target_word": "美丽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，美丽的东西不一定贵。", "target_word": "美丽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨停了，天空出现了一道美丽的彩虹。", "target_word": "美丽", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "美丽的", "label": "定语形式"}, {"form": "更美丽", "label": "比较形式"}, {"form": "最美丽", "label": "最高级形式"}, {"form": "美丽动人", "label": "复合词"}], "register": "中性", "sense_fingerprint": "形容人或景物好看、让人喜爱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed69058d-24aa-4c07-bc40-36884250d128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23226, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "美丽", "is_correct": true, "explanation": "美丽 měi lì，形容好看、让人喜爱，是正确答案。"}, {"text": "魅力", "is_correct": false, "explanation": "魅力 mèilì：mèi（第四声）与 měi（第三声）声调不同，意思是吸引人的力量。"}, {"text": "米粒", "is_correct": false, "explanation": "米粒 mǐlì：mǐ 与 měi 韵母不同，意思是大米的颗粒。"}, {"text": "伟力", "is_correct": false, "explanation": "伟力 wěilì：wěi 与 měi 声母不同，意思是巨大的力量，偏书面用语。"}], "explanations": {"美丽": "美丽 měi lì，形容好看、让人喜爱，是正确答案。", "魅力": "魅力 mèilì：mèi（第四声）与 měi（第三声）声调不同，意思是吸引人的力量。", "米粒": "米粒 mǐlì：mǐ 与 měi 韵母不同，意思是大米的颗粒。", "伟力": "伟力 wěilì：wěi 与 měi 声母不同，意思是巨大的力量，偏书面用语。"}, "sentence_index": null, "correct_answer": "美丽"}, "level_3": {"options": [{"text": "美丽", "is_correct": true, "explanation": "美丽形容小城好看，与“非常”搭配，符合句意。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：聪明形容人的头脑，城市不能用来形容聪明。"}, {"text": "勤快", "is_correct": false, "explanation": "搭配：勤快形容人的做事态度，不能用来形容小城。"}, {"text": "善良", "is_correct": false, "explanation": "语义：善良形容人的品德，小城不能用这个词来描述。"}], "explanations": {"美丽": "美丽形容小城好看，与“非常”搭配，符合句意。", "聪明": "语义：聪明形容人的头脑，城市不能用来形容聪明。", "勤快": "搭配：勤快形容人的做事态度，不能用来形容小城。", "善良": "语义：善良形容人的品德，小城不能用这个词来描述。"}, "sentence_index": 0, "correct_answer": "美丽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的力气很美丽。", "explanation": "这里应该用〈大〉。美丽形容外表或景色，不能用来形容力气。"}, {"text": "这道菜的味道很美丽。", "explanation": "这里应该用〈鲜美〉。美丽形容外表好看，不能用来形容味道。"}, {"text": "这次考试很美丽。", "explanation": "这里应该用〈难〉。美丽形容外表或景色，不能用来形容考试的难易。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23226, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美丽", "is_correct": true, "explanation": "美丽修饰红裙子，表示好看，符合句意。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：懒惰形容人的性格，不能用来修饰红裙子。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：幽默形容人说话风趣，不能修饰衣服。"}, {"text": "诚实", "is_correct": false, "explanation": "搭配：诚实形容人的品德，不能用来修饰红裙子。"}], "explanations": {"美丽": "美丽修饰红裙子，表示好看，符合句意。", "懒惰": "语义：懒惰形容人的性格，不能用来修饰红裙子。", "幽默": "语义：幽默形容人说话风趣，不能修饰衣服。", "诚实": "搭配：诚实形容人的品德，不能用来修饰红裙子。"}, "sentence_index": 6, "correct_answer": "美丽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的速度很美丽。", "explanation": "这里应该用〈快〉。美丽形容外表好看，不能用来形容速度。"}, {"text": "他的数学成绩很美丽。", "explanation": "这里应该用〈好〉。美丽形容外表或景物，不能用来形容成绩。"}, {"text": "他学习很美丽。", "explanation": "这里应该用〈认真〉。美丽形容外表或景物，不能用来形容学习的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个花园非常很美丽。", "corrected_sentence": "这个花园非常美丽。", "error_description": "错误：“非常很美丽”；正确：“非常美丽”。“非常”和“很”都是程度副词，不能叠用来修饰同一个形容词，只用其中一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有一条美丽地红裙子。", "corrected_sentence": "她有一条美丽的红裙子。", "error_description": "错误：“美丽”修饰名词“红裙子”时要用“的”，不能用“地”。应说“美丽的红裙子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
