INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23228, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家都能乘坐的公交车、地铁等交通工具和服务。", "primary_collocate": null, "pronunciation": "gōng gòng jiāo tōng", "ipa": "kʊŋ⁵⁵ kʊŋ⁵¹ tɕjɑʊ̯⁵⁵ tʰʊŋ⁵⁵", "syllable_count": 4, "sentences": [{"text": "我每天坐公共交通上班。", "target_word": "公共交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的公共交通很方便。", "target_word": "公共交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐公共交通比开车便宜。", "target_word": "公共交通", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他家附近没有公共交通。", "target_word": "公共交通", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "为了环保，我们多用公共交通。", "target_word": "公共交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市里在发展公共交通，新地铁线开通了。", "target_word": "公共交通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共交通在早上特别拥挤。", "target_word": "公共交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人坐公共交通可以半价。", "target_word": "公共交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天，公共交通很慢。", "target_word": "公共交通", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她不会开车，只能靠公共交通。", "target_word": "公共交通", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "公交车、地铁等大家都能使用的交通", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dd17ffc-a76b-42f7-bbad-b8985cc3d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23228, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公共交通", "is_correct": true, "explanation": "正确：“坐公共交通上班”是常见说法，指公交车、地铁等大家都能用的交通。"}, {"text": "公共场所", "is_correct": false, "explanation": "搭配：“坐”要接交通工具，公共场所不能用来乘坐。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以乘坐的东西，句意不通。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不能用来乘坐上班，句意荒谬。"}], "explanations": {"公共交通": "正确：“坐公共交通上班”是常见说法，指公交车、地铁等大家都能用的交通。", "公共场所": "搭配：“坐”要接交通工具，公共场所不能用来乘坐。", "空气": "语义：空气不是可以乘坐的东西，句意不通。", "花园": "语义：花园不能用来乘坐上班，句意荒谬。"}, "sentence_index": 0, "correct_answer": "公共交通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆公共交通很干净，司机也很热情。", "explanation": "这里应该用〈公交车〉。公共交通指整个交通系统，不是一辆车，不能用“辆”来计量。"}, {"text": "我们买了一台公共交通。", "explanation": "这里“一台公共交通”用错了。公共交通是整个交通系统，不是可以买的机器，可以说“买了一张〈公交卡〉”。"}, {"text": "我们在公共交通等车。", "explanation": "这里应该用〈公交站〉。公共交通是系统，不是可以停留等候的地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23228, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公共交通", "is_correct": true, "explanation": "正确：“公共交通在早上特别拥挤”说的是大家都用的交通在早高峰时很挤。"}, {"text": "沙漠", "is_correct": false, "explanation": "搭配：“拥挤”说的是人或车多，沙漠不会在早上拥挤。"}, {"text": "空房间", "is_correct": false, "explanation": "语义：房间空，与“拥挤”相反，句意矛盾。"}, {"text": "无人岛", "is_correct": false, "explanation": "语义：无人岛本身没有人，怎么会拥挤，句意矛盾。"}], "explanations": {"公共交通": "正确：“公共交通在早上特别拥挤”说的是大家都用的交通在早高峰时很挤。", "沙漠": "搭配：“拥挤”说的是人或车多，沙漠不会在早上拥挤。", "空房间": "语义：房间空，与“拥挤”相反，句意矛盾。", "无人岛": "语义：无人岛本身没有人，怎么会拥挤，句意矛盾。"}, "sentence_index": 6, "correct_answer": "公共交通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她打了公共交通去机场。", "explanation": "这里应该用〈出租车〉。“打”用于具体的车辆，公共交通是系统，不能“打”。"}, {"text": "她坐了一条公共交通去上班。", "explanation": "这里“一条”用错了。公共交通是整个系统，不能用“条”计量，应去掉量词，说“她坐公共交通去上班”。"}, {"text": "旅客在公共交通休息。", "explanation": "这里应该用〈候车室〉。公共交通是系统，不是可以休息的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23228, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天坐一辆公共交通去学校。", "corrected_sentence": "我每天坐公共交通去学校。", "error_description": "错误形式：“一辆公共交通”。正确形式：“公共交通”。公共交通指整个交通系统，不能用“辆”计量，去掉量词即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23228, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇的一个公共交通不太方便。", "corrected_sentence": "这个小镇的公共交通不太方便。", "error_description": "错误形式：“一个公共交通”。正确形式：“公共交通”。公共交通是整体概念，不能用量词“个”计量，应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
