INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23230, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "自行车有两个轮子，人坐在上面用脚蹬着走。", "primary_collocate": null, "pronunciation": "zì xíng chē", "ipa": "tsz̩˥˩ ɕiŋ˧˥ ʈʂʰɤ˥", "syllable_count": 3, "sentences": [{"text": "这辆红色的自行车很漂亮。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟刚学会骑自行车，高兴极了。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自行车没有发动机，要用脚蹬。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一辆新自行车。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑着自行车去超市买菜。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自行车的链条掉了，我不能骑了。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有很多人骑自行车上班。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我给自行车打点气。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的自行车上有一个小篮子。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我骑自行车摔倒过一次。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "电动自行车", "label": "复合"}, {"form": "自行车道", "label": "复合"}, {"form": "自行車", "label": "繁体"}], "register": "通用", "sense_fingerprint": "人坐在上面用脚蹬着走的两轮车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27dbee67-57fb-4045-a9fe-c7c814b0d92e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23230, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自行车", "is_correct": true, "explanation": "正确。“辆”用于车，“红色的自行车”很漂亮，符合句意。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：量词“辆”只用于车辆，不能说“这辆红色的手机”。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：量词“辆”只用于车辆，不能修饰房子。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫是动物，不是车辆，与“这辆红色的……”的语境不合。"}], "explanations": {"自行车": "正确。“辆”用于车，“红色的自行车”很漂亮，符合句意。", "手机": "搭配：量词“辆”只用于车辆，不能说“这辆红色的手机”。", "房子": "搭配：量词“辆”只用于车辆，不能修饰房子。", "猫": "语义：猫是动物，不是车辆，与“这辆红色的……”的语境不合。"}, "sentence_index": 0, "correct_answer": "自行车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天打自行车去学校。", "explanation": "这里应该用〈骑〉。“打”不能用于自行车，骑自行车要说“骑”。"}, {"text": "弟弟开自行车去公园玩。", "explanation": "这里应该用〈骑〉。自行车靠脚蹬，要用“骑”，“开”用于汽车等机动车。"}, {"text": "妈妈每天给自行车洗澡。", "explanation": "这里应该用〈擦〉。“洗澡”只用于人或动物，清洁自行车要用“擦”或“洗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23230, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自行车", "is_correct": true, "explanation": "正确。“骑自行车上班”是常见说法，符合“路上有很多人”的语境。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“骑”不能用于汽车，应说“开车”或“坐汽车”。"}, {"text": "轮船", "is_correct": false, "explanation": "语义：轮船在水上航行，不在路上行驶，与“路上”的语境矛盾。"}, {"text": "火车", "is_correct": false, "explanation": "搭配：“骑”不能用于火车，应说“坐火车”。"}], "explanations": {"自行车": "正确。“骑自行车上班”是常见说法，符合“路上有很多人”的语境。", "汽车": "搭配：“骑”不能用于汽车，应说“开车”或“坐汽车”。", "轮船": "语义：轮船在水上航行，不在路上行驶，与“路上”的语境矛盾。", "火车": "搭配：“骑”不能用于火车，应说“坐火车”。"}, "sentence_index": 6, "correct_answer": "自行车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把自行车开进了停车场。", "explanation": "这里应该用〈骑〉或〈推〉。“开”用于汽车等机动车，自行车要说“骑”或“推”。"}, {"text": "这辆自行车启动了好几次，都没发动起来。", "explanation": "这里应该用〈骑〉。“启动”“发动”用于有发动机的机器，自行车靠人蹬，应说“骑”。"}, {"text": "我把自行车的眼睛擦干净了。", "explanation": "这里应该用〈车灯〉。“眼睛”只用于人或动物，自行车的灯要说“车灯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "哥哥想卖一个旧自行车。", "corrected_sentence": "哥哥想卖一辆旧自行车。", "error_description": "量词错误：“自行车”的量词应为“辆”，不能说“一个自行车”。应改为“想卖一辆旧自行车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她骑在自行车去学校。", "corrected_sentence": "她骑着自行车去学校。", "error_description": "体标错误：表示动作进行的状态要用“着”，应紧接动词“骑”，说“骑着自行车去学校”；“在”后要接处所，如“骑在自行车上”，不能说“骑在自行车去学校”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
