INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23240, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人们等车或上下车的地方。", "primary_collocate": null, "pronunciation": "chē zhàn", "ipa": "tʂʰɤ˥ tʂan˥˩", "syllable_count": 2, "sentences": [{"text": "车站离我家很近，走路五分钟。", "target_word": "车站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在车站等了二十分钟，车还没来。", "target_word": "车站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个车站的人很多，每天都很热闹。", "target_word": "车站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请问，车站在哪儿？我想坐公共汽车。", "target_word": "车站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟在车站门口等我，手里拿着水。", "target_word": "车站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，大家都站在车站里等车。", "target_word": "车站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车站旁边有一家小店，卖早饭和水。", "target_word": "车站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我到车站的时候，最后一班车已经走了。", "target_word": "车站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸每天早上把我送到车站，再去上班。", "target_word": "车站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小城的车站很旧，但是很干净。", "target_word": "车站", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "火车站", "label": "复合"}, {"form": "汽车站", "label": "复合"}, {"form": "車站", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：公共交通中人们等车、上车、下车的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37088c36-b988-4c59-bd87-98a844545e6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23240, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "车站", "is_correct": true, "explanation": "“车站”是人们等车的地方，“离我家很近，走路五分钟”语义通顺。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”是教室里的物件，不能说“离我家很近，走路五分钟”。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是可以走路到达的地方，与“走路五分钟”冲突。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“手机”不是地点，不能与“离我家很近，走路五分钟”搭配。"}], "explanations": {"车站": "“车站”是人们等车的地方，“离我家很近，走路五分钟”语义通顺。", "黑板": "语义：“黑板”是教室里的物件，不能说“离我家很近，走路五分钟”。", "月亮": "语义：月亮不是可以走路到达的地方，与“走路五分钟”冲突。", "手机": "搭配：“手机”不是地点，不能与“离我家很近，走路五分钟”搭配。"}, "sentence_index": 0, "correct_answer": "车站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天坐车站去上班。", "explanation": "这里应该用〈汽车〉。车站是地点，不是交通工具；坐的应是“汽车”。"}, {"text": "轮船每天都停靠在车站。", "explanation": "这里应该用〈码头〉。车站供火车、汽车停靠和乘降，轮船停靠要在码头。"}, {"text": "飞机从车站起飞。", "explanation": "这里应该用〈机场〉。车站是乘坐火车、汽车的地方，飞机起飞要在机场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "车站", "is_correct": true, "explanation": "“车站”是地点，“旁边有一家小店，卖早饭和水”语境通顺。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：衣服不是地点，不能说它“旁边有一家小店”。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是可以作为方位参照的地点，句子不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“雨伞”不能作为方位参照的地点，与“旁边有一家小店”搭配不当。"}], "explanations": {"车站": "“车站”是地点，“旁边有一家小店，卖早饭和水”语境通顺。", "衣服": "语义：衣服不是地点，不能说它“旁边有一家小店”。", "课本": "语义：课本不是可以作为方位参照的地点，句子不通。", "雨伞": "搭配：“雨伞”不能作为方位参照的地点，与“旁边有一家小店”搭配不当。"}, "sentence_index": 6, "correct_answer": "车站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小城的车站开得很快。", "explanation": "这里应该用〈火车〉。车站是地点，不会开动；开得很快的是火车。"}, {"text": "这个小城的车站每天给病人看病。", "explanation": "这里应该用〈医院〉。车站是等车、上下车的地方，看病要去医院。"}, {"text": "这个小城的车站每天都在上课。", "explanation": "这里应该用〈学校〉。车站是等车、上下车的地方，不能用来上课；上课要在学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我车站等车。", "corrected_sentence": "我在车站等车。", "error_description": "错误：“我车站等车”。正确：“我在车站等车”。表示地点时，“车站”前要加介词“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在一辆车站等他。", "corrected_sentence": "我在车站等他。", "error_description": "错误：“一辆车站”。正确：“车站”。车站是地点，不能用车辆的量词“辆”来计量，这里直接说“车站”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
